/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080121-6","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"区民委員会","time":"午後１時０３分～午後４時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区民カードと住基カードの発行枚数と、大体どのような年齢構成の方がそれぞれ登録しているのかお伺いしたいと思います。","respondent":"上川内戸籍住民課長","answer":"平成１７年が１,２９７枚、平成１８年度が１,９３４枚、平成１９年度は１２月末で１,７２４枚となっています。品川区証明書の交付、当時住基カードの発行されるのが先のことということがありまして、高齢者が多く取得されているという状況にあります。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"住基カードと区民カードを重複して取得している人がいるのかお伺いいたします。","respondent":"上川内戸籍住民課長","answer":"区民カード所持者のうち約１割弱の方が住基カードも重複して持っております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"住基ネットの本格稼働の前に発行された区民カードということですけれども、区民カードの新規登録の激減と住基カードの普及の増加の相関関係といいますか、それは特に連動するものなのかどうかお伺いしたいと思います。","respondent":"上川内戸籍住民課長","answer":"区民カードが平成１５年度に４,０７２枚取得されたということは、高齢者の方たちが本人確認の書類として区民カードしかなかったということです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"確認","question":"重複しているのは１割だけという話だったので、関係はそんなにないのではないかという感想です。住基カードを持つのは抵抗がありますけれども、その辺のことはどのようにすればいいのかお伺いしたいと思います。","respondent":"上川内戸籍住民課長","answer":"ただし、区民カードは品川区役所の中でしか通用しません。住基カードは全国どこでも通用します」と言うと、ほとんどの方が「住基カードにします」という現状があるという認識です。","id":"exchange-004"},{"speaker":"飯沼副委員長","kind":"質問","question":"住基カードは１,０００円でしたか。先ほど来、区民カードで満足されている方が住基カードしか今後は得られないとなった場合の利便性についてはどうなのか尋ねました。","respondent":"上川内戸籍住民課長","answer":"もしカードがない場合、ほかのもので代用していますので、証明書類がないからといって届出ができないということはありません。キャッシュカードだとか、そういうことを聞きながらやっておりますので、カードがないからといって不都合なことはないと考えています。","id":"exchange-005"},{"speaker":"飯沼副委員長","kind":"質問","question":"家庭の主婦とか高齢者の方にとっては大事なのかなと思っていましたけれども、今のご説明からすると、不利益にはならないということでしょうか。区民の皆さんにとって不利益はないと受けとめてよろしいか尋ねました。","respondent":"上川内戸籍住民課長","answer":"そのとおりです。","id":"exchange-006"}]},{"id":"topic-02","title":"番、行政視察の報告書","agenda":"番、行政視察の報告書","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問","question":"オークションの件ですけれども、手数料はどのようになっているのか尋ねました。","respondent":"武内税務課長","answer":"区のほうの手数料は無料です。売れた物件、つまり滞納者の負担ですので、区の持ち出しはないと考えていただいてよろしいかと思います。","id":"exchange-007"},{"speaker":"飯沼副委員長","kind":"質問","question":"伝統の技と味のところですけれども、チラシの裏面に実演ということが書いてありますけれども、実演にあたっての準備とか材料に関して、区から補助が出ているのかどうか、その点だけお伺いしたいと思います。","respondent":"金子産業振興課長","answer":"技のほうに関しましては、出店について委託の契約をしておりまして、委託料の中で賄っているのではないかと考えています。味のほうについては、特に私どものほうでは用意しておりませんので、当日販売する中で出店者のほうが工面しているのかと考えております。","id":"exchange-008"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"報告のところは口頭だけでは書き切れないので、ぜひ簡単なものでいいので資料をつけてほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/798229?Template=document&Id=2506#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":6924,"voices":33}},{"id":"h20-20080121-7","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"厚生委員会","time":"午後１時０３分～午後２時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうことであれば、計画の設計図が全然できていない状況で今日出せないということなのでしょうか、そこが１点。区民の親御さんたちから大きな期待があったわけですけれども、これが一体どうなっていくのかということについても教えてほしいと求めました。","respondent":"高橋幼保一元担当課長","answer":"基本設計の部分から変更になったことを、まずはこの委員会で報告しなければならないということで、中止になったという報告です。それから、五反田地域にできる私立保育園等も考えますと、幼保一体施設を予定していた部分の代替は可能ではないかと考えているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、平塚幼稚園があるわけですから、それはどうなるのか、具体的にどうなっていくのか教えてほしいと求めました。これがどこで、いつ決まったことなのかという、基本的なところをもう１回教えてほしいと求めました。","respondent":"古川児童保健事業部長","answer":"私どもはこの基本設計というのは当然実施設計に高めていって、当然私どもも考えてございましたし、責任を持って当委員会にもご説明申し上げました。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それをするにはあまりにもコストが高過ぎるという、そういうスペース上の問題で幼保一体施設は併設が困難ということで、今回中止になったと。とにかく認可保育園に対しては地域の中で高い要望がありまして、部長が言われたように、地域で増設していただくように要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"須藤委員","kind":"質問","question":"我々は今日もこれからいろいろなところへ顔を出していったときに、何でですかという話になる。ですから、そういったことが、後でまちに誤った変な話が出てこないようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"堺委員","kind":"質問・要望","question":"ぜひ成功させていただきたいという思いがありますので、そういう意味で、事前にきちんと対応しておいていただきたいなと。そこで、でき得る限り早く実現するように取り組んでいただきたいと、このことを申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"本間委員","kind":"質問・要望","question":"平成２２年度中に開設という部分の、平成２０年度から２年間の分をどうしていくのかということでございまして、これは問題がどうかなです。今、どうか幼保一元化の教育は大事なことですが、そして早期な対応方を着々と進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"宮崎副委員長","kind":"意見","question":"所管が違うのかもしれませんけれども、荏原西地区の学校のイメージをどのように描いていたのか。スポーツなどの位置づけがどうだったのか、それに変更があったのかどうか、その辺のところの説明をお願いしたいと思いますとの意見を述べました。","respondent":"古川児童保健事業部長","answer":"今回の幼保一体施設を変更する中でのグラウンドの関係、所管は教育委員会ですので、私のほうでストレートにお答えするわけにはまいりません。動きだとかを検討していく中で、次の機会を何とか考えていきたいですので、スポーツというよりもグラウンドの一定規模を確保したいです。","id":"exchange-007"},{"speaker":"宮崎副委員長","kind":"質問","question":"教育委員会からいろいろ計画が変更になって、もっと広げていきたいという中での今回の話なのか、その辺のところをもう少しお伺いしたいと思います。例えば、グラウンドが広くなったということであれば、どのくらいだったのがどのくらいなのか、その辺もお伺いしたいと思います。","respondent":"古川児童保健事業部長","answer":"今回の設計を一部変更している中では、地下１階で考えてございましたけれども、この部分を今回中止した。地下１階に予定しておりました給食調理室を地上階の平屋のほうにといった、実施設計の中では基本設計を若干変更せざるを得なかったということで。","id":"exchange-008"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"今回は小中一貫校をつくる中で、３校を一つにしていくわけですから、逆にほかの学校施設を活用できるのではないかと思うんです。要望になりますけれども、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"義務づけというか、そういうものが出されたところで、こういう計画が出されているということなのでしょうか。品川区でも出ているのか、それとも品川区独自のものなのか、そのことについてもお聞かせほしいと求めました。","respondent":"上山介護保険担当課長","answer":"特に、法において義務づけ等があるわけではないです。平成９年に既に今申し上げています推進計画を策定しておりますので、その後の社会状況の変化に応じて計画をこの時点で改定したです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは、区民の声を反映させながら、区民の声を反映させるしくみがどういうしくみになっているのかお聞かせほしいと求めました。区民が傍聴できることにもなっていますけれども、こちらの推進計画改定委員会は傍聴できることになっているのかお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長、上山介護保険担当課長","answer":"各区あるいは都内に限らずそれぞれの自治体で一定程度の計画ないしは指針等を策定して、福祉のまちづくりに取り組んでいるものと認識しております。これについて２月にパブリックコメントを実施して、今後推進協議会を母体にして… 重点施設周辺におきます設置・整備につきましては、住民や高齢者、障害者等の参加を得ながら実施していきますので。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ区民への説明会をやっていただきたいと思うんですが、いかがでしょうか、それが１点。この計画をするにあたって、ハード・ソフト面を両方合わせてですけれども、そういう部分があったらお聞かせほしいと求めました。","respondent":"上山介護保険担当課長","answer":"１点目、区民への説明会ですけれども、パブリックコメントがその趣旨に沿った形での対応かなと考えております。途中でご報告させていただきました、障害者７団体等の懇談会も開催しておりますので、そういった形での説明はこれまでしてきていると理解しています。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、ぜひ区民への説明会をご検討ほしいと求めました。ぜひ計画ができ上がった段階で、委員会の中で説明をしてほしいと求めましたが、そのことだけお聞かせほしいと求めました。","respondent":"上山介護保険担当課長","answer":"今回の施策の体系で述べています、こういった進め方の中で具体的にどのようにしていくのかということも含めて検討していきたいと考えております。今後、パブリックコメント等を実施いたしまして、こちらのほうに改めてご報告をさせていただきたいと考えております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、大幅な変更が出なくても、例えばパブリックコメントでこういう意見があったということもあわせて、ぜひ最終段階での説明をしてほしいと求めましたが、お答えいただけますか。","respondent":"上山介護保険担当課長","answer":"パブリックコメントの締め切りが２月２０日ですので、こちらの委員会のスケジュール等を考え合わせながら、意見等を含めたご報告をさせていただきたいと考えております。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"特に改定と書いてあるように高齢者や障害者にやさしいということですから、いつ頃、どういうふうにされる予定なんですか。１カ月も経たないうちに決定して実施されるということですから、ご要望等を十分吸い上げることがちょっと少ないのかなという気がしてならないのです。","respondent":"高橋障害者福祉課長","answer":"２月に、改めまして報告書も含めて障害者団体に説明をさせていただきたく、検討を進めています。推進計画改定委員会につきましては、改定の検討委員に出ていただいておりますので、随時その辺の連携に対しては進めさせていただいている状況です。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問","question":"私は委員の枠をもう少し広げられるのであれば、障害者７団体の方々それぞれが何らかの形で参画して、その場で意見が言えると。障害はみんな違うわけですから、そういう方々から直接ご意見を伺っていったほうが、その辺のところをお聞かせいただけますか。","respondent":"上山介護保険担当課長","answer":"障害者７団体との懇談会は、それぞれの障害者の団体の方々と別個に懇談会を設け、かつ２月に改めてご説明させていただきたいと考えているものです。７団体それぞれご出席いただいた場で、事前に資料を配付させていただきながら意見交換をしていきたいと考えております。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問","question":"「すべての人」も「だれもが」も同じ意味ではないかと言われればそのとおりですけれども、何か変えなければいけない意図があるのですか。こだわっているわけではないですよ、余分なことかもしれませんが、何かお考えがあれば教えていただけますか。","respondent":"上山介護保険担当課長","answer":"表現的には最初のタイトルのところが「すべての人」という表現にしておりまして、個々の表現については「だれもが」という表現をしております。考えていく過程の中で、最終的にどういった表現がいいのかを含めまして検討してまいりたいと思います。","id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"これはこれでいいだろうと思うんです。何か意味があるのかと思って、教えていただければという意味で申し上げただけですから、そんなに深い意味ではありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"高橋委員","kind":"質問","question":"コンサルティング会社が入っていると思うんですが、特にこのコンサルティング会社は福祉関係に強いのかどうか、また、どれぐらいの費用で契約されているのかわかれば教えてほしいと求めました。","respondent":"上山介護保険担当課長","answer":"ハード・ソフトを含めましてまちづくりについて豊富な経験を必要とするという前提がありますので、プロポーザルで実施させていただきました。この業者がバリアフリー新法への対応の仕方も含めまして、考え方がしっかりしているということと、今回この業者に決めたものです。","id":"exchange-019"},{"speaker":"宮崎副委員長","kind":"質問","question":"その中で１点、進捗状況と、まだできていないところはどういう対応になっているのかということが一つ。私はいつも思っているんですけれども、それは今回のユニバーサルデザインのところには位置づけられるのかどうか、そこのところを伺いたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"下神明駅が残っていますけれども、これについては鉄道事業者に問い合わせいたしましたところ、現在検討中であるです。ホームのドアは目にしたところ、なかったように記憶しております。","id":"exchange-020"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"それから、品川区は品川区で計画をつくっていくということですから、そういう立場で課題に乗せていくことが必要ではないかと思うんです。そういう意味では、メンバーの中に鉄道事業者もいるわけですから、その辺の区側の認識をお伺いしたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"ただいまのご指摘につきましては、確かにホームの安全確保は、とりわけ障害のある方等においては非常に重要性が高いと思います。現実問題、この問題については区のほうも具体的な把握をしてございませんので、関心を持って事業者に問題を投げかけていきたいと思ってあります。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ぜひ、お願いしたいと思います。そういうところも気をつけてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"山元委員","kind":"質問","question":"団塊の世代の方たちに対してどういう動きをしているかというと、こうしようと言うけれども、行動が伴っていないというところです。何かお考えがあれば、ぜひ教えてほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"この方たちに向けまして、例えば先ほど申し上げましたけれども、まず地域のこういう活動があるということでご案内をしたいと考えております。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993548?Template=document&Id=3192#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":30893,"voices":61}},{"id":"h20-20080121-8","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"建設委員会","time":"午後１時０３分～午後３時３９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を45件整理しています。","topics":[{"id":"topic-01","title":"の環状六号線整備に伴う池上線架道橋改良工事のための測量調査","agenda":"の環状六号線整備に伴う池上線架道橋改良工事のための測量調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"この改良工事、恐らく長い期間かかるであろうと思いますけれども、総事業費は幾らぐらいなんですか。区とか都とか国とかのもの、補助金の関係を少し説明を求めました。","respondent":"阿部都市計画課長","answer":"ただ補助金の関係はどうなのか、その辺はちょっと承知しておりません。申しわけございません。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"質問","question":"これ、場所だけ教えてほしいんですけど、目黒川右岸の下水道管が多分、今掘っているところからこの辺のどこか通るんですよね。地中に来るのかを教えてほしいのと、これは第二建設事務所がどうしても中央環状品川線の中で、区も言ってほしいなということがあります。","respondent":"阿部都市計画課長、家壽田下水道河川課長","answer":"年末ぎりぎりだったそうですけれども、東京都と東急の協議が整って、こういう形になったと聞いております。そういう機会には区の主張は十分にやっているわけですけれども、なかなか鉄道事業者との調整がうまく合わない部分があるです。 中央環状品川線はそれよりかなり下、深いところを掘っているということで、縦断的には大丈夫ということです。","id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問","question":"よくわからないんだけど、例えば３８ｍ掘るのはそれで、その下はいいんだけれども、上に今、下水道管とか、右岸の排水施設も掘るわけでしょう。やっぱり管理をある程度、工事、気をつけてよと言ったほうがいいものなのか、そこら辺がわからないので、教えていただければありがたい。","respondent":"家壽田下水道河川課長","answer":"ＦＥＭ解析と今、専門用語で呼んでおりますが、そういったものはやっておりまして、地上に影響がない。それはかなり深くて、地盤のいいところを掘っておりますので、地上には影響はほとんどないという結果で恐らく出るだろうと思います。","id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいんですが、そのほかに何か別の診断装置というんですか、診断と言ったらおかしいのかな。あくまでボーリング調査だけなんか尋ねました。","respondent":"阿部都市計画課長","answer":"要するに先ほども申し上げましたけれども、民地と接している部分がありますので、そういうことで境界等を含めた測量と聞いております。測量いたしまして、その後に設計に入っていくという形ですので、今回の測量はそういう中身です。","id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"改良工事の日程と言ったらいいんですか、この山手通りの拡幅工事を行うかどうか、それも一緒に教えてください。車線を減らしてやることになるのか、そういったことも説明を求めました。","respondent":"阿部都市計画課長","answer":"要するに同じ時期に供用を開始するというふうに聞いております。山手通りの車線の変更をする必要が出てくるということで、車線を外に持っていきまして、すりつけていくです。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問","question":"工事期間中に車線を変えていって、工事がしやすくするようにという、その区間がここであるという理解でよろしいでしょうか。それから先ほど質問した中で、その工事期間中の交通規制はどのようになるかということを説明するよう求めました。","respondent":"阿部都市計画課長","answer":"今、委員がおっしゃったように、この区間のすりつけです。その関係で車線の変更が出てくるですけれども、それは改めて第二建設事務所の品川線担当のほうで計画をつくるというふうに聞いてあります。","id":"exchange-006"}]},{"id":"topic-02","title":"の大井町線急行運行に向けての深夜試運転の実施","agenda":"の大井町線急行運行に向けての深夜試運転の実施","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"実施時期、最初の２回は１２日、１９日で、既に２回実施されたのでしょうか。もし実施されていて、沿線の住民の方から何か反応ですとか声があったのであれば、教えてほしいと求めました。","respondent":"阿部都市計画課長","answer":"１月１２日、１９日は実施しております。これにつきましては、東急に確認しましたけれども、沿線の方々から意見というものはなかったと聞いています。","id":"exchange-007"}]},{"id":"topic-03","title":"の品川駅・田町駅周辺まちづくりガイドライン","agenda":"の品川駅・田町駅周辺まちづくりガイドライン","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"全体の地域は６３０ｈａですか、教えていただきたいなというのが１点と、これは品川区から何人ぐらいというのはわかるんですかね。もしわかったら、説明を求めました。","respondent":"青木都市開発課長","answer":"こうしたことに関しまして、今後運用していくに当たって配慮していきますというような形での対応方針を表現しています。もう１つ、具体名とか、品川区在住もしくは品川区に所在地を持つ事業所からのご意見は０件だったと報告いただいております。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"パブリックコメントのことなんですけれども、６３０ｈａという膨大な地域の意見を伺うわりには、あまりにも期間が１５日間と短過ぎる。目的をご説明いただきたいのと、この状況についてどう思われているのか、お伺いしたいと思います。","respondent":"青木都市開発課長","answer":"ちなみに品川区としての対応ですけれども、個別に町会の方々にご案内申し上げて、ご意見をちょうだいするなどといった手続を踏まえたことは事実です。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"去年、今年、年末年始そういう話もよく伺いました。この環境に配慮したという、この環境とは一体何を指しているのか、説明を求めました。","respondent":"青木都市開発課長","answer":"どんな責任を負っていくべきかというような、よりどちらかというとかたい話に振ったものでありまして、必ずしも人間が心地よく住むための環境がどうあればいいという視点ではないというふうにご理解いただければと思います。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"私はもっともっと議論すべき点があると思いますし、もちろん身近なところでできる環境対策もありますよ。ＣＯ２の削減目標を掲げながら増えているのが実態ですから、よく見直すべき点があると思いますので、議論すべきだと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"三上委員","kind":"意見","question":"今のやりとりを聞いている中で、このものについてというのは、品川区の地域ではほとんどないよね。話し合いはされていると思うんだけれども、品川区でこういう議論というのはどこまで反映されると考えていますかとの意見を述べました。","respondent":"青木都市開発課長","answer":"そういったものは区としては十分、行政側としては認識しておりまして、この港区中心の取り組みに対しても少なからず意見を申し上げてきたところです。そのつもりで取り組んでいく所存です。","id":"exchange-012"},{"speaker":"三上委員","kind":"意見","question":"それは位置づけは明確にしながら、品川区としての意見、それからどう取り組むかということはやってきていると思う。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"品川区はだれが出られたのかというのを教えていただきたいのと、案の修正には至らなかった、文言の変更だけは間違いというのはしたと。そういう話というのが何かもっと表に出てきてほしいなと思うんだけれども、その辺の感覚を説明するよう求めました。","respondent":"青木都市開発課長","answer":"１点目のご質問ですけれども、この検討会等につきましては、都市開発課長を当ててきてまいっております。あるいはほかの鉄道事業者等にも大きな課題であるということを認識していただけたことは、品川区としての努力の成果だと考えております。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"用地買収を含めて始めますよとか、今おっしゃったように権利関係がたくさんあるから、用地買収だって必要になってくるわけじゃないですか。そういう何かきっかけづくりみたいなものをぜひこれからも話す機会があるんでしょうから、それは要望だけにしますけど、ぜひお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問","question":"１つ目、国や都の金というのが出やすくなるとか、やりやすくなるといった効果があるのかどうかということを教えてください。品川区のこれからのあり方を分析していく、あるいは対応策を区として考えていくというような、そういったお考えは今でなくてもあるんか尋ねました。","respondent":"青木都市開発課長","answer":"ガイドラインそのものは冒頭ご説明したとおり、まず計画論を行政、自治体でつくります。あるいは区政全体の中で産業等を踏まえて、隣の区とどう協調していくのか、どう競争していくのかということを考えていくべきだと考えています。","id":"exchange-016"},{"speaker":"井上委員","kind":"質問","question":"そこを品川にどう誘導してくるかということをおっしゃっていましたけれども、来街者の集まる観光拠点としての景観形成を誘導します。こういうところに含まれているのか、その辺の区としての姿勢みたいな、まちづくりのイメージみたいなものはどういうふうに考えているんか尋ねました。","respondent":"青木都市開発課長","answer":"産業振興の視点から観光協会などとのタイアップで進めている旧東海道の魅力づくり、そういったものを品川区の所管でも取り組んでいるものを踏まえて、こういったような記載に反映させたものです。","id":"exchange-017"},{"speaker":"井上委員","kind":"質問","question":"そういうこともいろいろな工場跡地とか、品川区にも結構あるわけですけれども、そういうことが既にイメージされているということか尋ねました。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"よりもうちょっとグレードの高いいろいろなコンベンション機能も備えた都市型ホテルが多く立地していて、そこも非常に好調だと伺っております。そうした中で、品川区といたしましては… そういったこの全体の中で、こういったことを考えていきましょうという表現だというふうにご理解をお願いしたいと思います。品川浦のところにホテルを建てるとか、そんな計画は現在区が持っているわけではありません。","id":"exchange-018"}]},{"id":"topic-04","title":"の平成１９年度マンション管理セミナー（第２回）の開催","agenda":"の平成１９年度マンション管理セミナー（第２回）の開催","exchanges":[{"speaker":"井上委員","kind":"提案","question":"参加している方たちからも意見を求めてほしいというようなことを提案しましたけれども、テーマとして企画することができるのかどうか、できるのかということをお伺いしますとの意見を述べました。","respondent":"齋藤住宅課長","answer":"今、委員からのご指摘があった高層マンションの防災対策につきましては１つの課題だと考えていますので、できればテーマに考えます。まず民間よりも先に区がやってみようということで取り組み、民間事業者の意識を変えていきたいと考えています。","id":"exchange-019"},{"speaker":"井上委員","kind":"質問・要望","question":"今求められているのは、管理をしている住民の方たちからもそういうセミナーの要望の声があるので、このマンション管理セミナーを有効に活用していただきたいという要望をお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"ひとつ伺いたいのは、３０年ないし４０年近くなってきたマンションの方々の高齢化が進んでいますよね。そういう方に対しての意識形成というのは大規模改修への話し合いというんですか、そういう点では現在や今後、ちょっとお伺いさせていただきたい。","respondent":"齋藤住宅課長","answer":"休日、夜間に相談にのってほしいという要望を受けたもので、対応しようと今、区で考えているところです。ついてはどういう話をしたかについても添付資料としてつけるようにして、これからももっと広く関心を高めていきたいと思います。","id":"exchange-021"}]},{"id":"topic-05","title":"の区民住宅長期滞納者（和解条項不履行）に対する強制執行","agenda":"の区民住宅長期滞納者（和解条項不履行）に対する強制執行","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"今の説明の中で、経過があったんですけど、そもそもこの区民住宅の入居対象で、一定の所得を確認しますよね。どうしてここまでの、そごというのも違うんだけど、そこをちょっと教えていただけますか。","respondent":"齋藤住宅課長","answer":"私どもの努力不足もありましたが、感情的になって、ちょっとうまく話ができないことがあります。時間をかけたつもりでしたが、なかなか具体的な事情もお話しいただけず、アクションもみずからはなかなか起こされなかったです。","id":"exchange-022"}]},{"id":"topic-06","title":"の「品川区ワンルーム形式等集合建築物に関する指導要綱」の制定","agenda":"の「品川区ワンルーム形式等集合建築物に関する指導要綱」の制定","exchanges":[{"speaker":"井上委員","kind":"提案","question":"同じように居室がある階数が３階以上、かつその戸数が１５戸以上のワンルーム形式と集合建築物とするというふうに、そういうことがあるのでしょうか。これは提案されていたことが形になっていいと思っているんですけれども、この中で３０m2ですよねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこの理由をもう一度伺いたいのと、２０戸から２９戸だったら２つとした理由は何か、あわせてご説明ほしいと求めました。もう１つはファミリータイプの４０m2以上というのはどういう理由なのか、お考えを教えていただきたい。","respondent":"齋藤住宅課長","answer":"なかなか説明しがたいんですが、売りにくくはないんだけれども、建設しにくいというのが大体この戸数の割合だというふうにご理解をお願いいたします。３５m2ぐらいで、これはワンルームマンションとは言わないと、業界の中では言っています。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"ただ、もう一回り大きいのを２軒だけファミリーでも、それだけじゃ地域との交流というのは結びつきにくいんじゃないのかなとも思うんですよね。今後どういうふうにやっていくのかはあれですけれども、今回第１段だということなので、今後の現状の問題意識だけ教えていただけますか。","respondent":"齋藤住宅課長","answer":"都市計画法、建築基準法がございまして、法令の範囲内でしか制限ができないんです。そうすると、上に自分も住んで、余った容積をワンルームにしないと、住み続けられないし、事業もできないといった方もいらっしゃる。","id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういうのというのは今回、これを見る限り入っていないんですけども、その辺のお考えがどうなのかを教えていただきたいと。区の条例に格上げすることも検討するべきじゃないかなと思うんですけれども、そこについてはどのようなお考えなんか尋ねました。","respondent":"齋藤住宅課長","answer":"ワンルームの１階部分を店舗にすることにつきましては、今後の検討課題だと考えています。条例にしなかった理由は２つ、今も申し上げましたが、上位法がありまして、条例にしても強制力を持たせることはできません。","id":"exchange-026"},{"speaker":"井上委員","kind":"意見","question":"ここがなぜ２９m2じゃなくて、またあるいはどういうふうに指導していこうというふうにするものなのか、考えをお願いしますとの意見を述べました。","respondent":"齋藤住宅課長","answer":"１m2上がっています。多分、それは３０m2未満と矛盾している言い方。","id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"だから、これが何で２９m2になって、３０m2と、ここをしたんですかと。","respondent":"齋藤住宅課長","answer":"未満は２９m2までです。区といたしましてもなかなか対応しづらいんですけれども、地域活動課のほうでも、何かいろいろ仕掛けを考えなきゃいけないなということはあります。","id":"exchange-028"},{"speaker":"阿部委員","kind":"意見","question":"それに沿わない形で建設して、例えば１棟売りをしてすぐに１棟売りしたような場合には、買った業者に対し同様の指導をしていくのかどうか。やはり今言いました、これまた既存のワンルームマンションの所有者に対して、何らかの働きかけをするお考えかどうかというのを説明するよう求めました。","respondent":"齋藤住宅課長","answer":"あるいはそういったものをまず初めとして誘導しないかというのは、また別な切り口として考えています。ただ、１棟売りして建ったものに対しての指導はなかなか難しゅうございまして、ご理解のほうをお願いいたします。","id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問","question":"８位、９位ぐらいならいいのかなというような感覚を持ってこれを決めたんだとすると、ちょっと違うのかなと思うんだよね。９位になってくるのかどうか知らないけれども、２位になったことをとらえて、そこら辺を教えてほしい。","respondent":"齋藤住宅課長、岩田まちづくり事業部長","answer":"１位、２位になったからということではございません。いろいろこの２年間ずっとやってきましたけれども、心配といったものに区としてどうこたえるか、こういう規制をつくらせていただいたです。 それが貸家式アパート等でも２間、３間というような、文化の流入ということでも非常に価値があることだと思うんですね。それでやってみようというのが、今回の改正の大きな理由ですので、ご理解をいただきたいと思います。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１点だけちょっと教えていただきたい。棟数でもいいんだけれども、何か理由があったから飛び出させたんだろうから、そこを説明するよう求めました。","respondent":"齋藤住宅課長","answer":"そうすると、この数年で４件ほどあります。荏原地域で多いということですね。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"４件もあったというので、どうせ開発するなら同じになるような気がするので、ここら辺はちょっと検討していただければなと。これは要望だけしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"須貝委員","kind":"質問","question":"それでトラブルがあっても、どこに訴えていいんですかと。それをやはりいいところどりじゃないんですけど、緩くなればやはりどうしても上下あれば下のほうに流れてくるわけですから。","respondent":"齋藤住宅課長","answer":"この下町の地域と、品川区、目黒区、世田谷区とか、大田区といったところでは、ワンルームに対して実需が違いますので、なかなか比較が難しい。どうなるかまだわかりませんので、状況を見ながら、ちょっとまたいろいろ見直してまいりたいと思います。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"今、住宅課長のほうからお話があったんですが、それはかなり大丈夫だと思っていいんでしょうかね。どうなんでしょう、その辺、ちょっと自信のほどをお聞きしたい。","respondent":"齋藤住宅課長","answer":"私も２回ほど乗り込んでいったことがありますが、社員が５人しかいなくて、儲かるためなら何でもやると。名前を変えてでもやるというところもありますので、それについては、なかなか条例にしても規制しがたいというのは事実です。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"できるだけ指導していただきたいということと、私も重ねて言わせていただきますが、あくまで転売ということも今あると思うんですね。完全な投資ということで、その辺の後も何とか追えるように、施行された後は従ってもらうように何とか指導を強化してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"なぜ説明会なのかというと、実際全部とは言わないですけど、乱暴な業者はとにかく住民説明会を３回我慢すればいいんだと。説明会の規定というのはもう少し明確にするべき必要があるんじゃないのかなと思うんですけれども、同じことですけれども、お考えを説明するよう求めました。","respondent":"齋藤住宅課長","answer":"説明会だけは２３区の中では私どもがリードしておりまして、２Ｈの範囲で説明すればいいという規定が多い中で、説明会を開きなさいというのは品川区。","id":"exchange-036"},{"speaker":"中塚委員","kind":"意見","question":"３回我慢すればいいんだと、ぽろっと言って、それですごくみんな反感を買って。会の話はあれですけど、やっぱり近隣住民から申し出があった際は、しっかり対応するという文言や指導は必要ではないのかなと思うんですけどもとの意見を述べました。","respondent":"齋藤住宅課長","answer":"着工させないように指導しなさいということをおっしゃるんですが、なかなかそこまで言い切ることが難しい。それで話し合いの場を区役所のほうで設けたりとかして、区としても努力をさせていただいているです。","id":"exchange-037"}]},{"id":"topic-07","title":"耐震化促進計画","agenda":"耐震化促進計画","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"これは平成２０年の１２月３１日となっておりますけれども、その１年間だけのものなのかということと、傾向を教えていただきたい。","respondent":"片田建築課長","answer":"これは国のほうの考え方ですから、あと全国を含めて、このような内容で対応してきているという状況です。それと、２０年の１２月３１日までに改修した場合ということでの条件になってきてありますが、ちょっとそれは伺っていきたいと考えております。","id":"exchange-038"},{"speaker":"井上委員","kind":"質問","question":"２７年までに耐震の９０％を実現していこうという中で、国としてそうということなのか。それ以降のことについては、どのようなことを考えられているのか、その辺の検討とかはないんか尋ねました。","respondent":"片田建築課長","answer":"区としてどうのという検討ではございませんで、国としての考え方として、これをどう連動させていくかということだと、私も認識しています。国の考え方かもしれませんけれども、これもたしか前回、そういうことも含めて情報提供をしていきたいということでいるものです。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"私は２つポイントがあるのかなと思っていまして、１つはやはり啓発といいますか、これはよく議論されたところだとは思うんですね。一点お考えを伺いたいのと、それを１点、説明を求めました。","respondent":"片田建築課長","answer":"地域のほうにもご説明にお伺いするといったようなこっちからの視点を考えてきてありますので、あわせて進めていきたいということで考えてあります。そんな形での関係機関との連携も強化した上で、行くだけではなくて、そういうＰＲに努めてまいりたいと考えています。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"建築確認審査がなかなかおりにくくて、見直す点というか、定める点が明確になるのかなと思うんですよね。だけれども、悪意を持った方々も残念ながらあらわれることもあり得るでしょうから、かっちりやり過ぎると使いにくいと。","respondent":"片田建築課長","answer":"建築士事務所協会との連携の中でも、その見積もりがどのぐらいかかるんだといったようなところまで、実は提案させていただいてきてあります。その建物、建物に合った内容について、いろいろな診断の結果の補強方法等についての提案をしていけたらと考えています。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"その辺は幅をきかせて運用の中でよく工夫していただきたいということです。じゃ、それじゃやっぱりだめなんじゃないかなと思っていて、その考え方をお聞きしたいんです。","respondent":"片田建築課長","answer":"やはりそういう制度としては、いろいろ活用された方のご意見も踏まえた中で、研究できるところには今後とも研究していきたいと考えています。そこで生活再建ができるということを基本として考えてありますから、シェルターは、それはご理解いただければと考えています。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこを教えていただきたいのと、この考えを教えていただきたいのと、生活保護世帯の方をどう考えていらっしゃるのか。生活がぎりぎりなものですから、この耐震シェルターの関係ではどういうふうに運用を考えているのか、現状を教えていただけますか。","respondent":"片田建築課長","answer":"それに対して、というところで、すぐ避難できる場所が身近にあることが望ましいだろうという考え方に基づくものです。生活保護世帯等々についても、そこの世帯としての収入がそれを超えるかどうかというのを１つの判断基準で考えていきたいと考えています。","id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問","question":"補助金は見込んでいませんというぐらいの、区でこの９０％にするためにどうしたのですかというのがどこかにあるなら、それを教えてほしい。建て替えをしたり、５６年６月以前というのは、そこら辺の生活サイクルを何年と区はとらえてやっていらっしゃるのかというのがあれば説明を求めました。","respondent":"片田建築課長","answer":"１点目、特にシェルター、支援制度を来年度予算から検討していきたいといったところを区のほうとしても取り込んだというところもあります。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問","question":"一番効果があるのは建て替えだろうし、あとそこで１部屋だけ守るといったら、シェルターがあるから命を守れる。独自に政策を打っていただければなと、これはお願いをしておくのと、また違ったところで質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759088?Template=document&Id=3900#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":50564,"voices":122}},{"id":"h20-20080121-9","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"文教委員会","time":"午後１時０２分～午後４時２０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"荏原西地区小中一貫校に関する設計変更","agenda":"荏原西地区小中一貫校に関する設計変更","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"いわゆる、幼稚園部分がなくなって、小学校と中学校の学校施設だけで建設していくと説明を受けたんですけれども、改めてそこを確認したい。軟弱地盤だということですから、素人ですからそういうことがわからないんですけれども、軟弱地盤であっても耐えられるものになるのか。","respondent":"市川庶務課長","answer":"１点目と３点目が関連があろうかと思うんですが、今回の設計変更によりまして、新しい施設には入ってまいりません。これが設計変更の主な概略です。","id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"ちょっとその辺の見解を、改めて伺いたいと思うんです。１,０００m2ですから、小さな子どもですから、ちょっと残念かなと思いました。","respondent":"市川庶務課長","answer":"どうにか融通がきかなかったのかというご趣旨でしたけれども、縦にということで、地下のほうに設計でいろいろ工夫しながら回してまいりました。ここが選択の決断をした境目の事情です。","id":"exchange-002"},{"speaker":"山内委員","kind":"質問","question":"その地盤のことになるんですけれども、設計の段階で、事前にそういう調査ができなかったのかということが、まず一つ問題だと思います。工事費すべてにおいて、トータルすると経費がかかってくるんですが、その辺はどう考えているのかということを説明するよう求めました。","respondent":"市川庶務課長","answer":"従来、幼保一体施設を予定しておりました２階建ての棟になるわけですけれども、従来２階建てで考えていたものを１階建てに直すといったことですので。","id":"exchange-003"},{"speaker":"山内委員","kind":"質問・要望","question":"こういうことがあったということは、ある意味、この６校構想の中で設計ができている段階もありますけれども、やはりこういう調査を事前にして、なるべくロスをなくすという形にしていただきたいなということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"その中で、幼保小中という連携の仕方がどういうふうに変わってくるのか、変わらないのか。一貫校という形での考え方がどうなっていくのかということをお聞きしたいんです。","respondent":"市川庶務課長","answer":"政策的な意図のもとに変更したわけではございませんので、特に２点目のご質問、このことによってどうこうなるということはないと考えております。１点目の、私どもでは、幼稚園単独施設として残るということで説明を聞いております。","id":"exchange-005"},{"speaker":"西本委員","kind":"意見","question":"当然ながら、平塚小学校は、そのあいている部分をどう使うのかというところは出てくると思うんです。その辺をどういうふうに検討されるのか、これからのスケジュールを含めて、考え方をお願いしますとの意見を述べました。","respondent":"市川庶務課長","answer":"できないのか、これについては、その計画ごとに検討をしてまいります。児童保健事業部のほうでしかるべき検討が行われ、また必要ならば、私どもも協議に加わっていくという姿勢で向かっていきたいと思っています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"路線変わらずといっても、具体的なところでは、やはり大きな変更が出てきているようですから、それも含めて展開をしてほしいと求めました。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大沢副委員長","kind":"意見","question":"どういう時期に、町場に対してどういう時期に、タイミングといいますか。近隣のお母さん方も、頭の中でそれを予定している方もあるので、そこのところは、どのタイミングになるのかとの意見を述べました。","respondent":"市川庶務課長","answer":"今後、当該の平塚幼稚園、平塚小学校、平塚中学校、荏原第二中学校の小中一貫校の建設計画にかかわる関係者に対して説明をしてまいります。幼稚園に入園を予定している方々、これについて十分に説明を行えるように、取り組んでまいります。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"地盤が非常に弱かったというのは、いつごろの時点でわかったんか尋ねました。","respondent":"市川庶務課長","answer":"昨年の秋の時点で、一定のボーリング調査の結果が出てまいりました。その後、これまで進めてきた設計作業の延長線で考えられるかどうか、そういうことを昨年末まで検討したという経緯があります。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"秋というと、９月から１１月、１２月ぐらいまで一定程度の期間があるんですけれども、１１月には議会があって、当然、文教委員会も開かれたんですけれども、そこには発表するまでにきちんとした結果が導き出せてなくて発表できなかったということなんか尋ねました。","respondent":"市川庶務課長","answer":"方針を確定するのには、幾つか検討して、詰めるべきことがあります。一定の方針を出した上で、なおかつまだほかに選択の余地がないか、そういうことを検討した上で最終的に方針を決定した。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"先ほども質問が出たように、それに取り組むように進めていただきたいということを、改めて申し上げておきたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"金野委員","kind":"確認","question":"すみません、確認だけ。給食室部分というんでしょうか、アリーナは残すということなので、その部分ということなんか尋ねました。","respondent":"市川庶務課長","answer":"説明しますけれども、地下１階の部分、設計の変更作業を行っています。シンプルな形にしたほうがやりやすいということのもとで、今、作業を進めております。","id":"exchange-012"},{"speaker":"金野委員","kind":"質問","question":"そうすると、その部分をそぎ落とすということで、剣道場とか、こういうのは学校についているところは少ないので、こういうのはなくしちゃうんですか。それとも、それもちゃんと設計図の中に端のほうに生かせるようになってくるのか尋ねました。","respondent":"市川庶務課長","answer":"そういうことも含めて、今、検討をしています。大体、見込みが立って、先ほど申し上げました施設のローリングがうまくできそうだというめどを立てているという状況です。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"関連で、すみません１点。子どもが見えるような設計を考えていただきたいなということを、そのことも意見としてお伝えしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"}]},{"id":"topic-02","title":"鈴ケ森小学校の休校措置","agenda":"鈴ケ森小学校の休校措置","exchanges":[{"speaker":"金野委員","kind":"質問","question":"見ましたというやりとりはなくて、一方的に流すだけなんでしょうか、そのやりとりについて。要するに連絡がとれた人からと書かれているので、メールだと、その連絡が行ったかどうかというのは、どうなるのかなということです。","respondent":"古里学務課長","answer":"学校からの説明によれば、メールと電話で連絡をとってですので、それは保護者と直接確認ができた者から下校させていくです。下校の確認がとれて、最終的に全員が下校したのは４時３０分と聞いておりますので、確実に連絡がとれた状態で下校させていると確認をしています。","id":"exchange-015"},{"speaker":"金野委員","kind":"質問","question":"７５名が欠席をして、電話でされたものと伺ったんですが、保護者にちゃんと伝わっているかどうかというのは非常に心配をされるところなんです。ちょっとこういう緊急時に子どもを帰すときのタイミングというんでしょうか、学校から帰る間、ちょっと心配だなと思うんです。","respondent":"古里学務課長","answer":"一方的に流して、それで連絡がとれたと、学校はそのような乱暴なやり方はしていないと考えています。これについてそのようなこともあり得るということについては、私のほうから、改めて学校のほうに通知をさせていただきたいと思います。","id":"exchange-016"},{"speaker":"金野委員","kind":"質問","question":"今、お考えをお聞きしましたので、できれば直接言葉で伝えていく昔ながらの連絡網というのがやっぱり一番安全なのかなと思います。それも含めて、緊急時の対応というんでしょうか、ぜひ、お願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"西本委員","kind":"質問・要望","question":"確認をさせてほしいと求めました。それから、７５名は特定のクラスに集中していたのか、全体にばらけていたのかというところは、いかがだったんか尋ねました。","respondent":"古里学務課長","answer":"１５日に再開をした場合、校内でのさらなる感染ということを考えた場合、これは緊急性があると判断したというものです。どうかということですが、全校児童に満遍なくということではございませんけれども、ほとんどすべてのクラスで発症をしているです。","id":"exchange-018"},{"speaker":"西本委員","kind":"確認","question":"非常に感染力が強いということで、これは確認ですが、給食等が感染源でないということが、今の時点では言えるという理解でよろしいんか尋ねました。","respondent":"古里学務課長","answer":"先ほど申し上げたとおり、保健所が感染のルートについては、まだ調査中です。現在の段階での口頭の報告によれば、給食を介して、いわゆる食中毒としての感染ではないのではないかという報告を受けてあります。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"私もちょっとそこのところを伺いたかったんですけれども。何で１日あけて、１５、１６日なのかなと、ちょっとあれだったので、そこを伺いたかったんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"石田（慎）委員","kind":"質問","question":"４７名程度が検便検査を実施したということなんですが、２１日現在はきょうですので、１０８名全員に対して検査をするんでしょうか。その２点を、説明を求めました。","respondent":"古里学務課長","answer":"この対応について、至急学校が検討しているところでございまして、学期末までにきちんと取り戻しをしますということは報告をしております。学校は全力で子どもの健康管理に当たっておるところですので、来週以降、そうした３学期末までの計画の見直しをしていくと考えております。","id":"exchange-021"},{"speaker":"石田（慎）委員","kind":"質問","question":"そうすると、検便検査というのは、欠席者だけでなくて、学校全体での検査を促したというか、希望される方のみ実施をしたということでよろしいんか尋ねました。","respondent":"古里学務課長","answer":"そのようです。ＰＴＡのメールを借りて緊急の連絡の中に、そのようなことに触れて通知をしたと、学校から聞いてあります。","id":"exchange-022"},{"speaker":"大沢副委員長","kind":"質問","question":"１５日に全校を次亜塩素酸ナトリウムで消毒したというような対策を考えると、１１日の給食を中止をしたことはいいんですが、子どもたちにそういう食を与えるということに対して危機管理みたいものはお持ちになっていたんか尋ねました。","respondent":"古里学務課長","answer":"何らかの形での給食の実施はせざるを得ないということで、それから児童は、手洗いの徹底を指導した上で配付をしたです。必要なところについては、十全の消毒、部分的な消毒等は行って実施しているというふうになっております。","id":"exchange-023"},{"speaker":"市川委員","kind":"確認","question":"すみません、ちょっと確認だけさせてください。鈴ケ森小学校のことを受けて、他校で何か特別な対応とかをしていることがありましたら、説明を求めました。","respondent":"古里学務課長","answer":"したがって、家を出るときは元気だったんだけれども、１時間目に突然吐いてしまうと。完治後も、２日間は出席停止という扱いをして、今後の事態に備えたいというふうに考えております。","id":"exchange-024"}]},{"id":"topic-03","title":"特別支援学級等整備計画","agenda":"特別支援学級等整備計画","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"介助がついている状況がどの程度あるのかということを、ちょっと教えていただきたいというのが、とりあえず一つあります。校内委員会だとか、そういうことも含めて、ちょっと整理できるように教えてほしいと求めました。","respondent":"河野指導課長","answer":"障害がある子どもの登校に関して介助員がついているのかと聞こえたんですが、それでよろしいでしょうか。","id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"親の立場から聞いた意見ですから、教育委員会の判断がどうかというのはわからないんですけれども、外されちゃったと。さっきの質問との関連で、どういうふうに見たらいいのかということ、それをちょっと教えていただきたい。","respondent":"河野指導課長","answer":"その子が学校の中で適正な教育を受けることができないというケースについて、必要の度合いに応じて配置するということでやっております。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"了解なりをいただける対応が、学校側にも必要なのかなと思いながら伺ったので、ぜひその辺もちょっと受けとめてほしいと求めました。言葉の教育だとか、そういう意味ではちょっと理解はしたんですけれども、そこと固定級との違いが何なのかというのをちょっと説明を求めました。","respondent":"河野指導課長","answer":"通常の義務教育学校に設置されている、公立の学校に設置されている特別支援学級は、軽度の知的障害を持つ子どもが対象になります。基本的には知的障害を伴わないというのが前提ですので、それ以外は、自分が在籍している学校で通常の授業を受けるという仕組みになっております。","id":"exchange-027"},{"speaker":"西本委員","kind":"確認","question":"特に固定級ですが、設置の考え方を確認したいんです。そうすると、ブロックの中の、地区の中の開校している固定級は閉鎖になって、一貫校に移管していくという形の考え方でよろしいんか尋ねました。","respondent":"河野指導課長","answer":"第二日野小学校のほうには特別支援学級はありませんので、この場合には、小学校についてはそのまま特別支援学級を設置しない。冒頭に申し上げたように、すべての施設一体型の小中一貫校に特別支援学級を設置するという考え方ではございません。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"子どもたちはそこに通っているわけですから、その年からあっちですよとかいう形になってしまうと思うんですね。そこのタイミングというのは、それぞれの施設の場合に考えた形で、これに落とされているのか、どうなんか尋ねました。","respondent":"河野指導課長","answer":"それだけのスペースが確保できる第一日野小学校のほうに特別支援学級を移設したほうが、十分な特別支援教育に対応できるということで、今。地域バランスを考えて、大崎中学校のほうにもう１校通級を設置して、こういう計画を考えているところです。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"やっぱりその学校を選んで、その学校にいるわけですから、そこで卒業したいというようなことは当然考えるわけですよね。そこを配慮した切り替えというのを考えていただけるんでしょうかということです。","respondent":"河野指導課長","answer":"６年前に、平成何年にこういう学校を設置したいので認可してくださいといっても、認可は下りません。ただ、浜川中学校に関して言えば、そういう構想がありますよということで、来年の４月に入級を予定される子どもを対象に、そういう話はしています。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"せっかく伊藤学園のほうにできているわけですから、近いところにそういう学校があるわけですから、それを認識していただくというような。なるべくそちらのほうに促すわけではないんですが、もうちょっと広く知っていただきたいなと思いますが、いかがか尋ねました。","respondent":"河野指導課長","answer":"まさに伊藤中学校の特別支援学級にするか、浜川中学校の特別支援学級にするかという、実態としては全くありませんでした。伊藤中学校の特別支援学級のほうもご案内していますので、最終的に、親御さんの気持ちを伝えていただくというふうになろうと考えているところです。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"私もちょっと、今の話は伺っていて、それはそれとして理解はするんですけれども、浜川中学校が、平成２２年度から閉級になりますよね。固定級がずっと平成２１年度まであって、平成２２年度から固定から通級開級というのは、中身的に質が変わるということなんか尋ねました。","respondent":"河野指導課長","answer":"私どもは、個々の子どもたちのそういう利害関係を全く考えてないわけではありません。全体を考えたときに、あるいは区内全体のバランスを考える上で、その辺はぜひご理解をいただきたいと考えているところです。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"あの周辺の環境自体があるわけですから、それは同様の心配になってくるので、ちょっとお願いしておきたいと思います。質問じゃないんですけれども、そういう時間を設けていただきたいということを、改めてお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/612972?Template=document&Id=4624#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":31579,"voices":90}},{"id":"h20-20080121-5","meetingId":"h20-cm01","date":"2008年1月21日","dateIso":"2008-01-21","committee":"総務委員会","time":"午後１時０２分～午後２時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"この１１４件の意見、パブリックコメントの数字上それが妥当なものとして考えておられるのかどうか、まずそこをお聞きしたいんですが。","respondent":"福島長期計画担当課長","answer":"１１４件ですけれども、この数が多いか少ないか、確かに難しい問題で、多いとも少ないとも言いにくいところもあります。さまざまな市民の方の考え方があるかと思いますが、数としては状況としても、ほかと比べましては多いかと考えております。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"本来こういう最も重要な部分での意思決定をしていくわけですから、私はまず必要なのではないのかなと思っているんですけれども、その辺はいかがか尋ねました。","respondent":"福島長期計画担当課長","answer":"どちらが多くの区民の方に声が届くかということを考えたとき、一番いい方法というのがこの広報紙で、文章で語りかけるものがいいのではないかと。そういったことのほうがいいのではないかということで、今回につきましては直接の説明は行いませんでした。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"今後のあり方として、やはり直接説明をし、意見を聴取していくという形をぜひ私はつくってほしいと求めました。もう１つ、直接的に文章のほうでお聞きしたいんですけれども、個別の話になりますけれども。","respondent":"福島長期計画担当課長","answer":"この基本構想に基づきまして長期基本計画を策定してまいりますので、ご説明し、そういった機会をつくる方向で検討していきたいと考えています。ただ、どのようにやるかはまだ検討してございませんが、策定の段階につきましてはまずは区民の方の直接的な声を聞こうと考えています。","id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"これって決まったものなんですか。例えば半年とか１年間は長過ぎるかどうかわからないですけれど、先ほどの説明もあわせてパブリックコメントを行うという考え方はないんか尋ねました。","respondent":"福島長期計画担当課長","answer":"品川区としてもＣＯ２削減について努力していくという意思はここに示されているものと考えておりますので、ご理解いただければと思います。なかなか難しいことはあるかと思いますので、要綱に定められたとおり行うのが妥当ではないかと考えています。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問","question":"もしかしたら普通のいい方ですと多分「健全な家庭」と、こちらのほうはどのような考え方で「健康」とされたか１つお伺いしたいところです。その１点をお伺いします。","respondent":"福島長期計画担当課長","answer":"ここであえて、これは単に家庭だけにかかわらず３０代前半の方々が今後健康に、「健康」という形にさせていただきました。ご理解をお願いします。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"過去のものはここでは関係ないかもしれないですけれども、結果が公表されているのは３番目の耐震改修促進計画だけですね、今のところ。こういう形で出るようにするのかその点をお伺いしたいのと、あと、いつごろに掲載をされる予定なのかなということも。","respondent":"福島長期計画担当課長","answer":"現在考えていますのは、いただいた意見とその要約、さらに対応という形で全文が見えるようにしたいと考えています。ただそれにつきましても手続等、決定等を取りますので、その辺のお時間をいただければと思います。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"すみません、今お伺いすればよかったんですけれども。それだけちょっと。","respondent":"福島長期計画担当課長","answer":"こういうことがありました、結果についてはこうですというようなご報告につきましても、広報しながわを通じて行いたいと考えています。したがいまして個別に回答をお送りするというようなことは考えておりません。","id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"２０年に１回という改定の時期でこれだけ集まってきた。しかも２０年に１回だということになれば、もう少し丁寧な対応の検討をしていただけないでしょうかということなんですが、いかがか尋ねました。","respondent":"福島長期計画担当課長","answer":"まさに２０年に１度のことですし、寄せられた意見の方々の重みというのも感じております。したがいまして、どのような形で満足度がより得られるのかどうか、少し検討させていただきたいと考えております。","id":"exchange-008"},{"speaker":"伊藤委員","kind":"意見","question":"何というか必要性が、可能性があると思われますので、それはぜひ検討してくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"原委員","kind":"意見","question":"伊藤委員から話がありましたけれど、もうちょっと深く。別紙３のところで肯定的、否定的ということで２１件と出ているんですけれど、ちょっとお教えいただけますかとの意見を述べました。","respondent":"福島長期計画担当課長","answer":"「区への責任を果たした協働というのは妥当でない」ですとか、「基本構想には正しい日本語を使ってほしい」みたいなご意見をいただいております。学校教育ですとか子育てについて批判的なご意見がある方が、それを含めて基本構想について批判されているということがございました。","id":"exchange-010"},{"speaker":"原委員","kind":"質問・要望","question":"２０年ということで、品川区民憲章の次に位置してこようかと思うので、ちょうど基本計画の１０年との間ですよね。否定的といっても関心があるからいろいろな意見をちょうだいするという抜本的なところが大きいものですから、そこのところをもう１回。","respondent":"福島長期計画担当課長","answer":"全文をこういう形でお示しすることにつきまして、今後長期計画を策定していく際にも検討していきたいと考えています。今回の結果については検討していきたいと考えています。","id":"exchange-011"},{"speaker":"土井委員","kind":"提案","question":"これからもこの種の形のものに区としていろいろと皆さんにご意見を伺うことも多々ありますから、「ぜひまたお聞かせください。ちょっと勝手な提案ですけれどとの意見を述べました。","respondent":"福島長期計画担当課長","answer":"先ほどご回答しましたように、確かにそういった方々は大切だと思いますので、何らかの方法、今この段階でこういう形で回答しますというのは答えられないんですけれども、何かいい方法を検討してみたいと考えています。","id":"exchange-012"},{"speaker":"菊地委員","kind":"質問・要望","question":"４ページにあります「区域の再編について」というところなんですけれど、前段で都から、これって本来の趣旨からいうとずれたものなのかどうか。１１月のときの都区のあり方検討委員会の報告が４４４項目ですか、その辺の検討状況がわかれば教えていただきたいんですが。","respondent":"日下部企画財政課長","answer":"それから４４４項目の検討状況ですけれども、今検討を進めつつあると。順次、かなり膨大な量になりますけれども、事務の内容については都と区で幹事会を中心にしまして検討が進んでいるという状況です。","id":"exchange-013"},{"speaker":"菊地委員","kind":"意見","question":"それまでの間に今のお話だけだと実際に事務配分そのものが進んでいくのかどうか。平成２０年までに決定をし、報告なり何なりあるという状況になるのかどうか、ちょっと疑問としてあるんですけれどとの意見を述べました。","respondent":"日下部企画財政課長","answer":"税財政制度、もともと３つの課題をスムーズに議論を進めるということで、３段階で設定して議論を進めてきているという経過があります。このように考えています。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問","question":"その前にもあった、今度は「都の区」じゃないんだから、「都の区」じゃないところで新たな仕事と金の水平的な分配というものを考えていかなければ。","respondent":"日下部企画財政課長","answer":"詳細は別としても具体的に進めていこうということになったとしても、相当しっかりした議論をしていかないと、まず感じてあります。いろいろな観点からの調査・検討がなされて、私どももしっかりとこの結果については、そういう１つの議論の素材としてしっかり受けとめていくと。","id":"exchange-015"},{"speaker":"土井委員","kind":"意見","question":"それに進んでいくにつけても、そこでぬくぬくと、それがいいと言っていた人は「余計なことをするな」という話になりますよね。ちょっとお考えを聞かせていただいて、きょうのところは終わりにとの意見を述べました。","respondent":"日下部企画財政課長","answer":"ですからこの報告の中では、何て言いますか、普通地方公共団体になることは現実的に財政調整の問題があるから難しい。で、いずれにしても２３区の受けとめ方はいろいろこれからあろうかと思いますので、十分な議論が必要ではないかと考えております。","id":"exchange-016"},{"speaker":"土井委員","kind":"意見","question":"そういうことを我々は目指すべきじゃないかなと思っているもので、ちょっとその辺の流れが変にならないのかなと思っただけです。意見で終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"伊藤委員","kind":"質問・要望","question":"それこそ２３区の区議会だって相談があってしかるべきだし、区民にとっても大きな問題になってくるというところまで行くわけじゃないですか。区長じゃないのに申しわけないけれど聞かざるを得ないんだけれども、そのことをやはりぜひ確認をしていただきたいので答弁ほしいと求めました。","respondent":"日下部企画財政課長","answer":"やはり区側は区側としての自主・自立を基本としたような考え方もしっかりと打ち出していくべきだという背景も１つにはあったということを。区長会そして我々区も、理事者側としてもこれからしっかりと、これを議論の素材として十分検討していく必要があるだろうと考えています。","id":"exchange-018"},{"speaker":"伊藤委員","kind":"質問・要望","question":"という要望ぐらい、内容がすごく刺激があり過ぎるじゃないですか。ある意味私たちが言い続けてきた中にもあるんだけれど、やはりそれは議会の報告とか情報提供をぜひお願いしたいということですが、答弁を。","respondent":"日下部企画財政課長","answer":"区民の皆さん方を巻き込んで、やはり皆さん方が考え方を１つにして、非常に運動としての盛り上がりがあったと。そういった意味では私どもは議会でもしっかりと、これからの推移を含めてご報告するということは当然のことではないかと考えております。","id":"exchange-019"}]},{"id":"topic-02","title":"移ってまいります。予定表の３、行政視察の報告書","agenda":"移ってまいります。予定表の３、行政視察の報告書","exchanges":[{"speaker":"土井委員","kind":"意見","question":"だからそこのところはぜひ気持ちをくみ上げて、ちゃんと預かれるルール化をしてください。お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"質問","question":"それはどこから出されているかということと、現実にどうしているかということですね。それを説明するよう求めました。","respondent":"桑村総務課長","answer":"１００万円につきましては区長が立て替えるということがあったわけですが、今現在、副区長が立て替えている状態です。施設から預かったお金、それから１００万円については副区長が立て替えたもので、相続人にお支払いしたというものです。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325034?Template=document&Id=1774#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":36475,"voices":59}},{"id":"h20-20080122-14","meetingId":"h20-cm01","date":"2008年1月22日","dateIso":"2008-01-22","committee":"行財政改革特別委員会","time":"午後１時０２分～午後３時２２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"財政（歳入）に関すること","agenda":"財政（歳入）に関すること","exchanges":[{"speaker":"山内委員","kind":"質問・要望","question":"今、単純に教えていただきたいんですが、単純な年度の幾ら取り損ねたんだという金額を教えていただきたいと思うんですけれども。１つなんですが、給食費の滞納がないのかなというのがちょっと疑問だったんですが、その２点を説明するよう求めました。","respondent":"日下部企画財政課長","answer":"現年度分が平成１８年度幾らかというご質問かと思いますけれども、今、また後ほどその辺の資料についてはお出しさせていただきたいと思います。","id":"exchange-001"},{"speaker":"阿部委員","kind":"質問","question":"これはもしやっていなければ、ちょっと一度その視点で洗っていただければと思うんですが、いかがでしょうか。年間の徴収のコストと年間の２０万円の収入額と比較したときに、果たしてどうなのかなと、ちょっとその辺のお考えを伺いたい。","respondent":"小林保育課長、金子産業振興課長","answer":"１点目、現年度分のお支払いいただいていない分と、過年度分と分けてご説明をしたいと思います。児童課との連携を考えたことがあるかというお尋ねが、児童手当の支給月をあらかじめ連携して聞いておいて… 人件費も含めて考えますと、支払っている方がいらっしゃるという現状から、これを直ちに支払い猶予するということはできないだろうと考えています。","id":"exchange-002"},{"speaker":"阿部委員","kind":"提案","question":"このことを福祉につなげていくことで、発見のツールとして活用できないだろうかとご提案させていただきましたので、改めてご答弁をお願いいたします。この件はご答弁は結構ですとの意見を述べました。","respondent":"小林保育課長","answer":"保育園のほうで対応しておりますので、別居中ですとか、そういった形で滞納に結びつく例があろうかと思います。参考として、保育料の納付はどうなっているのかという目であわせて見るという点では、活用の余地があろうと考えております。","id":"exchange-003"},{"speaker":"武内委員","kind":"質問・要望","question":"前も１回あったと思うんですが、教えてもらいたいんですけれども、５年でいいんですか。５年滞納が繰越になると不納欠損のほうに入るのかどうか、教えてほしいと求めました。","respondent":"日下部企画財政課長","answer":"地方自治法の規定によりまして大半のものは５年ということになります。そういったものについては、地方自治法の適用を受けて５年というのが消滅時効の期間、一般的にはそういうことで受けとめられてあります。","id":"exchange-004"},{"speaker":"武内委員","kind":"質問","question":"ちょっとまたその仕組みのことで教えてもらいたいのが、不納欠損になって、例えば何年かたつと不納欠損からも数字が除かれるんでしょうか。ここに今回出していただいているものは、すべて不納欠損になるのは５年ということでよろしいんですね。","respondent":"日下部企画財政課長","answer":"基本は５年なんですが、それが１つの時効の適用の前提条件になるとか、いろいろな個々のケースによって適用は違ってまいります。５年は基本なんですが、それぞれの条件がありますので、すべて一律にというわけではないということでご承知おきをいただきたいと思います。","id":"exchange-005"},{"speaker":"武内委員","kind":"質問","question":"平成１８年度になると不納欠損額がゼロになっているんですけれども、どういう理由でゼロになるのかという、そういうのがあるんか尋ねました。","respondent":"金子産業振興課長","answer":"先ほど企画財政課長が説明を申し上げました５年で時効になるというものの例外が私どもの債権でして、先ほど説明したとおり、あるいは何らかの事情。１件が、もう１件は、こういった処理をした合計が１６２万８,０００円余になっているです。","id":"exchange-006"},{"speaker":"武内委員","kind":"質問","question":"１６２万何がしというのは今の理由で、その翌年に今度不納欠損がゼロになっているということは、その理由が今の理由なんでしょうか。ちょっと私の聞き方が悪いかもしれませんが。","respondent":"金子産業振興課長","answer":"平成１８年度につきましては、今のように破産の申し立てであるとか、あるいは亡くなっているとか、そういった事実が確認できたものがありませんので、この不納欠損の処理をするものがないということでゼロになってあります。","id":"exchange-007"},{"speaker":"武内委員","kind":"質問","question":"それでまた新たに不納欠損が出てくる場合と出てこない場合があると、そういう見方でよろしいですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"まずこの全体的なことなので、滞納者がなぜ払えないのかという、そういう調査をまずするところからこの問題にあたるべきではないかなと思っています。いくのか、調査把握が私は大事ではないかと思うんですけれども、まずその区の全体的な姿勢を尋ねました。","respondent":"日下部企画財政課長","answer":"これはさっきもいろいろ収入確保の取り組みも含めてご説明させていただきましたけれども、それぞれの内容によって、基本的には納めていただく。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問","question":"ちょっとそれぞれ伺いたいんですけれども、どういった調査、把握の方法について伺わせてください。こういったポイントはよく注意して状況を聞かなければいけないと思っているところなどがございましたら、あわせて教えていただけますか。","respondent":"小林保育課長、齋藤住宅課長","answer":"そういうケースではないけれども、ちょっとお支払いするのが無理なのかというのは役所へ来ていただくという形で、本課のほうで対応をしているです。減額の対応をする場合もあり、またそうではなくて、個々の対応をやっているのが現状で… 具体的に申し上げますと、今、入居者の４３％の方が何らかの減額を受けております。減った、納付の勧奨やご相談にこちらのほうから応じることもできるということですが、今のところ大きく変化される方はいらっしゃらないです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"区のほうではその辺はどういうふうに対応されているのかなということをお伺いしたいんです。その辺の多重債務者の状況の把握というのはどんなふうに行われているのか、教えていただけますか。","respondent":"日下部企画財政課長","answer":"１点目の実態の把握ということでありますけれども、今、今後とも私どもとしましてはそういう基本的な考え方で対応してまいりたいと考えております。率直に申し上げまして、私自身も多重債務の状況について把握をしてございませんので、その辺はご容赦をいただきたいと思います。","id":"exchange-011"},{"speaker":"中塚委員","kind":"提案","question":"滞納者に対していたずらに強制執行を立てるのではなくて、まず多重債務者かどうかをきちんと調査すべきではないかという提案をしているんですね。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"林委員","kind":"質問","question":"例えば保育料の場合は、最初の山内委員の質問と同じような形なのかもわからないんだけれども、１０億９,５００万円強が平成１８年度に発生した。この保育料のところで言う３番の表を見ると、その年に払うべき保育料というふうに考えるものなのか、そこを最初に聞かせてくれますか。","respondent":"小林保育課長","answer":"それに対して右側の１０億６,１００万円余が収入できたということになるわけです。結果的に３,３３７万９,４５０円の収入未済が年度末に残ったというふうにお読みいただけるとありがたいです。","id":"exchange-013"},{"speaker":"林委員","kind":"意見","question":"１０億９,５００万円の中に、前年の未済額３,５００万円は入っているか入っていないかということを先に知りたかった。その分だけちょっと答えてくださいとの意見を述べました。","respondent":"小林保育課長","answer":"大変失礼いたしました。入っております。","id":"exchange-014"},{"speaker":"林委員","kind":"質問","question":"これはどういうふうに考えればいいんですかね。これをどうとらえますか。","respondent":"日下部企画財政課長","answer":"これが平成１８年度については３,３３７万９,４５０円になんですが、現年分、つまり平成１８年度だけで見ますと８００万円ですね。基本的に毎年度同じような傾向というのは、今申し上げたようなことで共通しているのではないか、このように私どもは受けとめてあります。","id":"exchange-015"},{"speaker":"林委員","kind":"質問","question":"保育料の場合は、一番長い人で５年間、０歳から入った人は６年間払い続けなきゃならない。そういうきめ細かさというのをとっている部署はあるんか尋ねました。","respondent":"日下部企画財政課長","answer":"３ページに出てまいりますけれども、３ページに出てまいりますように、それぞれそういうふうに段階を追って対応の仕方を変えるとか。","id":"exchange-016"},{"speaker":"林委員","kind":"意見","question":"だけど５０万円になって、１年で払うとなれば１０万円近くのお金になる。そういう返しやすいというのか、もとへ戻しやすい方法というのがあると思うんだけれども、そういうことを考えていらっしゃる部署はありますかとの意見を述べました。","respondent":"小林保育課長","answer":"保育料の場合ですけれども、滞納者の状況を見る場合に、滞納している延べ月数と総額の金額、この２つを参考に対応を変えてあります。現在抱えているのでは、一番短いものは４回払い、一番多いのは９０回払いまで持っておりますので、そういった形の中で対応しています。","id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"さっき保育課長からは現年分は８０２万円で過年度分が２,５００万円強、新たに今年から滞納が始まった、そういう人もいますよね。そうすると、この滞納というのは、毎年、額じゃなくて、人数で増え続けているんか尋ねました。","respondent":"齋藤住宅課長","answer":"住宅課長の私から説明します。過年度分は４万円ずつ払う、こういった形できちんと納めてくださる方もいらっしゃるんですが、できない方も出てくる。","id":"exchange-018"},{"speaker":"林委員","kind":"質問・要望","question":"例えば保育園にお子さんを入れていて、区民住宅に住んでいて、奨学金もという、例えば重複して絡んでいる人はいないんですか。それからもう１点は、例えば返す人たちに、今年から品川区が実施している日曜開庁のときは、この返済は受け付けているんか尋ねました。","respondent":"齋藤住宅課長","answer":"日曜開庁につきましては、区民住宅につきましては、指定管理者のほうで出張して収納する。住宅課では取らないということにしておりますので、銀行があいていない日曜日は収納はできません。","id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"それから、同じ人がいないことを祈りますけれども、それはすぐ簡単にできることでしょうから、しておかなきゃいけないんじゃないかなと思います。滞納が生じているというふうに考えられなくもないと思うんだけれども、区の責任がそういう角度から見るとあると思うんだけれども、いかが考えますか。","respondent":"齋藤住宅課長","answer":"それがまず１つと、あともう１つは、空きがある住宅に区が税を投入して、入れるためにお金を下げてしまうと、オーナー間の不公平が出ます。","id":"exchange-020"},{"speaker":"林委員","kind":"意見","question":"例えば月に保育料が３万円ですというところを、３万円が入ってこない、滞納になっていくわけです。それは入っていたら入っている人が払うべきだけれども、区の責任で区が滞納しているというふうに考えることはできませんかと聞いているんですとの意見を述べました。","respondent":"齋藤住宅課長","answer":"率直に申し上げまして、サブリース契約、民間でもあります。１棟借りをするという契約での、空いていないのが滞納だというのは、ちょっと違うかなと私は考えております。","id":"exchange-021"},{"speaker":"原委員","kind":"質問","question":"ですから、１０％減額してあげますよという、民間で言うところのおまけですよという感覚になると思うんですね。というのは、我々委員も歳費ですから、動いても動かなくても同じ数字が入ります。","respondent":"齋藤住宅課長","answer":"おおむね９５％が合格のラインのようでして、１,０００人いらっしゃると、どうも事情が苦しい方もいらっしゃる。そういった意味で言うと、そういったきめの細かさが高い収納率につながっていると考えておりますので、引き続き１００％に向けて努力をするです。","id":"exchange-022"},{"speaker":"原委員","kind":"質問","question":"実際の問題、他区なんかの場合には８０ちょい超えから９１～２％がいいところだろうという感覚を持っています。さっき一般的に５年というところなんですけれども、２番、３番について期間を教えてほしいと求めました。","respondent":"齋藤住宅課長","answer":"１０年に延びたものの滞納督促を去年ちょっと一生懸命やったんですけれども、その場で差し押さえもできるものであれば、なかなか債権調査はできない。いっぱいお金をかけても取れなければなかなか難しいということでもって、この滞納繰越分がなかなか上がらないです。","id":"exchange-023"},{"speaker":"原委員","kind":"質問・要望","question":"そうしましたら、先ほどご説明いただきました民間の信用保証機関ですか、この辺を今以上に活用いただきたいと要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"数点お伺いしたいのですが、９４％以上が口座振替で、これは納付書で納付をしている方を基本的には滞納しているという考えでよろしいのでしょうか。奨学金を中学３年生の場合、返す時期が約４年後ぐらいになってしまうと思うんですが、その４年の間に何らかの周知はされているんか尋ねました。","respondent":"小林保育課長、鷹倉区民課長","answer":"ないしは口座を持っているけれども、口座振替にしたくないという形で口座振替のご依頼をちょうだいできないケースです。収納率は現年度分からいいますと９９％を超えておりますけれども… したがって、学校に対してどういう状況になっているかということも聞けることはありません。まだ債権債務関係というのはなかなか理解しにくい部分もありますので、そこのところを借りたのはあなた自身ですよという動機づけをしています。","id":"exchange-025"},{"speaker":"石田（慎）委員","kind":"提案","question":"やっぱり４年間というのは非常に長いものでして、できたら年に１回でも、ご提案をします。その件数等をお聞かせほしいと求めました。","respondent":"鷹倉区民課長","answer":"平成１８年度で言いますと、公立３７、私立３３、７０件の方に貸付をしているということです。先ほど返す１年ぐらい前からそういうお手紙という話なんですが、今、創意工夫していきたいなと思ってあります。","id":"exchange-026"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"例えば品川区に住み続けているとか、品川区の会社に勤めるようになったとか、そういった率というのがもしわかったら教えていただきたいんですが。","respondent":"鷹倉区民課長","answer":"品川区からほかの学校に転学された方というのは、数件あるかないか、１件あるかないかということです。修学が３年間継続していける方で、それがまさに勉学意欲がある方ということになりますので、途中でやめられないようにいろいろ考慮しています。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つ大きなところでお聞かせいただきたいのと、保育料の滞納の階層別のところの分布状況がわかるような資料があったら教えていただきたいのと。現年度分は減額があるので払えるはずだというご答弁があったので、その辺の減額の内容をもうちょっと具体的に説明を求めました。","respondent":"日下部企画財政課長、齋藤住宅課長、小林保育課長","answer":"住宅料、いろいろ先ほど来ご説明していますように、その支払い能力にある程度見合った形でのご負担をいただくという前提で出発をする。… したがいまして、原則、標準的な意味においては、滞納が発生するということはないんだと思います。季節的に出っ張り引っ張りがあるとか… １件あたりは２万４,２００円余ぐらいですので、申しわけございませんが、直接的には階層を知る手がかりとしては不十分かなと考えています。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"免除されるという制度があるのかどうか、数がわかったら教えていただきたいのと、あとワーキングプアも生活保護基準以下の世帯がどんどん増えている。区政全体的に区民の実態をどうとらえていらっしゃるのかなというところを、ぜひ今の機会なので伺いたいんですが、いかがか尋ねました。","respondent":"小林保育課長、日下部企画財政課長","answer":"平成１８年度実績で減額の件数と主な理由といたしましては、件数が１４７件、理由といたしましては世帯員の増が７２件とほぼ半数です。それ以外に収入減、あるいは障害を持つ方の新たな認定等です。３４万区民の生活実態というのはさまざまですので、なかなかこれを一律にどうということであらわすというのは、現実問題非常に難しいと思います。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"提案","question":"内閣のほうで提案されて、お金が戻ってきたところで、税金とか国保料の滞納を改善したケースというのが結構生まれているんですね。そういった面では滞納の原因をしっかりとつかんでいくというのが、まずその実態を調査して把握をするということが１番であるし、いかがか尋ねました。","respondent":"日下部企画財政課長","answer":"区としても相談の中で対応する、いろいろな専門家がアドバイスをする、こういう対応をしているということが１つ。いろいろ難しい問題がありますが、いろいろな面から対応していくということがまず一番基本だと考えていますので、ご理解をいただきたいと思います。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多重債務とかサラ金の問題なんかは、区民相談なんかで今も実施をされていますけれども、ぜひ区のほうで積極的に区民の実態を把握するという意味で、相談の充実をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"金野委員","kind":"質問・要望","question":"１つだけ確認というか、教えていただきたいのが生活保護費の弁償金のところなんですけれども、その遺族年金で収入がありました。そこら辺の減額、支給されることによってその人が持つ生活費というのは、どの程度なんか尋ねました。","respondent":"志村生活福祉課長","answer":"例えば１万６,０００円だとしますと、８万円から引いた残り６万４,０００円が生活保護費として支出する、こういう関係になっております。その部分は資力があったという判断に立ちますので、その時点に立ち返って、それまで払った保護費を返していただくというそんな関係です。","id":"exchange-032"},{"speaker":"金野委員","kind":"質問","question":"そうすると、資力があるということで返すにあたって、資力の度合いによって返済をしていくのに、結構保護費の中で返済をするのが大変な方も中にはいらっしゃるかと思うんですが、その辺は現状どうなんか尋ねました。","respondent":"志村生活福祉課長","answer":"保護の継続されている方につきましては、厳密に言いますと、返してもらった分だけ最低保護基準を割っているわけですね。どこら辺までが返せるのかということで、その辺は担当のケースワーカーを含めまして、相談しながら決めているというのが実情です。","id":"exchange-033"},{"speaker":"阿部委員","kind":"意見","question":"もしあれば、どういったものがありうるのか、あるいはその種類とボリュームがわかれば、お教えほしいと求めました。例えば文教委員会などでは検討する余地はあるのか、ちょっとその辺を、区側に聞くのも変かもしれませんけれどもとの意見を述べました。","respondent":"日下部企画財政課長","answer":"私が承知している限りでは私費会計、給食費は特別な扱いでございまして、これ以外にはたしかないと思います。これは厳密に言えば歳入扱いということにはなりませんので、そういう意味から、私どもとしては具体的な項目として上げさせていただいていないです。","id":"exchange-034"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"生活保護費の中でどういう割合になっているのかというのと、奨学金貸付金元利収入も現年度分と過年度分を教えてほしいと求めました。１３９件というお話があったと思うんですが、それとも１人が何回にも分割でやるから１３９件になっているのか、その２つを説明するよう求めました。","respondent":"志村生活福祉課長、鷹倉区民課長","answer":"弁償金の中身についてご説明申し上げます。一番低かった方が１２８円で、一番高かった方が４５０万円程度というふうに、ちょっと上下があります。 ９６４万７,０００円。そして滞納分、これの残りの２,１６１万５,６００円が滞納分の未済分、先払い分についてはすべて収納されているということになります。","id":"exchange-035"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"そこら辺の扱いはどうなるのか、それをちょっと説明していただきたいのと、返済しているのは高校を卒業後１年以降の本人ですよね。他区の状況なんかは、やっぱり本人に貸しているんか尋ねました。","respondent":"志村生活福祉課長、鷹倉区民課長","answer":"お尋ねのとおりでございまして、収入済額の例えば平成１８年度の５,８２８万１,０００円、このうち現年度分が４,６００万円とお答えしました。これはそういう意味では区の収入になるというか… 返すときは口座が３６％なのでどうなんだというご質問だと思うんですけれども、返済方法につきましても、口座の引き落としについてこちらは勧誘する。","id":"exchange-036"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"これで振り込みますよという承諾をもらうときに。そのほうが今後の回収を考えていくと、どういう条件でできないのかわからないんだけれども、その規定は改正することができればと思うんですけれどもとの意見を述べました。","respondent":"鷹倉区民課長","answer":"自動引き落としの場合は、ご本人が金融機関に行ってその申し込みをしていただくというのが基本で、公共料金と同じですね。自動引き落としをお願いしますという形で、そういう形の行動をとっていただくように勧誘する、強く勧めるということまでかなと考えています。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/817079?Template=document&Id=5832#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":39467,"voices":92}},{"id":"h20-20080123-16","meetingId":"h20-cm01","date":"2008年1月23日","dateIso":"2008-01-23","committee":"街づくり特別委員会","time":"午前８時５０分～午後４時１４分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/183026?Template=document&Id=6358#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":1140,"voices":6}},{"id":"h20-20080222-3","meetingId":"h20-c-budget","date":"2008年2月22日","dateIso":"2008-02-22","committee":"予算特別委員会","time":"午後２時４５分～午後２時５３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/170168?Template=document&Id=890#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":2261,"voices":18}},{"id":"h20-20080225-6","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"区民委員会","time":"午前１０時０３分～午後２時０３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今回こういう改悪というんですか、２割になるんですよというお話をしたら、ほんとうにそういうような反応があったんです。随分と、平成１７年度、１８年度のこの２００万円の方の保険料というのはどのように変化していったのかというのを改めてお伺いしたいんですが。","respondent":"原国保年金課長","answer":"平成１８年度は４万７,３００円、それから平成１９年度が５万７,０００円、それから平成２０年度が７万３,０００円。細かいところは別にしまして、７万３,３００円余です。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"保険料がどうなるのかということを聞きに行ったんですけれども、その人は７５歳以上なので、もっと負担が重くなっちゃうということなんです。ちょっと待ったという立場で頑張るべきだと思うんですけれども、質問なんですけれども、その辺の認識はいかがか尋ねました。","respondent":"原国保年金課長","answer":"１９年度、また２０年度についても保険料の軽減措置をお願いする形で、負担が一気に進まないようにという配慮をしています。そういった考え方でいけば、ご負担をそういった中でお願いしながら、この制度を維持、発展させていきたいと考えているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"憲法の精神、「すべての国民に対して健康的で」、健康に関してはもちろん医療というのは欠かせないですから。それをどのように考えているのかというのをお伺いしたいんですけれども。","respondent":"原国保年金課長","answer":"同じ年金の２００万円、給与所得の２００万円ですけれども、そもそも３倍近い保険料をちょうだいしてきたです。こういったように、同じ金額でありながら、大きく金額の違うところを兼ね合いをしながら進めていきたいと思っているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"どうも貧困格差を是正するどころか、所得割と均等割が平成１２年では６５対３５だったのが、先ほど説明がありましたように５８対４２になっちゃう。ちょっとこれは私としてはむしろ逆なんじゃないかなと思うんですけれども、そこら辺の認識はいかがか尋ねました。","respondent":"原国保年金課長","answer":"医療費が高くなればそこでちょうだいするものもそれなりに増えてまいるというところで来ております。所得の低い方は、均等割で計算しますと４万近くになってしまうというところを、こちらのほうもいろいろお願いをしながら実施してきているところです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"それは今後も頑張ってほしいなと思うんですが、それで各自治体にも競わせるような仕組みをつくって、そういう国が自治体ごとに医療費を適正化しろ。よくするために、あと国が国保財政に負担する部分をもっと抜本的に上げなさいというのを言うべきだし、そういう意思は区としてはありますか尋ねました。","respondent":"原国保年金課長","answer":"国の総医療費が３３兆円という中で、この中でこの４月から実施します特定健診、この医療費が約３割の１０兆円近くは生活習慣病にかかる医療費。そういった中で、また社会保障がその中で守られていくというふうに私どもは認識しております。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"要望というのはどういう要望なのかいうのを、それだけちょっと聞きたいんですけれども。","respondent":"原国保年金課長","answer":"例えば全国市長会、こういったところで、今回始まります健診等についても、それなりの負担を国のほうで負ってほしいということでの要望をしておりますし、国庫負担の４割等についても、そういったところについても増やしてほしい等々の要望をしています。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"法改正による大まかなことを伺った中で、ほんとうはやはり品川区としてどうしているかというところを伺いたいんですが、今賦課割合のところ。全体として必要なことの中で、区の支援という中で一般財源分というんですか、それがどのくらい入られているのか。","respondent":"原国保年金課長","answer":"例えば先ほどの、そういったところを一般会計の繰り入れということで、平成２０年度で見ますとそれだけでも約１０億弱お願いしていると。そういったものを踏まえますと、先ほども申し上げました５０億円前後のお金を一般会計からの繰り入れでお願いしています。","id":"exchange-007"},{"speaker":"渡部委員","kind":"質問","question":"今、国保の個人負担分という中で、滞納というのはどのぐらいあるのか尋ねました。","respondent":"原国保年金課長","answer":"５月末で出納閉鎖しますけれども、この時点でとらえますと８５.０７％ということで、残りの１４％近くが滞納です。当然こちらにつきましては、いろいろお支払いいただくための交渉等をしておりますので、その後増えてまいりますけれども、そういった数字です。","id":"exchange-008"},{"speaker":"渡部委員","kind":"意見","question":"逆を言うと、国民健康保険の制度を維持していかなければならないと思うんです。実際のところの滞納の問題等も含めた上で、これから先の国民健康保健の大まかな見通しをお聞かせいただければ、説明を求めました。","respondent":"原国保年金課長","answer":"どういった形で今後の医療保険制度を考えていくかということで、昭和３６年の発足以来、今回の改正が一番大きな改正と言われております。健診等こういったものを効果的に実施する中で、こういった対策にも力を入れながら、健康寿命を伸ばしていきたいと考えているところです。","id":"exchange-009"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"どうしてこんなに複雑なんですかと聞きたいぐらいですけれども、さっき安藤委員が質問で、３８ページの年金所得者の特に２００万円。その点が１つと、私は、負担増をしなくてはならないような国保の制度になってしまっているのかという大もとのところを教えていただきたいんです。","respondent":"原国保年金課長","answer":"この１０年になるんですか、９年になるんですか、この間に１１０億円の医療費が増えているというような実態もあります。そういった意味では、こういったものをもとに算定をしていくと、こういった数字になってまいるです。","id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"今、大もとのところを伺ったら、医療費が増えている。もちろん高齢化が進んでいるので、医療費は増えていると思いますけれども、それだけか尋ねました。","respondent":"原国保年金課長","answer":"そこに前期高齢者支援金ということで、全国で見ますと６５歳から７４歳の加入者割合が、国保を前提で見ますと非常に大きいと。国保はそういった意味では、前期高齢者交付金ということで財政措置されておりますので、そういった意味では一定の国保としては評価をしています。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"国保に関して自治体の負担がどうなのかなというのをお伺いしたいのと、均等割のところも、負担のところが医療と支援と２つに分かれましたね。この医療と支援が一体何なのかというのを説明してほしいのと、どうして２本立てになったのかという部分をご説明をほしいと求めました。","respondent":"原国保年金課長","answer":"今回は、るる説明してまいりましたけれども、非常に大きな制度改正になってあります。後期、財政調整する中で国保の負担を少なくしていく、こういったような目的の中で実施されておりますので。","id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問","question":"この間お伺いをしているんですが、国基準のところを示すと、品川区のどこで担保されているのかというのをお伺いしたいと思います。ほぼ安心はしているんですが、その辺、どこで担保されているのかというのを具体的にお聞きしたいんです。","respondent":"原国保年金課長","answer":"今までの区民健診という状況がありますので、それと比較したときに、今委員がご指摘した幾つかのものがそういったところに上がってくるです。区のほうで、国の基準への上乗せ項目ということで実施するということで決めてありますので、従前の区民健診と同等の中身で行くです。","id":"exchange-013"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"うれしいと思いますけれども、突然になくなってしまったりとか、そういう危険性はないのでしょうか。前に伺ったときに、どうその辺で住民を把握するというところにつながっていくのかというところがとても見えないので、説明を求めました。","respondent":"原国保年金課長","answer":"女性ですと９０cm以上というところが一つの基準になってまいりまして、動機づけ支援、あるいは積極的支援。民間での健保組合等々においては、そういったノウハウを使いながら、より効果的な保健指導を実施していくというところで考えているところです。","id":"exchange-014"},{"speaker":"飯沼副委員長","kind":"質問","question":"民間委託は例えばどういうところに業務が委託されるのかというのと、予算的には、すごい単純なところを委託するということなのでしょうか。その辺をもうちょっと知りたいんです。","respondent":"原国保年金課長","answer":"民間のノウハウの中でどういったことがより効果的なものとして対応が可能かということで、そういったところと連携しながら実施していくです。予算的には、新年度予算のところで３,０００万円強のお願いをしています。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"医療費というのは実際問題、日本というのはそんなにすごい多い、国際的に比べて多いものなんですかねということです。","respondent":"原国保年金課長","answer":"それから、所得割についても現行の１００分の１１７が１００分の百三十幾つになってしまうということで、私どもは考えているところです。各層で見ますと一部そういう層もありますけれども、全体的には押さえることをお願いしながら行きたいというふうに思っているところです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、どうしてもこの高い負担をお願いするしかないんだというような立場に立って説明されては困るというか、改正の部分もありますよ。１割負担を２割にするとか、そういう説明はすべきではないと思うので、説明の仕方にもかなり工夫をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"意見","question":"品川区の一般財源の中で、４７億円ほどの繰り入れをしていることも含めまして、十分対応していると思います。この議案に対して賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"山路委員","kind":"意見","question":"今回昭和３６年以来の大幅な法改正が行われたと思うんですが、これで平等になって、そういう原理からしますと賛成せざるを得ないんです。ですので、賛成との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"意見","question":"６５歳から７４歳。民間委託のプロポーザルをしているというところにおいては、保健指導のところは委託に反対をしていきますので、反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"渡部委員","kind":"意見","question":"人口ピラミッドが変わってきたときに、やはりいろいろな制度改革があって仕方がないのかなとは思います。ただ、長い目で見た品川区、これからどんどん続けていくためにはこの医療保険制度の改革は必要だと思いますので、賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"稲川委員","kind":"質問","question":"これは現行犯なのかな。注意をうながして、それがあまりにも悪質だったら過料になるという流れでいいんですか、流れとしては。","respondent":"秋山資源循環推進課長","answer":"ご質問ですけれども、まず、持ち去り行為をした者に対して持ち去らないよう現場で、それから持ち去って車に積んでしまったものについては原状回復の命令をして、その命令に従わなければ、従わないということはそのまま持ち去ってしまうという状況になった場合に過料を科すです。","id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"なおかつ無視して持っていってしまったという状況になったときに、電話をかけてパトロールの人が来たときにはもういないわけじゃないですか。そうなった場合というのは、逆にマニュアルとかをつくっているんか尋ねました。","respondent":"秋山資源循環推進課長","answer":"逃げてしまった場合等、いろいろな状況があるかと思います。それが次回、施行の７月までに集団回収団体の方々を含めて説明会等を開いて、どういう形で持ち去り防止をやっていくかということを十分にご説明して。","id":"exchange-023"},{"speaker":"渡部委員","kind":"質問・要望","question":"１つ、まず確認させていただきたいのが、これというのは週に１回資源回収があるときのことですよね。どうなりますかというのを１つお伺いして、この答えによってはその後の質問が変わっちゃうので、まずそれを先に聞かせていただいていいか尋ねました。","respondent":"秋山資源循環推進課長","answer":"先ほど申し上げましたように、悪質な者が増えてまいりまして、悪質な者をどうにかしたいということでご提案をさせていただいたものです。ですので、まず、悪質な者をこの条例を使って区民と一緒に取り締まっていくというか、そういうことを考えてあります。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"何といったらいいのでしょうか、明らかにこの人は町会の人じゃないぞ、新聞積んで持っていっちゃうんだよねというような人も見かけるようです。いろいろな議案が「４月１日から」となっているところが、これが７月１日になっていたもので、それをお伺いできればと思います。","respondent":"岩崎環境清掃事業部長、島袋品川区清掃事務所長","answer":"集団回収と行政回収は同じ曜日で実施しているところはかなりあります。警察ではないので逮捕できないんですけれども、何とか毎回こっちが出動していって、品川はうるさいから面倒くさいなと。 それを２カ月とか３カ月の間に現場現場を押さえて、何時ごろにいつ抜き取りが起きるか、そういうのを全部把握したい。そういう準備がもろもろあるので７月に施行ということです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"意見","question":"抑止効果の罰金とかいう話だったんですが、そこがちょっと何か、どういうことなのかもう少し説明を求めました。","respondent":"秋山資源循環推進課長","answer":"上限を罰金の場合は２０万円、過料の場合は５万円ですので、罰金であれば警察の逮捕ということも可能な事例だと。現場ですぐ過料を課すということとは、またちょっと変わってきますので、その辺も含めて検討していきたいというふうに考えております。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"４月ぐらいに説明会を集団回収の方に行うと言っていたんですが、今の時点で何かどんな説明をされるのかというのがもしあれば教えてください。そういう方々に対して、過剰に、実際どうなっちゃうのかなというのがちょっと心配なんですが、それはどういうふうに回収するのか。","respondent":"秋山資源循環推進課長","answer":"それの内容の説明、順次団体の方に連絡をして説明、それから回収事業者に対しても同じような説明をしていくという予定です。それから、悪質なものをどうにかしたいということで答弁を差し上げておりますので、そういうものを何とかしたいというのが今回の条例の趣旨です。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問","question":"集団回収ではない、行政回収のほうで、今、そちらは行政がどういう回収をしているのかということと、あと、例えば、区長に認められる指定された団体になりたいといった場合は、何かそういうルートというのはできているものなんか尋ねました。","respondent":"秋山資源循環推進課長、岩崎環境清掃事業部長","answer":"行政回収の業者ですけれども、今、品川のリサイクル組合のカムズというところが行政回収の資源回収をしておりますので、ここで区長、または区長から指定された者というのは、リサイクル協同組合のカムズというのを想定しています。 そのときにトイレットペーパーを置いていったり、今は１円ぐらい払ったり、キロ１円ですね。組織的に、しかも暴力的に持っていっちゃうというところがあらわれてきているのが、最大の今回の状況だということです。","id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"町会の方が直接回収してくれる業者と契約を結んで、今持っていってもらっているふうに伺っているんですけれども、区があっ旋とかしているんですかね。あっ旋業者というのは幾つぐらいあるんでしょう。","respondent":"秋山資源循環推進課長","answer":"現在のところ、集団回収の事業者ですけれども、４５社あります。区のほうで登録している、登録というか、区のほうで把握している業者の中から選んでくださいということでお話をしています。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点だけ確認させてください。それがこういう、持ち去りの業者によってどのぐらい抜かれているかというのを。","respondent":"島袋品川区清掃事務所長","answer":"抜き取り業者がいるというので注意していますが、どのぐらいとられたというのはちょっと。申しわけありません。","id":"exchange-030"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"その辺の考え方というのかな、犯罪ではないけれどもというところで、ちょっとその辺の過料にしたところをもう１回聞かせていただきたい。１点、資源として置いてあるものはだれのものなのかという判断の根拠というのはどの辺にあるのか、ちょっと教えていただきたい。","respondent":"岩崎環境清掃事業部長","answer":"裁判所で２０万円を払いなさいと言われるというのは、品川はスピードで勝負したいというのが、今回の条例の趣旨です。今、なかなか厳しいんですけれども、検察当局と協議をしています。","id":"exchange-031"},{"speaker":"飯沼副委員長","kind":"意見","question":"過料を課すというのはちょっとどうかなとよく思ったりもするんですけれども、今のお話を聞いて、やっぱり悪質なところを取り締まっていく部分では。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"渡辺委員","kind":"質問・要望","question":"自民党として賛成します。集団回収のことで会派のほうにも多数悪質業者対策の要望は多く伺っておりますので、区民要望に沿う形と、賛成でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"配慮を求めたいのと、また違う話かも知れないんですが、ホームレスの方々の実態に合った生活支援の前進も同時に必要だと考えております。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"稲川委員","kind":"質問・要望","question":"７月１日から施行されるんですけれども、それを過ぎて以降は持ち去り行為が本当に減るように、逆に頑張っていただきたいと。町会の人たちの努力のたまものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-02","title":"平成２０年請願第１号、保険でも良い歯科医療ができるように求める請願","agenda":"平成２０年請願第１号、保険でも良い歯科医療ができるように求める請願","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"今、やはり改定によって、メンテナンスに力を入れるというふうに高まってきた機運というのがすごく冷水を浴びさせられたと言っていました。意見書が上がっているような自治体や、広がりなどについてちょっと、つかんでいるところがあれば教えていただきたいです。","respondent":"原国保年金課長","answer":"ホームページ等で確認できる範囲ということで、今のところ９区ほどの状況をつかんでいるところです。不採択が１区、それから継続保留が５区、参考送付２区、意見書提出が１区というような状況をつかんでいるところです。","id":"exchange-036"},{"speaker":"安藤委員","kind":"意見","question":"群馬の前橋とかあって、昨年の夏時点では２７市町村で採択されているということですけれども、医療機関専門誌とかに紹介される形で広がっているのかなという認識がありますがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"どういうふうに答えてくださるのかなとちょっと心配はしながらも、この辺の８０２０が、今度９０幾つでしたっけ。この辺の評価と、やはり検診の受診抑制というか、この辺が進んでいる中での進捗状況がどうなのかなというあたりはつかんでいらっしゃるんか尋ねました。","respondent":"原国保年金課長","answer":"地元の歯科医師会がやっているところを区のほうで後援しながら実施をしているという状況でございまして、それから平成１７年度が１６８名。そういったものを実施しておりまして、平成８年度からそういった事業を展開して、表彰をしています。","id":"exchange-038"},{"speaker":"飯沼副委員長","kind":"質問","question":"ずっと１２％台だったものが、平成１８年度かな、７.７％に削減をされているという。歯科医師の５人に１人が年収３００万円以下、歯科技工士の３人に１人が２００万円以下といった、把握していらっしゃることを教えていただけたら。","respondent":"原国保年金課長","answer":"１つの資料といたしまして、医療経済実態調査、これは診療報酬を改定する上での参考資料ということで中医協が使う資料になってあります。院外処方がなしのところについては、同様に３４５万円が３４６万９,０００円ということで数字が出ているところです。","id":"exchange-039"},{"speaker":"飯沼副委員長","kind":"質問","question":"１つ、そのことに対して所管の厚生労働省にご質問をして問いただしたらば、何と２０年間据え置きの項目が７３項目もあったという。やっぱり国が動かなくてはいけないなと思って、この中身はもっともだと感じているんですが、皆様いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"鈴木（真）委員","kind":"確認","question":"するとそれ以前に出た意見書ですよね。そこら辺のところを、まず１点確認したいと求めました。","respondent":"原国保年金課長","answer":"出されているのは平成１９年の４定で出されておりますので、そういった意味では今年の２月に出る前というところになってあります。","id":"exchange-041"},{"speaker":"鈴木（真）委員","kind":"質問","question":"お話を伺ったことはありますけれども、今の段階で中医協の答申が出てくる状況を待っていていいんじゃないかというお話を伺っております。どうか尋ねました。","respondent":"原国保年金課長","answer":"基本的には国民皆保険の中で、健康保険というものが基本にあっての話ですので、その中でよりよい治療をということで、こういった診療報酬が２年に１回改定されているというふうに受けとめはしています。","id":"exchange-042"},{"speaker":"山路委員","kind":"質問・要望","question":"どうしても難しい問題だと、そういうことがあるんじゃないかと思うんですね。基本的に中身は、この請願は歯科医師会全体ということかどうかわかりませんので、賛成しかねるということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"安藤委員","kind":"質問","question":"やはり今区が取り組んでいる９０１６とか、さっき言った３点というのは、そこら辺はいかがか尋ねました。","respondent":"原国保年金課長","answer":"今回の平成２０年度の改定に当たりましても、こういったものを参考に、平成２０年度は評価・算定をしてきている。こちらのほうの歯周病に係る指針の見直し、こういったものを踏まえて診療報酬の改定を行っていっているというふうに理解をしています。","id":"exchange-044"},{"speaker":"鈴木（真）委員","kind":"質問","question":"先ほど中医協の答申が出てくる中で、もう少しその状況、答申をちゃんと見きわめてから対処したほうがいいのではないかというお話を伺っております。ですから、自民党としては、状況をもう少し見計らってということで、不採択ということで考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"山路委員","kind":"意見","question":"先ほど言いましたように平成２０年度の改正案が出て、歯科医師会全体の問題としてどうかということだと思います。内容は理解できるんですけれども、その取り扱いについては不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"安藤委員","kind":"意見","question":"８０２０運動もそうなんですけれども、先ほどの入れ歯の問題ですとか、メンテナンスの問題はやってもらうということが大事だと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"稲川委員","kind":"意見","question":"私は不採択です。個人というか、やはりそういうところから上がってくるものをしっかり研究していくべきだと思いますので、不採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"渡部委員","kind":"意見","question":"ほかの区からの意見書もそれなりに出ていたという中で、２月１３日の答申に少しは生かされているのではないのかなと、まず考えます。今回は時期尚早といいますか、タイミング的に考えても不採択でよろしいかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/798229?Template=document&Id=2508#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":50371,"voices":135}},{"id":"h20-20080225-7","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"厚生委員会","time":"午前１０時０２分～午後５時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を81件整理しています。","topics":[{"id":"topic-01","title":"議案審査","agenda":"議案審査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この中で１人も上がる人はいないということで確認をさせていただいていいかということが１つです。そして、なぜ保育料が値上がりする人をつくったのかという、この意味はどういう意味なのかということもあわせてまずお聞かせほしいと求めました。","respondent":"小林保育課長","answer":"そうした場合にＤ２１はおおむね、新しい階層ですと、１,５００万円から１,７５０万円ぐらいの給与所得相当に対応することになります。ご説明をさせていただきましたように、既に１０％を超える、階層を伸ばして適正な負担をお願いすることが妥当であろうと判断をいたしました。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"その平成１９年度所得税２分の１廃止による影響で増収になった分がどれくらいあるのかということも１つ教えてほしいと求めました。それともう１つは、条例提案も今まで行ってきたことで、区でこういう提案が出されてきたので条例は出さなかったんですけれどもとの意見を述べました。","respondent":"小林保育課長","answer":"１点目の階層を新設することによって期待される保育料ですけれども、現行の人数から試算いたしますと、１,２００万円前後の保育料が見込めます。ご説明させていただきました階層の調整をしていますので、そういった意味で、この改正に至っているとご理解いただければと思います。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２３区もやっているんじゃないかなと思うんですけれども、２３区の税制改定による調整も含めて、今回どういうふうな改定がされたのかということがおわかりでしたら教えてほしいと求めました。","respondent":"小林保育課長","answer":"そうした中で、２３区の対応といたしましてはほとんどの区で何らかの対応は予定しております。ちなみに、聞いておりますところは、この４月に同じような趣旨で改定をする区は１２区前後あるやに状況を把握しています。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１２区前後が４月から改定するということであれば、それ以外の１１区が改定しないということは何かすごい保育料が下がってしまうのかなと思うんですけれども、そういうわけではないんか尋ねました。","respondent":"小林保育課長","answer":"既に実施済みの区も数区ありますし、その中で一緒に処理しますという区も三、四区あります。その他、基本的にはすべての区で何らかの対応を考えております。","id":"exchange-004"},{"speaker":"須藤委員","kind":"質問","question":"３番目の多子減額制度の拡充ということで、少子化対策の大きな財政支援になると思うんだけれども、今言った他の自治体でここまでの減額制度をやっているようなところはあるのかどうか、品川区独自のアイデアとしてこういうふうに考えられたのかどうかを説明するよう求めました。","respondent":"小林保育課長","answer":"直近の状況把握では、改正前の品川区、階層に応じて３割、４割、５割の減額をしているという区が１５区ございまして、それを下回る区もあります。したがいまして、今回改正をして品川の水準に至るという区は、大田区を含めまして、そう多い数はございません。","id":"exchange-005"},{"speaker":"須藤委員","kind":"質問","question":"大田区を含めてそう多いことはないというのは、大田区もやっていますよということなのか、大田区も含めてそう多くないというのは、大田区もやっていないということなのか、だから品川区と、あと二、三区しかありませんよということなのか、その辺を説明するよう求めました。","respondent":"小林保育課長","answer":"今回、品川区がやりますと、この内容は、５割、１割は品川区と大田区だけです。ほかの１５区は従前の品川区と同じ程度で、今回の第１回定例会にはそれ以上の拡充の方向は出されてございません。","id":"exchange-006"},{"speaker":"堺委員","kind":"質問","question":"Ｄ２１が１６９名ですか、合わせて４２２名でしょうか、平成２０年度の場合は半年間経過措置として従来どおりということですから。これについても先ほど何か２,２００万円ぐらいの予算を想定していますということなんですが、これは、ちょっと金額的なことを教えていただけますか。","respondent":"小林保育課長","answer":"つまり下期だけの実施になりますから、この影響額は単純に２分の１、本年度は６００万円程度の影響額と考えております。３点目の多子減額ですが、これを実施することによって平年度ベースで２,２００万円程度の保育料の減収となるという見込みです。","id":"exchange-007"},{"speaker":"堺委員","kind":"質問","question":"さらに多子家庭の部分が２,２００万円ですから、今の数字からいくと約１億円の減収になってしまうと。それでも、調整した後でも減収になってきはしないかなという気がするんですが、その辺はどう数字的に見込まれているんか尋ねました。","respondent":"小林保育課長","answer":"カバーできる金額というのは１億円まで行くかどうかという水準が想定されますので、その他、六千万円程度の収入の減ということにはなるかと思います。それから、今は歳入のお話ですけれども、当然、それに際しまして、事業規模が拡大しますので、支出ももちろん増えてまいります。","id":"exchange-008"},{"speaker":"堺委員","kind":"質問・要望","question":"私は今回の保育園の保育料の３点については十分理解ができると思っているんですが、それでも、若干の減収があるんですよということでいいんですかね。あるいは、今、微増、微増と言っているんですが、その辺をもう一回確認したいと求めました。","respondent":"小林保育課長","answer":"新たな弾力化云々という、その他の変動要因を別にすれば、残念ながら、保育料は今回の調整を行いましても減収となります。","id":"exchange-009"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"ちょっと伺いたいんですけれども、それは税制改定の影響ですから、やらなければ１億４,０００万円の減収になるということなんですよね。１つは税制改定の影響でこれをやらなかったらどうなのかということと、それが当然、そこは上げなかったということですよね。","respondent":"小林保育課長","answer":"先ほどご説明させていただきましたが、何もやらなければ１億円から最大１億４,０００万円ぐらいの影響額が出て、区は減収になってくると。","id":"exchange-010"},{"speaker":"宮崎副委員長","kind":"意見","question":"なぜこのＤ２２、Ｄ２３を今の時点でつくらなきゃいけないのかというのが、そこのところが今の説明だとよくわからないんですけれども。お願いいたしますとの意見を述べました。","respondent":"小林保育課長","answer":"保育料を考えるスタートは、かかる費用はだれかが負担しなきゃいけないということです。他方、合理的な運営に努めておりますけれども、協力を得る上で必要だろうというのが基本的な階層構造を設定する場合の着眼点と心得ております。","id":"exchange-011"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"保育料はだれかが負担する、確かにそれはそうだと思うんです。そういう負担を求めていくんだということなんですけれども、何であえて今のこの２つの段階なのか、もう一度そこのところをお伺いしたいと思います。","respondent":"古川児童保健事業部長","answer":"したがいまして、１番目での基本的な考え方は、２点目は全体の保育料に対する考え方を踏襲した上です。ほとんど８２％が区の負担でございまして、そういった部分については当然理解がいただけるかと、こう考えております。","id":"exchange-012"},{"speaker":"宮崎副委員長","kind":"質問","question":"この減収をどうやってバランスをとるんだという、何ていうか、心配すると。そういうふうに見えるんだけれども、そこのところはどういうふうな説明なんか尋ねました。","respondent":"古川児童保健事業部長","answer":"多子軽減をやった分を２番目のこの階層でとは毛頭考えてございません。こういう中ではＤ２１については少し大きな広がりになってきたなという中から、階層を２つ増やしたと、こういうことです。","id":"exchange-013"},{"speaker":"須藤委員","kind":"意見","question":"今、多額の所得を持っている人が大ざっぱに１つの段階というのはおかしいのでこういう整理をされたということは、また一歩前進だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"堺委員","kind":"確認","question":"先ほど何点か質疑の中で確認をさせていただきましたが、これからのさまざまな事業展開においても、そういうふうに理解をするところです。そういう面で、この１７号議案については賛成と申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"これも本当に条例提案をしてきたところですので、本来であれば第３子無料というところで私たちは提案してきたところですけれども。私は国の負担こそ求めるべきだと思いますし、子育て支援にはもっと増やすべきだというときに、反対ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"本間委員","kind":"質問・要望","question":"子育て支援の１つとして、さまざまな角度からいろいろな区民からの要望が出ている中で、これも大変よいことだなと思います。総じて、この保育園保育料につきましては賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"高橋委員","kind":"質問・要望","question":"この１７号議案に関して賛成です。１つだけ、多子減額制度がこの先、もう少し進んでいくといいと思いますので、要望だけです。","respondent":"松澤委員長、上山介護保険担当課長","answer":"これより第１７号議案、品川区保育の実施等に関する条例の一部を改正する条例について、採決をいたします。〔賛成者挙手〕 賛成多数です。よって、第１７号議案、品川区保育の実施等に関する条例の一部を改正する条例については可決いたしました。私から、第１８号議案、品川区介護保険制度に関する条例の一部を改正する条例の一部を改正する条例についてご説明いたします。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この１２月１２日に出された政令第３６５号というものは、平成１９年度を平成２０年度に据え置くことができるという中身なんでしょうか。そこの中身を１つ教えていただきたいのと、あとは第４段階の経過措置の方が２段階あって、この５つの段階のそれぞれの人数を教えていただきたいのと。","respondent":"上山介護保険担当課長","answer":"これに伴う減収の見込み額になりますけれども、約４,２００万円を推計しています。政令ですけれども、平成１９年度と同額です。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"高齢者の所得の少ない人への配慮が必要だというふうなことで判断したということなのか、そこのところを１つ確認をさせてほしいと求めました。それともう１つは、２３区の他の自治体がどういう措置をとったのかということがわかったら、その点についてもお聞かせほしいと求めました。","respondent":"上山介護保険担当課長","answer":"今回、平成１９年度と同額ということで、税制改正に影響を伴う方を対象として考えたものです。他区の状況ですけれども、昨年の秋の状況ですが、その時点で経過措置を継続するというところではっきり意思を示している区が約半分ございまして。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"何と２.８倍、本当であれば段階を元に戻してほしいくらいだなと思うんですけれども、そういうことでも。それともう１つ、これも共産党は前から条例提案もして提案をしてきたので、なぜ９６万円から１２０万円に拡大をしようとしたのかということとの意見を述べました。","respondent":"上山介護保険担当課長","answer":"今回、所得の基準を広げながら対象者の拡大を図るということでご説明をさせていただいたものなんですが、それを１つの目安とさせていただきました。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"そこを１つ教えていただきたいのと、あとは私たちがこれを提案したときも、そこの考え方はいかがでしょうか。１.１５倍となると、他区の状況というのは今回は１２０万円に上げるにあたってどう検討したのかということもお聞かせほしいと求めました。","respondent":"上山介護保険担当課長","answer":"他区の状況ですけれども、特例減額といたしまして実施している区が１８区ほどあるです。住宅も含めて考えているものです。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これは要望ですけれども、これは１２０万円に９６万円から拡大をされたというのは一歩前進というふうなことで評価はするものですが、他区はもっともっと拡大をしているという状況が大きくありますので、他区の状況も踏まえて、ぜひさらに拡大をしていただきたいということで、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"私はもっと、今、後期高齢者医療制度も入って負担増になると、そういうことへの配慮ということであれば、もっと本当に配慮してほしい。強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"}]},{"id":"topic-02","title":"東京都後期高齢者医療広域連合における決定事項","agenda":"東京都後期高齢者医療広域連合における決定事項","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これが今度、相手の生活状況を考えずに天引きという形になってしまうわけですから、相談の機会が奪われるということになると思うんですよね。もともとは老人保健法の方では認められていなかったものですから、これもまた深刻な状況をつくり出さないかなということをすごく心配しています。","respondent":"冨岡高齢事業課長","answer":"徴収の段階の対応ですけれども、十分に相談を受けた上で、場合によっては生活保護の方につなぐということもあるかと思います。慎重に対応されるものと考えておりますので、今、機械的にこういうものを適用していくものではないというふうに考えているところです。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ですから、９割近い人が病院に通院しているわけですよ。いろいろな作業を考えると、悪質な人というのはこれしかいないわけですから、逆に非効率じゃないかと思いますし。","respondent":"冨岡高齢事業課長","answer":"１点目の年金からの天引きの件ですけれども、例えばその部分はお返しするとか、それが有効であればそういう形の対応ができるかと考えています。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今の国民健康保険料に比べて後期高齢者医療制度の保険料がどう変わるのかということがわかる資料として出してほしいと求めました。そういう形で、自治体独自の減免制度というのをぜひつくれないものかと思うんですが、これに対してはいかがか尋ねました。","respondent":"冨岡高齢事業課長","answer":"そのもとにそれぞれの団体が構成団体として加入をして、一定の水準でできる限り公平な手続で、公平な保険料で出しているといういきさつがあります。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１倍からすると１.６４倍ですから、３万２,０００円が５万３,０００円になってしまうわけですから、これはほんとうに大変な値上げだと思うんです。そういうところにぜひ心を寄せて、区としての減免制度もご検討いただきたいというふうに思います。","respondent":"木下福祉高齢事業部長","answer":"これを月で見ますと約４,４００円ぐらいの負担ということでありますので、今回の広域連合、こういうような現実的な数字になっていると考えています。","id":"exchange-028"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、それは高齢者になったら病気をするのは当たり前ですから、安心してかかれる医療をつくってほしいというのが。だから、そういうところで言えば、減免制度についてはこれからの課題というふうなところでもご検討ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"須藤委員","kind":"質問・要望","question":"ですから、相当いろいろなところでこの制度についての説明をしっかりしていただくということを、まずもってお願いしたいと思います。こういう委員会の中でもきちんと説明していただくと、もう少し理解ができるんじゃないかなと思うので、そのあたりのことをもう一度お願いします。","respondent":"冨岡高齢事業課長","answer":"もちろん丁寧な説明を心がけてまいりますし、納めていただくのは７月になるかと思いますが、さらに周知に努めてまいりたいと思っているところです。","id":"exchange-030"},{"speaker":"堺委員","kind":"質問・要望","question":"そこの米印ですか、「保険料の均等割軽減については、二人世帯（ともに被保険者）を想定して算出した」。この一連のことについて、先ほどちょっと聞いたような気がするんですが、よく理解できなかったので、重ねてもう１回、ご説明をいただきたい。","respondent":"冨岡高齢事業課長","answer":"先ほどにつきましては簡略な説明でございましたので、さらにもう一度説明をします。一番下の６億９,０００万円は、これだけの経費を一般財源でお願いしたいという意味の減額という意味です。","id":"exchange-031"},{"speaker":"堺委員","kind":"質問・要望","question":"あるいは時代状況の大きな変化というんでしょうか、支え合っていくというんでしょうか、今申し上げたような高齢社会になったとしても存続。それで、住民説明会については、２９日から始まって６回のようなんですが、これで今回はしようがないという形になるんか尋ねました。","respondent":"冨岡高齢事業課長","answer":"区民の方に丁寧に、それを支える側の若い方にも丁寧にご説明するということで、今回はこういう形で説明会を開かせていただきますけれども。それに際しては、さらにご理解をいただけるよう、丁寧な説明に務めてまいる所存です。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"は掲示板とか、「説明会がありますよ」というお知らせをぜひしていただきたいと思うんですけど、どうでしょうかということです。１枚目のところで、これは今までどおり、７万円の支給ということでいいんでしょうかという確認をさせてほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"わかりやすいプリントを、資料を用意させていただいて、丁寧に説明をしてまいりたいと考えています。この部分についても、昨年１１月２０日の広域連合の議会で、一般財源で対応するということになったという状況です。","id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７５歳以上の方なので、それに胸のレントゲンも入るということでいいのかなという、その項目についてちょっと確認をさせてほしいと求めました。２月始めに突然、一つでも該当する場合は、これについてはどうなっていくのかということについても教えてほしいと求めました。","respondent":"冨岡高齢事業課長","answer":"たしか２月の説明会で、必要な検査は治療の一環として行われているために、対象者から除きたい」。具体的には、薬などの使用の有無を確認するなどの項目を設けて把握するなどの方法で絞り込みをするというようなお話をされたと聞いております。","id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうので７４歳までは健診を受けられるのに、受けられるようにしていていただきたいなと思うんですが、どうでしょうか。それと、さっき１人あたりの健診費用というのが幾らぐらいになるのかということもお聞きしましたので、その件に関してもお願いします。","respondent":"冨岡高齢事業課長","answer":"確かにそういう考え方もあるなということは言えるかと思いますが、区の方の考えとしては、初年度につきましては特定はかなり難しいと考えております。国、こちらでさらに特別に対応している部分ですので、総合的に考えながら進めてまいりたいと考えています。","id":"exchange-035"},{"speaker":"宮崎副委員長","kind":"質問","question":"ワンコインという意味がちょっとわからなかったので伺いたいのと、今、診療報酬のところについてはどういうふうな認識なのかというのを聞きたい。そこら辺のところは、行政の方は今、どういう認識になっているんか尋ねました。","respondent":"冨岡高齢事業課長、木下福祉高齢事業部長","answer":"表現が適切だったかどうか、５００円という形で、広域連合では自己負担金という形で決めております。区につきましては、負担をいただかないという方向です。高齢者の疾病状況に着目した診療報酬のあり方というのを検討していまして、在宅も含めましてターミナル期を支援できるような診療報酬ということと。","id":"exchange-036"},{"speaker":"宮崎副委員長","kind":"質問","question":"健康診査事業約１０億円というふうになっているんですが、最初から７５歳以上は半数と、考え方としてはそういうことを織り込んだ予算になっているんか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"特に、国保連合会のレセプトと突合せができるように制度上はなる予定なんですが、その部分については把握ができるようになるということです。","id":"exchange-037"},{"speaker":"宮崎副委員長","kind":"質問","question":"そこのところを考えるべきじゃないかと私は思うんですけれども、先ほど考えないというふうなお話だったんですが、何でそうなのか。そこのところが全くわからないんですけれども、どうか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"高齢者の方にも基本的に１割負担していただく、それから若い人も４割の分を負担しましょう、これで一定の整備をしてきたという経過があります。健診に対する考え方でありますけれども、国の考え方を基本にしつつも、今後ともしていきたいと考えています。","id":"exchange-038"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"改めて、東京都は広域連合がそういう対応をしましたけれども、私は、浦安市でやったような各自治体での対応を強く求めておきたいと思います。それを受けて自治体がどうするかというのが、健康診査というのは全体にやるわけですから、そういうことだってあり得ると思うんですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"須藤委員","kind":"意見","question":"先ほどもお話ししましたけれども、４月から始まる後期高齢者の条例制定、しっかり各自治体やっていかなきゃならないのは当然だと思います。それから規約についても先ほどお話ししましたとおりですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この後期高齢者医療制度ですから、制度そのものを撤回すべきだと思っているところですので、今回の条例に対しても反対です。第２６号議案の規約変更ですけれども、高齢者の保険料を軽減させるというための規約変更ですので、この第２６号議案に対しては賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"本間委員","kind":"質問・要望","question":"新しい大きな医療制度改革に伴う制度ですから、これにつきましては対象者も７５歳以上というようなこともありますので、周知に尽くしていただきたい。理解、納得していただくようなことをお願いしたいということをもって、第１９号議案は賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"高橋委員","kind":"意見","question":"第１９号議案と第２６号議案に賛成をいたします。遠くまで行けないので、八潮や南大井の方で開けるなら、お願いできればと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"須藤委員","kind":"質問","question":"区としてよかったよという点、それから財源的には東京都と区とどういうふうになっていくのかなと、そのあたりを説明するよう求めました。","respondent":"志村生活福祉課長","answer":"長々ご説明したとおり、路上生活者の対策につきましては、１区だけ、あるいは城南ブロックだけというわけにはまいりません。現在、これをご説明いたしました新しいプランですけれども、大体１９億円ぐらいには圧縮できるのではないだろうかというふうに計算をしています。","id":"exchange-044"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"路上に戻っていった方の割合とかがわかったら教えていただきたいのと、自立支援センターが現在５０名という定員ですけれども、そこら辺のところの利用率の状況を教えてほしいと求めました。","respondent":"志村生活福祉課長","answer":"いわゆる年末年始対策を行いましたので、現在はその方の対応が終わりましたので、７０％から８０％と言われてあります。月の中途でも退所される方が出てまいりますので、一概には言えませんけれども、大体同じような率というふうにお考えください。","id":"exchange-045"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ホームレスの方たちを支援している方たちの去年の路上生活者対策に関する要望書というのを見たんですけれども、食べ物が十分にないので辛い。そこら辺のところもどうなのかということと、そういう点で言えば、どういうふうに考えられているのかということもお聞かせほしいと求めました。","respondent":"志村生活福祉課長","answer":"それから自立支援ということでありますので、自立支援、緊急一時保護ということを柔軟に施設の中で対応していこうと考えているところです。この辺の対応につきましては、平成２０年度に入ってからですけれども、東京都が独自事業でこの対応につきましてはセンターをつくりまして。","id":"exchange-046"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"これは３日間、家がないわけですからホームレスというとらえ方をすれば、継続が必要なんじゃないかと思うんです。必要なところは継続し、予算の圧縮というところにシフトして縮小させていくというのはどうかなと思うんですけど、いかがか尋ねました。","respondent":"志村生活福祉課長","answer":"すみません、ちょっと私の説明が足りなくて申しわけありませんでした。この辺につきましてもそういった効果が出てまいりますのは、平成２２年度、平成２３年度ごろとお考えいただければと思います。","id":"exchange-047"},{"speaker":"宮崎副委員長","kind":"意見","question":"全体のホームレスの実態がどうなっていて、いわゆる路上生活者のほうがこうなっていく。そういうのがちょっと全体的に見えないので、そこら辺のところをわかりやすく説明してほしいと求めました。","respondent":"志村生活福祉課長","answer":"この辺が私どもが所管している生活保護からしますと、生活保護には入らないとか、入るとかという不安定就労の関係です。そういう意味での例えば生活保護を含めます、それからこの事業のこともありますけれども、その関連のものが出てくるだろうなと考えています。","id":"exchange-048"},{"speaker":"宮崎副委員長","kind":"確認","question":"そこのところを確認したいんですけれども、改めて今の東京都のほうがやっているという中身がもうちょっとわかれば、どんな実態でやっているのか。わからないんです。","respondent":"志村生活福祉課長","answer":"ですので、私どもではその中で、例えば生活保護に該当するのか、あるいは現在行っている路上生活者対策で対応がとれるのか。これを私どもが窓口の対応する中で判断をする、あるいはそうしたことに対するお答えを出していくというものであろうと思ってあります。","id":"exchange-049"},{"speaker":"宮崎副委員長","kind":"意見","question":"現状がどうなっていて、その対策がどうなっているのかというのが全然わからないところで、切り縮めていくというのが非常に心配だなと感じました。感想ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"自立支援住宅というのが６分の１ぐらいの戸数に減らしてしまうというところでも、憲法第２５条が保障されるような形で充実をすべきだと思います。ということで、この議案に対しては反対ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"}]},{"id":"topic-03","title":"平成２０年請願第２号、介護保険の改善を求める請願","agenda":"平成２０年請願第２号、介護保険の改善を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年の１１月までは特別養護老人ホームの整備は完了したという答弁だったんですけれども、私は１日も早く増設してほしい。ここでも去年の１１月の一般質問のフォローでも聞いたんですけれども、年齢、どんな人が入れているのかということをお聞かせほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"８５歳、８０歳代後半の方がそれに続いて、８０歳代前半の方がそれに続くというような状況です。介護されている方が高齢であるとか、複数の方を介護しているとか、そういう点に着目して優先度をつけているという状況です。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、８０代の前半の方でも要介護度が高かったら、在宅であればほかの困難性とかがつけば入れる場合もあるという感じでイメージしていいでしょうか。それから老人保健施設に入所している人、この中で病院に入院している人、老人保健施設に入所している人で入れた人がいるんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"ちょっと今のご質問に具体的に対応する資料を持ち合わせておりませんけれども、在宅が約８０人、その他有料老人ホーム等が７人というような状況です。個別の調査票等、データがないと申し上げられませんので、その点は勘弁いただきたいと思います。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１００歳の方の息子さんですから、この方の場合は、介護の困難性の２０点がつかないために特別養護老人ホームに入れなかったんですね。このことをちょっとお聞かせいただきたいんですけど。","respondent":"蓼沼高齢福祉課長","answer":"ただ施設に入っていることだけで、全く入所ができないのかということでもありません。そういった施設に入っている方々に対しても、一定の公平な優先順位がつくように、今見直しを進めているところではあります。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、見直しの中ではこの介護の困難性というのは、入院していようがいまいが、２０点がつくということになるということでしょうか。本当に大変な、特別養護老人ホームが必要だというふうに考えたということで、その基準を変えるということになったということか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"特別養護老人ホームについては在宅で介護が困難な方を重視して、そういった方々についての施設サービスを提供しているというものです。","id":"exchange-055"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういうことでも、この人たちが必要でないというふうに言い切れるのかどうかというのを私は改めてお聞きしたいと思います。いかがか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"繰り返しになりますけれども、特別養護老人ホームについては在宅の方を中心にという考えは変わりございません。しかし今、もう少しそういった施設に入っている方にも一定の配慮ができないものかということで、見直しを進めているところです。","id":"exchange-056"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１６万円から２０万円ということで言われていますけれども、これはなぜケアホーム西五反田と違う値段にしたのか。なぜ下げたのかということと、２点説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"今後につきましては、本会議でもご答弁申し上げましたように、ケアホームも含めて今後長期基本計画の中であわせて検討していく予定です。あるいは独自の資金で運営していこうという考え方のもとで設置をしたこともありまして、そういったことが利用料の違いに出ているところです。","id":"exchange-057"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、１６万円から２０万円に下げられるということで、建設コストの関係でそういう値段に抑えられると考えていいんですか。あれば、そうするとケアホーム西五反田と同じような利用料になるということになっていくんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"ケアホーム西五反田のほうが人の配置等を手厚く、サービスを提供しているというところが利用料にはね返っているというところがあります。そういった中で利用料につきましてはできるだけ低廉にということで、ケアホーム西五反田よりは低廉なものになるように詰めているところです。","id":"exchange-058"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで、人の配置はケアホーム西五反田と原小学校跡では、原小学校跡のほうが人の配置が少ないと、そういうふうに考えていいんでしょうか。そういう方針というのは、どうしても納得がいかないんですけれども、そこら辺のところを改めてご説明ほしいと求めました。","respondent":"木下福祉高齢事業部長","answer":"それからケアホーム西五反田について、３次募集までしたというお話がありましたけれども、そのようなことはありません。今回の長期基本計画の見直しの中で十分検討しますけれども、今回の長期基本計画の検討の中で論議をしていきたいと思っているところです。","id":"exchange-059"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"しかしお金のない人は、１００歳で要介護３の人も入れない。自治体として方向がおかしい、間違っていると思うんですけど、そこのところも含めて説明を求めました。","respondent":"蓼沼高齢福祉課長","answer":"それから特別養護老人ホームですが、要するに施設サービスについては、介護保険上は３施設というものがあります。割合で申し上げますと、そういった意味ではバランスをとりながら多様なニーズにこたえてきているという状況です。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"違うというのは利用料の問題ですから、選択肢と言われますけど、お金のない人には選択肢に入らないんですよ。それでも選択肢と言えるんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"ケアホームにつきましても実際に８１床、８０人ぐらいの方が入って、それで３０人の方がお待ちになっているわけですね。さまざまなサービスの提供を区としてはいろいろな区民の声があるわけですから、ニーズにこたえていく必要があると考えております。","id":"exchange-061"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"これは明らかにお金のある人にだけ優遇する施策であって、これは自治体としてやるべきものではないと思います。とりあえず、一たん終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-062"},{"speaker":"須藤委員","kind":"質問","question":"ですから、いわゆる施設をつくっていくことで、その保険料に影響するのかどうかということを１つ聞きたい。そういうところも大変だというお話も伺っていますので、そのあたりのお考えを説明するよう求めました。","respondent":"蓼沼高齢福祉課長","answer":"定着支援を図るという観点も大事かと思いまして、そういう意味では福祉カレッジがその機能を果たしているというふうに考えております。今後、１つには区の長期基本計画の検討がありますし、十分に今後のサービスについては検討してまいりたいと考えています。","id":"exchange-063"},{"speaker":"須藤委員","kind":"質問・要望","question":"先ほどお話を伺うと、福祉用具も医師の判断によって対応という形もとられるというようなお話がありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"在宅で頑張ってきたけれども、在宅の人はさらに先に行っちゃうんじゃないのと思うんですけれども、そこのところはどうなんでしょうか。相変わらず、病院のほうも入りやすくなると、在宅も今までのペースで入れるという保証があるんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"施設サービスが開始されれば、施設整備については慎重に、計画的にする必要があるということが言えるだろうです。それから入所基準の見直しですけれども、その中で必要性の高い方から入所していただくです。","id":"exchange-065"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"やっぱり大ざっぱなそういう試算をやったんじゃないですか、今、頭の中にあるものでも出してほしいと求めました。それとも無理やりあけるということになるんか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"そういう施設整備全体と、あと在宅のほうも非常にサービスが今いろいろなものが出てきているわけですね。夜間対応型訪問介護というサービスも品川区は始めておりますので、なるべく在宅で支援をしながら、介護が困難になったら施設入所。","id":"exchange-066"},{"speaker":"宮崎副委員長","kind":"質問・要望","question":"在宅が困難になったら入所の見通しが持てると、ずっと言うんですけど、それだったら在宅が困難になったらというのはどういう基準なんですか。施設の方が入りやすくするとかいろいろあったけど、やっぱり数を増やしていくことなしに解決できないと思うんですけれども、どうか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"きっと供給が、特別養護老人ホームの部分とケアホームの部分については検討していきますということを申し上げたところであります。今、そういうことがないという健全な運営をしているということの１つの証左だと受けとめていただきたいと思います。","id":"exchange-067"},{"speaker":"宮崎副委員長","kind":"提案","question":"それともう１つ、先ほどの在宅が困難になったらと言うけど、じゃ、これは一体だれがどういうふうに決めるんですか。どうか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"ご本人、家族の意向を踏まえながら、そのときがやはり家族あるいはケアマネージャーが在宅の限界だろうということを判断しているわけです。もう１つ、ご本人、家族の意向を踏まえたことをベースに判断をしているということであります。","id":"exchange-068"},{"speaker":"宮崎副委員長","kind":"質問","question":"低廉にと言うんだったら、一体だれを焦点に当てた考え方なんですか。どうか尋ねました。","respondent":"木下福祉高齢事業部長","answer":"それからもう一方で、十分認識をしているわけでありまして、それはまさに介護の世界でもセーフティネットということは当然あると思うんですね。そういう意味で、今回の見直しの中ではそのことも視野の中に入れていきたいというふうに思っているところです。","id":"exchange-069"},{"speaker":"宮崎副委員長","kind":"意見","question":"どのぐらいの規模でつくるのか、この場合、早く区の考えを出すべきじゃないかと思います。これを言いたいと思いますとの意見を述べました。","respondent":"山田副区長","answer":"品川区の場合は歴史を振り返ると、まずはそういったところのいわゆる低所得の方も含めて入れるというところで、整備をしてまいりました。","id":"exchange-070"},{"speaker":"堺委員","kind":"質問","question":"もう１回くどくなっちゃうかもしれませんが、基金のもののとらえ方というんですか、考え方というんですか。その辺のところもう１回ちょっと教えていただけますか。","respondent":"蓼沼高齢福祉課長","answer":"サービス量の伸びを見込んで、今般の平成１８年度の制度改正の影響があって、積むような状況になっているのは事実です。あるいはサービスの量の見込みというものを考えて、次の第四期については、基金についても十分な活用をしてまいりたいと考えています。","id":"exchange-071"},{"speaker":"堺委員","kind":"確認","question":"もう１点、ちょっと今のご説明の中で確認させていただきましょうか。第三期ですか、平成２０年度、たしかおっしゃったかな。","respondent":"蓼沼高齢福祉課長","answer":"この事業計画におきますサービス量の見込みからして、保険料を一定程度低く抑えようということで、事業計画の中では予定しております。これについては、次の第四期の事業計画の中で十分検討して、円滑な活用について図っていきたいというものです。","id":"exchange-072"},{"speaker":"堺委員","kind":"質問","question":"その辺と、それからもう１つ、第四期には基金の運用について、これは保険者の判断によると、考え方によると。これも当然状況の変化によるんでしょうが、取り崩しということも、それはあり得るということなんか尋ねました。","respondent":"蓼沼高齢福祉課長","answer":"今のところは平成２０年度予算では約１,０００万円強の取り崩しということで計上しています。ですから、それに伴う給付の見込みによって保険料も設定し、どれぐらいそのまま運用していくのかということを検討していくことになるです。","id":"exchange-073"},{"speaker":"堺委員","kind":"質問","question":"大体理解できてまいりました。１点、やっぱり大事な介護保険制度ですから、安定的な事業が運営できるようにお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この枚数というのは増やしてほしいし、これは品川区と杉並区だけ、２区しかないんですよね。ただ現物から現金に切り替えるということだけで済むわけですから、なぜこれができないのか、ちょっと教えてほしいと求めました。","respondent":"蓼沼高齢福祉課長","answer":"先ほどご説明申し上げましたように、制度改正の４月実施から９月の経過措置の期間、この制度の趣旨についてご説明して。あるいは自立支援という制度改正の趣旨から照らしても、移行してきたということで、特段のこの都の助成については考えることはしなかったです。","id":"exchange-075"},{"speaker":"須藤委員","kind":"質問・要望","question":"それなりに質疑をしたので、本日結論を出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"須藤委員","kind":"質問","question":"これをしっかり認めて、それにつなげて長期基本計画というふうに段取りをとって、議会としてもしっかり発言していきたいと考えています。ですから、このものについては、まだ願意に沿いがたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-077"},{"speaker":"堺委員","kind":"質問・要望","question":"大体１２０人前後とたしかおっしゃったんでしょうか、特別養護老人ホームに入所できているという状況の説明がございました。ですから、１年にこういうことなのか、公明党としても要望しておきたいと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから区民全員をお金のあるなしで差別をしないというところでの特別養護老人ホームの増設を１日も早く計画をしてほしいと思います。ということで、この３点については採択をしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"},{"speaker":"本間委員","kind":"意見","question":"２つ目は介護保険制度の改正の中から利用実態、その２点から、そのような利用実態の中で改定がされてきたと。それから３つ目も同様ですが、以上の３点につきましては、願意に沿いがたいということで締めくくりたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"高橋委員","kind":"意見","question":"今回も副区長からその旨の答弁がありましたので、その対応を注視していきたいと思います。それにより、願意に沿いがたいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993548?Template=document&Id=3194#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":101361,"voices":192}},{"id":"h20-20080225-8","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"建設委員会","time":"午前１０時０２分～午後０時４３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"第２２号議案 品川区手数料条例の一部を改正する条例","agenda":"第２２号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"何点か伺いたいんですけれども、１番の建築基準法関係と３番の都市計画法関係についてちょっと伺いたいんですけれども、それとも区の政策判断なのか。それと区民への暮らしの問題をどう考えているのかというところなんですけれども、暮らしへの影響をどう考えているのか、そこを説明するよう求めました。","respondent":"片田建築課長、齋藤住宅課長","answer":"なおかつ昨年６月２０日に施行されました新たな法改正に基づく審査、特にこれについては国の方針ということで、厳密に検討しています。もう１つ、それを適用しているし、ほかの自治体については徴収するという考え方です。２３区の場合は、先ほど申し上げた現員現給を基にした事務費の見直しと他の２３区の動向を踏まえて、新たな改定と定めさせていただいたものです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"そこをどんなふうなお考えになっているのか伺いたいのと、逆にだからといって、ほかの自治体が進んでいる間に、品川区だけは取りませんよと。こういう関係もまたどうなのかなというのはあわせて疑問に思うので、ただそこに疑問が残るので、そこをちょっと説明を求めました。","respondent":"齋藤住宅課長","answer":"手数料の決まりというのは根本のご質問ですので、なかなか説明が難しいんですが、例えば使用料であれば使用の対価です。２３区での事務の統一性という部分が大都市の中ではありますので、公平の観点から、今までのところは他区との均衡を図るものです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"それはそれとして、反対まですることじゃないんだけれども、どうもその点は腑に落ちないなとは感じるんですね。それからもう１つ、どれくらい時間がかかったかと、今回のこの手数料の中でどれくらいの割合をそういうふうに考えているんか尋ねました。","respondent":"齋藤住宅課長、片田建築課長","answer":"１万３,９４５円かかるので、端数を引いて１万３,０００円、こういう計算式で一例ですが考えております。審査の内容が２回３回になったり、中身につきましては、こういったモデルをもとにしながら定めていくです。 改めまして手数料を改正するときには、またいろいろな議会へのご説明をさせていただいているということで上程するわけですけれども、今回は民間でも取っているものと同額ということも含めてご理解いただければと考えております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"採算だけではない必要なものというのは、必要な仕事ということがあるわけですから、手数料の考え方については、私は納得できません。そもそも税金を納めて、給料として皆さん仕事をされているわけですから、手数料の考え方については意見として述べさせてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"井上委員","kind":"質問・要望","question":"質問の中で確認をさせていただきたいんですけれども、これは東京都も２３区も今回、同等は確認でもう一度答弁をお願いします。１７区で改定済みということで、他区がどういう動きになっているかということと、どのようになっているかということをお伺いしたいと思います。","respondent":"片田建築課長、齋藤住宅課長","answer":"ただ説明をちょっとつけ足ししますと、過去においては、計画通知、公の建築物については、一部構造等の審査が免除されていた時代が実はございました。いろいろなことも含めて適正に審査を行うということも含めて… 他区との関係でご質問がございましたが、他区は改正して２年たったので、改正をしたというのが他区のお考えです。第一回定例会で３区、それは私どもと同じ考えで実費相当分に合った、作業量が増えたということでの改正です。","id":"exchange-005"},{"speaker":"井上委員","kind":"質問・要望","question":"わかりました。建築確認のほうなんですけれども、例えばどういうところ、それについて具体的にこういうものだというのを示してほしいと求めました。","respondent":"片田建築課長、齋藤住宅課長","answer":"例えば区の建築確認の１万m2以下のもので、あるいは東京都の関係施設を区の中につくるような場合、これが基本的には対象になってきます。区が１万m2以上の大きなものを区内につくる場合… ですから、２３区とも算出根拠としては同じものです。申請手数料に転嫁したほうが、受益者負担にしたほうがいいという、こうした事務も条例で定めますので、のべつまくなしに増えるということはないです。","id":"exchange-006"},{"speaker":"阿部委員","kind":"質問・要望","question":"計画通知というものをもうちょっと教えていただきたいんですけれども、建築確認ではなく計画通知という手続をとる、そういう理解でよろしいか尋ねました。","respondent":"片田建築課長","answer":"そういうような考え方に基づいて、基準法の第１８条という条項がありまして、そこは計画通知と別建てになってあります。東京都でいえば２３区と多摩８市が対象になってありますから、そういうところが出す場合には計画通知という言葉を使わせていただいています。","id":"exchange-007"},{"speaker":"阿部委員","kind":"確認","question":"関連質問なんですけれども、１万m2が基準になって都が建築確認をするか、品川区が品川区に対して計画通知というものを出すんですか。これは手数料と関係なくなるんか尋ねました。","respondent":"片田建築課長","answer":"もし品川区が区の権限でできる１万m2以下のものを区の中で設置するといった場合には。１万m2以下のものは、区が自分でやる場合については免除規定があります。","id":"exchange-008"},{"speaker":"阿部委員","kind":"確認","question":"ということは、これまでは民間では取っていた建築確認の手数料を、これはむしろ正常な負担になっているのかなと。単に意見ですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"提案","question":"もし答えられる部分があったら教えてほしいのは、そこら辺の議論があったのかというのを教えてほしいのと、耐震関係についてはね。そこら辺のとらえ方、行政で提案するわけだから、そこら辺の判断というのは建築課のほうでよく見ないと、簡単に出してくるような気がするんだなとの意見を述べました。","respondent":"片田建築課長","answer":"１つは、実は先ほどもちょっと説明の中で申し上げましたように、多少タイミングをはかっていたという経過があります。というのは、そういう１つのきっかけになったのかなという認識を持ってございまして、このような表現をさせていただいたという経過があります。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問","question":"学校系なら中高層で済むわけですから、そうなったときに、安全なんだよね。建築課から何かのときに言うべきだと私は思っていて、これは意見だけにしておきますけれども、そこら辺はお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"須貝委員","kind":"確認","question":"改正は２３区、今、建築確認の日数も結構かかっている。増員するとか何かということももちろん大切だと思うんですけれども、その辺についてどのようにお考えか尋ねました。","respondent":"片田建築課長","answer":"確かに昨年の６月に改正施行されて、３カ月ぐらいは半分以下に落ち込んでいるということでございましたけれども、かなり戻しつつあるような状況です。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"意見","question":"今の答弁を聞くと、条例を改正して、値上げなの、値上げじゃないの。値上げするんだから、それに対するどうという話に対してちゃんと答弁がないと、簡単に全部値上げするみたいな話になるよとの意見を述べました。","respondent":"片田建築課長","answer":"今回の改正については、民間と同等のサービスに対する対価として徴収するものです。サービスの件については、これまでもそのような対応をさせていただいてきているところですので、ご理解のほどよろしくお願いいたします。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"確認","question":"今の話をすると違う方向にいっちゃうから、そこら辺をちゃんと踏まえてやってくれないと、条例を審議しているんだから。そこは確認したいと思います。","respondent":"岩田まちづくり事業部長","answer":"説明が悪く混乱を招きまして申しわけございません。それから３番の都市計画法関係にかかるものにつきましては、件数も件数ですが、これは実際の事務に伴う改定だです。","id":"exchange-014"}]},{"id":"topic-02","title":"平成２０年請願第３号、上大崎３丁目（最高裁判所・裁判所共済組合）旧みやこ荘跡地に関する請願","agenda":"平成２０年請願第３号、上大崎３丁目（最高裁判所・裁判所共済組合）旧みやこ荘跡地に関する請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もう少し経過のほうをご説明いただきたいと思うんですけれども、この請願に至るまでの品川区との協議の経過、裁判所の経過もあるのかもしれませんけれども、この経過を少し教えていただけますか。","respondent":"松代管理工事課長","answer":"その中では、みやこ荘が３月末で閉鎖するということで、今回の請願にありますような形で地元としては考えているというお話をお聞きしております。当時確認した内容に加えて、私ども先週、同じように確認をしたというところが現在までの経過です。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう少し伺いたいのは、更地にしてしばらくの間は機械警備で管理するのだと。更地の状態というのはどういう状態なのか、もう少し教えていただきたいんですけれども。","respondent":"松代管理工事課長","answer":"私もその点、どういう形で更地というお考えですかと聞きましたら、詳しくはまだ示されませんでした。こういった場合、ほこり等の対応が周辺から出るので、そういったことが周辺にないように対応してまいりますというお話で終わっているところです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区自身が当事者じゃないんですから、最高裁判所とのやりとりの中で、１本の道を開くべきじゃないのかなと思うんですね。最終的には品川区で購入していただきたいんですけれども、総合危険度だけなので、そこはもうちょっとご説明いただけますか。","respondent":"松代管理工事課長","answer":"そこを緊急的な対応して優先的に災害対策を施しましょうというふうに位置づけておりまして、区内にこの危険度の高いところが５カ所あります。道路の拡幅であったりしておりますけれども、そういったところを重点的に今、事業を展開しているということを説明したところです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"火災危険度２ということは、そういうお宅もあるわけですから、それはちょっと暮らしをよく見ていないんじゃないかなと。３割、７割の首都直下型地震を目の前にして何とかやっていかなきゃいけないという、いかがか尋ねました。","respondent":"松代管理工事課長","answer":"１点は、もう１点は財政面ですけれども、もし購入するとすれば二十数億円になろうかと思います。そういったことから、すべてを勘案したものです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に質問なんですけれども、仕組みとして教えていただきたいのは、国の土地と言っていいのでしょうか。２０億円というのはそういうのも含めたのか、それとも国と価格についてはまだまだ余地があるのか、その仕組みをちょっと教えていただきたい。","respondent":"松代管理工事課長","answer":"財務省のほうが普通財産として売買等の手続になろうかと思います。その際は、将来何に使うかによって、当然いろいろと価格の点で交渉等があろうかと思います。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問","question":"もう少しその仕組みを教えていただけますか。どれくらい、半額になるのか、その辺がちょっとわからないので。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"それはケース、ケースによって違いますし、基本的には国が持っておりますので、国の判断によります。官舎等、またこういった施設を積極的に活用もしくは売り払いをしていこうということを方針に掲げておりますので… 現段階では、最高裁判所のほうはこの土地をまず自分たちとしてどのように再利用するかを検討中であるというお答しかいただいていないわけです。","id":"exchange-020"},{"speaker":"井上委員","kind":"質問・要望","question":"そういうことを地域の中でご要望されるかどうかわかりませんけれども、そういう認識が区のほうにあるかどうかということを１つ確認したいんですが、いかがか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"それと１点目のこの請願につきましては、望む声があるということは、これは私どもも公園を所管するものとしては十分認識しております。こういう苦しい財政状況を今、管理工事課長がご説明させていただいたわけです。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問・要望","question":"区として民間売却がされないように定期的に情報収集を徹底していただきたいなと、地域の方に早め早めに情報を流していただきたいなということは、強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは活用は、逆に言うと、検討しているんだけれども、いつごろまで検討されるんですかというのは、聞くぐらいは聞いてもいいと思うんだな。逆にここに約１,０００坪あるわけですから、活用の中で、例えばちょっとした官舎を建ててもらってもいいわけ。","respondent":"松代管理工事課長","answer":"非常にクールで厳しい対応で、まさに今、検討中だということの繰り返しでございました。ただ最後に、地元からの照会等にはきちんと対応しますということだけは言っていただきました。","id":"exchange-023"},{"speaker":"石田（秀）委員","kind":"意見","question":"それでちゃんと話も聞いてくれるけれども、そういう形の中で行政側もできるだけ後押しをしていくというほうが、いろいろその中で話ができる。１回そういう場をつくれるような形が、私はこれは趣旨をしっかり受けて、しっかりその趣旨で扱っていただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"阿部委員","kind":"質問・要望","question":"もちろん公園の提供なんかも考えていただきたいし、まさに裁判所の職員の方々がこの地域の住民にもなっていくわけですね。ここは大変広い土地で、例えば一部だけでも切り分けて入手する可能性くらいはあるのかどうか、その辺を伺いたいなと思います。","respondent":"松代管理工事課長","answer":"そういうことをいろいろと諸条件をきちんと整理した上で交渉に臨む必要があると思いますので、今のところは想定的な部分ではお答えできない。は３,０００m2のうちの何分の１かというところで、そういったものをそのときそのときになってまた考えさせていただきたいと思います。","id":"exchange-025"},{"speaker":"阿部委員","kind":"質問・要望","question":"こういったことは本当にタイミングと情報戦だと思いますので、コンタクトはとりつつ、ぜひ頑張ってほしいと求めました。これで終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"三上委員","kind":"質問・要望","question":"比較的こういうところですから、それはそれで、こういうことでお願いするしかないかなと考えています。そういった点で要望はぜひとも品川区としても申し述べていってもらいたいと思います。","respondent":"松代管理工事課長","answer":"今、委員からお話がありました隣接する目黒宿舎、当面建物としては残るという話を聞いていますので、将来的ことは、そういった意味では、ここの部分も、今、委員がおっしゃった官舎はすべて見直すという点の１つかと考えていますが、これは一応ご報告までです。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問・要望","question":"多くの地域の方がこれだけ要望されているということはとても大切なことなので、ぜひ住民の皆さんも直接働きかける。区のほうとしては、できるだけ住民の要望をくみとっていただいて支援していただくということで、。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論を出していただきたいと考えています。住民の方々がこれだけしっかり趣旨を述べられて、やっぱり行政側も一緒になって動くということを考えると、ぜひ趣旨採択でお願いしたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"中塚委員","kind":"意見","question":"私は結論を出すということと、態度としても採択すべきだと思います。ここに書かれている住民の方のご意見は十分理解できますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"意見","question":"その部分については趣旨採択にして、一緒になって動くというほうが、私は住民の方にとってもそれのほうがいいと思ってそういうふうに言っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"阿部委員","kind":"質問","question":"住民と区のほうで裁判所と交渉していかなければいけないというスタートラインであるわけですから、住民の方と区が大きくは同じ方向を向く。その土地について考えていきたいという案を示す意味でも、趣旨採択という形でいくのがいいんじゃないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"井上委員","kind":"質問・要望","question":"私も住民と行政と一緒の方向で取り組んでいただきたいということで、趣旨採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"中塚委員","kind":"意見","question":"今、皆さんのほうが趣旨採択ということで、全会一致の重みもありますから、ただ、僕は採択を主張したのは、住民の願いをきちんと議会が受けとめて、真っすぐ届けることが大事だと思ったのでそう述べましたけれども、私も趣旨採択ということで結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今、説明があったとおり、３年ほどですか。はがれたというのはどうだったのかなという感じで、なぜ飛んでしまったのか、業者とのやりとりの中をもう少しご説明いただけますか。","respondent":"齋藤住宅課長","answer":"業者は３８ｍの風には対応できると言っておりましたが、三cmのビスでとめる程度のものでございましたので、そもそも構造上の問題がある。私ども施工業者としては、構造上の問題だと思うというお話をいただきましたので、協議をさせていただいたです。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問","question":"これは皆さんにどうというあれじゃないんだけれども、これは多分設計上、今、問題があるというのがあれば、選んだだれかがいるわけです。生かして、風が抜ける目隠しタイプのものがあるわけですから、それはどこかの頭の片隅に置いておいていただくということをお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"２月２１日の川西絹子議員の質問で、大井林町都営住宅跡を取得し、品川区基本構想の中での活用について伺いたいと思います。住宅の取得に関するところで、もう少し詳しい状況が聞けたら伺いたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759088?Template=document&Id=3902#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":33078,"voices":96}},{"id":"h20-20080225-9","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"文教委員会","time":"午前１０時０２分～午後０時１８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"そこを教えていただきたいと思うのと、現場のところでどういうふうになっているのか、その辺を知りたいと思います。いろいろなケースとして選択できるのかどうか、朝の始業時間からなのかどうか、その辺のことを教えてほしいと求めました。","respondent":"河野指導課長、市川庶務課長","answer":"幼稚園教諭の育児休業取得状況ですが、現在私が把握している範囲内では、現段階でたしか育児休業をとっている教職員はいかなったと記憶しています。 それと、やはり仕事の実情、その上で決められるべき事柄だと考えています。制度上もそうなってあります。","id":"exchange-001"},{"speaker":"南委員","kind":"確認","question":"例えば、極端な場合、１０時から、拘束を入れて３時ぐらいになるんですか。そういうのがどうなっているのか、その辺がわからないので、背景についてもちょっと教えてほしいと求めました。","respondent":"河野指導課長、市川庶務課長","answer":"現在の品川区立幼稚園における教諭の年齢構成そのものが、非常に二極化しているのが現状です。主な層としては、新卒数年ぐらいの２０代の教員と、４０代、５０代の教員ということで、３０代の教員が非常に少ないというのが実態です。それが、先ほど説明させていただきました４つの形態を取り入れて、この中で選択しているという制度的なバックアップもあります。","id":"exchange-002"},{"speaker":"金野委員","kind":"質問","question":"今、制度の内容が、あらあら教えていただいて、よくわかりました。保護者へのお知らせというんでしょうか、園児の受ける感じとしては大変かなと思うんですけれども、この辺はどうなんでしょう。","respondent":"河野指導課長","answer":"それによっても対応が変わってくるかと思いますが、私たちで考えている方向としては、担任のかわりになる方に代理という形で担任を務めていただくという方向で検討しております。","id":"exchange-003"},{"speaker":"金野委員","kind":"質問","question":"そうすると、ふだん、クラスが、担任が何人制になっているのか、そこら辺、ちょっと勉強不足なんですが、来る日と来ない日とをその担任がした場合、代替の先生は、同じ職員でやってくださるんでしょうけれども。","respondent":"河野指導課長","answer":"あるいは講師になるのかわかりませんけれども、その学級に張りつくという形で、何らかの形で措置していくということになります。したがいまして、常勤の教員が後補充に入るということについては、今のところ無理だろうなと考えております。","id":"exchange-004"},{"speaker":"金野委員","kind":"質問","question":"その辺のところは、スムーズに、園児たちや保護者にとっても不安がないような形でぜひお願いしたいと思います。保護者への周知というか、それはどうされるんか尋ねました。","respondent":"市川庶務課長","answer":"保護者の周知につきましては、当該の園長のほうから保護者に対してきちんと説明をして、理解を求めると指導してまいりたいと考えております。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問","question":"この制度は一体どういうときに使えるんだろうかというところ、具体的に教員の方たちが使えるんだろうかというのは、ちょっと疑問なんです。その辺はいかがなんでしょう、どういう使い方を想定しているんか尋ねました。","respondent":"市川庶務課長","answer":"やはり今の次世代育成支援というか、いろいろなメニューを用意して、この少子化の世の中への対応策をというところから考えられたものだと思います。有給であるけれども、先ほど概略を説明させていただきました、フルタイムの勤務とは当然違う部分が出てあります。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"熱心な先生方が多いものですから、これは要望としてなんですが、意味のある制度になってほしいと思っています。もう一つ、退職金のところが、退職金のところがよくわからなかったので、もう一度説明していただきたいんですけれども、どういう改正なんか尋ねました。","respondent":"市川庶務課長","answer":"１２カ月をすべて退職手当の対象月数にするわけではなくて、１２カ月でしたら、３分の１の４カ月は除算しますと。つまり、１２カ月ではなくて、８カ月を退職手当の算定の計算対象にしますという取り扱いだということです。","id":"exchange-007"},{"speaker":"山内委員","kind":"確認","question":"１点だけ確認をお願いできればと思うんですが、２番の2)の勤務形態なんですが、これは４通りありますよね。例えば、この４通りからしか選べないということでよろしいんか尋ねました。","respondent":"市川庶務課長","answer":"ここにお示ししています上位の法律の中で決められて、今回その条例を改正して、この４つの区分形態をパターンとするということが決められてあります。したがいまして、この４つしかパターンがございません。","id":"exchange-008"},{"speaker":"山内委員","kind":"質問","question":"１日３時間しか無理なんですといった場合は、ａの４時間掛ける５日間という形になるので、こちらから指導するという形になるんでしょうか。これをご理解していただいて、この中からしか選べないので、どれか選べばという感じで指導していくしか方法がないということなんか尋ねました。","respondent":"市川庶務課長","answer":"実情では、この育児短時間勤務制度というものは、この４つのパターンがありますので、ここから選んでもらうことになるという説明になると思います。はその本人の事情と仕事の内容、職場の実情、それを掛け合わせた上で考えていくということになろうかと思います。","id":"exchange-009"},{"speaker":"石田（慎）委員","kind":"質問","question":"それこそ残業という形がどうしても必要になった場合に、残業に関することがどこにも載っていないものですから、これは普通のフルタイムのような取り決めのあれなんか尋ねました。","respondent":"市川庶務課長","answer":"４時間ということで、先ほど説明しましたけれども、所定の手当が出るということになるわけです。大変失礼しました。","id":"exchange-010"},{"speaker":"大沢副委員長","kind":"質問","question":"(1)と(2)なんですけれども、(1)の上段で、２番の制度概要の2)ということで理解してよろしいんか尋ねました。","respondent":"市川庶務課長","answer":"通常週休日、これは教育職員の場合の週休日については、基本的にはフルタイムの場合と変わらないというところで考えていただいて結構だと思います。何かとわかりづらい表現で、申しわけございません。","id":"exchange-011"},{"speaker":"市川委員","kind":"質問","question":"３ページに１時間当たりの給与額というのが載っているんですけれども、１時間当たりの給与額というのを、常勤の週４０時間で働く方と変わってくるということなんか尋ねました。","respondent":"市川庶務課長","answer":"フルタイムであっても、この短時間勤務であっても、基本的には額としては変わらないと。基本的にはこういう計算をすれば、フルタイムの職員とは別の時間額が、時間単位の中で出るです。","id":"exchange-012"},{"speaker":"大沢副委員長","kind":"質問","question":"３番の(1)と(2)にも、その「および」を取ると、「週休日の割振りは育児短時間勤務の内容に従い」ということが書いてありますね。「勤務時間等」と書いてあるんですけれども、「勤務時間等」というのは、週休日も「等」の中に入るんか尋ねました。","respondent":"若林委員長、市川庶務課長","answer":"では、庶務課長、(1)の勤務時間等と(2)の週休日をしっかりと分けて、関連して説明するとまたややこしくなりますので、一つ一つ明確にした上で、表現等に何か説明してもらえればと思いますが。 まず１週間で何時間の勤務かということと、１日の中で勤務時間、多少回りくどい言い方になっている。同じところに勤務時間ということが出てくる意味は、そういう意味です。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"その辺を確認したいのと、その２点が、その辺の関係を教えてほしいと求めました。","respondent":"河野指導課長","answer":"基本的には８時半から５時１５分が標準になりますけれども、８時１５分から５時というようなケースもございまして、各園によって定めているです。これは特別区人事・厚生事務組合のほうで採用選考を実施して、それぞれの区が面接等を実施して、最終的にお願いするという形です。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"人様の、規則の中では求められるわけで、教育委員会のほうで条件整備をしっかりしていただきたいということをちょっと申し上げておきたいと思います。そういうことをちょっと申し上げて、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"}]},{"id":"topic-02","title":"通学区域の取り扱い","agenda":"通学区域の取り扱い","exchanges":[{"speaker":"南委員","kind":"確認","question":"全然つまらないことで、地図で確認すればいいんですけれども、確認してこなかったので、八潮４丁目というのは、どこにあたるんでしょうか。八潮団地は５丁目なんですけれども、４丁目というのは、確認したいんです。","respondent":"古里学務課長","answer":"八潮団地の下側、住宅区域ではないんですけれども、スポーツの森がある、大田の区境のところまでが八潮４丁目です。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"わかりました。でも、公園だから、人が住むような用途にはなっていないと思うんですけれども、通学区域はそういうものなんか尋ねました。","respondent":"古里学務課長","answer":"八潮３丁目は、こちらは外していますけれども、すいません。申しわけありません。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/612972?Template=document&Id=4626#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":15465,"voices":72}},{"id":"h20-20080225-5","meetingId":"h20-cm02","date":"2008年2月25日","dateIso":"2008-02-25","committee":"総務委員会","time":"午前１０時０３分～午後０時１８分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を34件整理しています。","topics":[{"id":"topic-01","title":"議案審査の（１）第１０号議案、品川区基本構想","agenda":"議案審査の（１）第１０号議案、品川区基本構想","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"疑問に思ったことを改めて質問させていただきたいのですけれども、１回目のこの策定委員会が行われた際に、こういう分析が必要であると思います。この点でちょっと、この構想の中でそういった問題がどのようにあらわれてくるのかお聞かせ願いたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問・要望","question":"どのようにあらわれているのかを少し教えていただきたい。","respondent":"福島長期計画担当課長","answer":"もちろんこの基本構想を策定するに当たりまして、委員の皆様にはそういったことも含めまして検討していただきました。当然ながら、前のものを分析されているし、また、基本構想につきましても、事務局としても説明しています。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"そういう立場に立ったときには、当然、そのことに対する前提での記述があってしかるべきなんだと思うんですよね。ですから、この中でどう読み取ればいいのかというのがわからないので、そこをお聞きしたんです。","respondent":"福田企画部長","answer":"そう考えますと、個々の施策の評価、どこまで進んできたのか。それからそのパッケージとしての政策、これについてどういうふうに過去を振り返るか、この議論をしていきたいというふうに考えています。","id":"exchange-003"},{"speaker":"菊地委員","kind":"意見","question":"こういうものを尊重しながら、中心は一番最初の基本構想で掲げた人間尊重社会の実現だというふうにこの中で記述をされているんですよね。","respondent":"福田企画部長","answer":"先ほど長期計画担当課長が説明いたしましたように、この基本構想自身が、この基本構想の前提を記述しております。区は基本的な施策について、これを重点的に実施する、これが大前提だと。","id":"exchange-004"},{"speaker":"菊地委員","kind":"意見","question":"やはり私は人間尊重という基本的な考え方というのは、やっぱり前提の問題としてきっちりここで言及しておくべきだというふうに思っています。","respondent":"福島長期計画担当課長","answer":"品川区としてはどういう方向を向いたらいいのかということを策定委員の皆様にご検討していただきたい、不遜な言い方ですけれども。区の考え方というより、国の考え方、これがそのまま区の政策の方向性だという資料ではございません。","id":"exchange-005"},{"speaker":"菊地委員","kind":"質問","question":"区の考え方ではないということであれば、どうしてこの基本構想改定の課題について資料をもらったのかよくわからないんです。この資料だと３３％になっていますよと、そうじゃないからこそ改定の課題ということで、こうして資料として上げられたのではないのか尋ねました。","respondent":"福島長期計画担当課長","answer":"それにつけてどうするかということまで載せたものではないということで、そのための、これから先の施策を考えていくための基礎資料です。そういった意味で、区の考えが載っていないということで、あくまでこの基礎資料をもとに次の施策を考えるというものです。","id":"exchange-006"},{"speaker":"菊地委員","kind":"意見","question":"少し生活費を稼ぐみたいなお店なんかも聞くことができますし、こういう区民生活の実態があって、ここではそういったことも説明されている。だけど、あくまでも国の問題として単に出しただけでというふうに今のお話ではとれるんですけれども、もう少しそこをとの意見を述べました。","respondent":"福島長期計画担当課長","answer":"あくまでも資料の出どころが国だです。その実態を踏まえて、どのような施策を考えていくのか、それはまた真剣に考えなければいけない問題であると考えています。","id":"exchange-007"},{"speaker":"菊地委員","kind":"質問・要望","question":"第１章のところで、勤労者の生活そのものも破綻をしているものですから、この辺の記述の仕方をまず１つ教えていただきたいなというふうに思います。それからもう１つ、どうも区民生活とのギャップが大き過ぎるという感じが常にしていたんですけれども、その辺もちょっとお聞かせ願いたいと思います。","respondent":"福田企画部長","answer":"今はようやくのこと経済成長２％、やはり日本経済は力強く再生に向かっている、そのような認識です。この第１章の策定、この２つの両面、このことを課題に着目をしたものです。","id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"２％というお話がありましたけれども、実質的には勤労者、この１０年ばかりで６％からは７％くらい下がってきている実態があるわけですから。区民の暮らしというのはますます苦しさを増しているという状況下にあるんだと思うんですけれども、もう一度その辺をお聞きしたいんです。","respondent":"福田企画部長","answer":"とりわけ中小企業、これがマクロ経済の回復に従って同時並行的に回復しているというふうには必ずしも考えられないようなデータも確かにあります。この１行目にありますように、大局的にはここにありますように経済再生、こういうふうに言っていいのだろうというような認識です。","id":"exchange-009"},{"speaker":"菊地委員","kind":"意見","question":"どうしてもそこは実際の私たちの区民生活から見れば、やっぱり区民生活というものに目を向けた形での第１章であれば第１章の中で実際に区民生活というものを記述をされるべきではないかというふうに思いますし、そこに区民生活の中にこそ軸足を置くべきだというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"浅野委員","kind":"質問・要望","question":"その中で、これは要望も含めてなんですけれども、これはすごい品川区になっていくなということが多分感じられると思うんですね。これからの長期基本計画策定に向けて、これをどのような形で職員の方に告知をし、また提供していくのかということを１点だけお願いしたいと思います。","respondent":"福島長期計画担当課長","answer":"庁内のイントラ等を使いまして周知する予定ですし、区民向けにつきましても、広報紙を使いまして特集号を組んでお知らせしていくです。実は職員向けには研修も考えておりまして、職員も一緒になって勉強しましょうということで、基本構想の研修も開かれる予定です。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問・要望","question":"このことを明確にすることが求められていると思うんですけれども、でも、この文章全体の中でもどうしてもそうした行政の責任としての部分が。以上の理由で第１０号議案については反対します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"基本構想ということですから、現行のこと、新たな方向というものをそれぞれお話があったんだろうと思うんですね。それを言葉にまとめるわけですから、なかなか難しいことだと、これだけの言葉の経緯、大論文をつくるのではありませんので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"中身は非常に真剣なことになるものですから、やっぱり大切なことは、これを区長会がどう受け取っていくか。そのところの今の方向性をお聞かせいただきたいのと、それから、そんなことをお聞かせほしいと求めました。","respondent":"濱野区長","answer":"それからもう１つは、これは先ほど申しましたような広範な区民運動が必要になってくると思いますけれども、その３つだろうというふうに思います。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、意見になっていますけれども、もしこれで、今、濱野区長の個人の意見は聞きました。これを推進していくのであれば、状況に応じてぜひ報告を議会にもしていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"菊地委員","kind":"質問","question":"１つだけ。基礎自治体としての役割というか、その辺の考え方をちょっとよくわからないところなので、そこだけ教えてほしいと求めました。","respondent":"濱野区長","answer":"都の区の制度、このレポートの趣旨というのは、当然その方向というのは同じことではないでしょうかというのが考え方だと。私もそういうふうに思っております。","id":"exchange-016"}]},{"id":"topic-02","title":"移らせていただきます。 議案審査の（２）第１１号議案、品川区職員定数条例の一部を改正する条例","agenda":"移らせていただきます。 議案審査の（２）第１１号議案、品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"それともう１つは、定義みたいなものがあるのかということをお聞きしたときに、どのようなチェック体制があるのかということを教えてほしいと求めました。","respondent":"榎本人事課長、堀越行財政改革担当課長","answer":"調理のほうですけれども、調理の業務代行の校数は平成２０年度で７校を予定しております。 委託に関して業務のチェックですが、これに関しては、指定管理者でもそうですけれども、現場を各所管課が確認して指導等、仕様書にのっとった業務が行われているか、それについて日常的に把握して指導を行っている、こういう状況です。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"委託ですとか、指定管理者とかとなると、いろいろな業者が手を挙げて入札で決めていくということになると思うんですね。その際のきめ方というのをちょっと確認をさせていただきたいのと、具体的にどういう、日常的にどうなのかというところをお聞かせ願います。","respondent":"堀越行財政改革担当課長","answer":"これは事業を進めるに当たっていろいろな、総合的に見直しを図りながら民間の委託導入等を決めてきている、そういう考え方です。所管のほうである程度その業務の遂行について衛生状態ですとか、チェックするというような、そういう体制をとっているというように聞いております。","id":"exchange-018"},{"speaker":"菊地委員","kind":"意見","question":"やっぱり日常的にどうチェックをされるのかというのが大変気になるところで、大間窪小学校をはじめとして３校で、その辺もお聞かせ願いますとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"事業者の執行体制ですとか、実績ですとか、そういったものを十分に評価検討して事業者を選定しているという状況にあります。それから執行状況のチェックの段階、そして区として事業者の実施主体の責任として適正に管理をしている、そのように認識をしております。","id":"exchange-019"},{"speaker":"菊地委員","kind":"意見","question":"その辺の日常的なチェックの仕方というものをやっぱりきちんと構築すべきなのではないかなというふうに思います。私はぜひとも必要なのではないかなというふうに思うんですけれども、そういう新たな体制づくりについて考えがあればお聞かせ願いたいと思いますとの意見を述べました。","respondent":"堀越行財政改革担当課長","answer":"簡易型総合評価方式、そういった形で事業者選定も行っていますので、そういった評価項目に沿った形でそのほかのチェックを行っているということです。","id":"exchange-020"},{"speaker":"菊地委員","kind":"意見","question":"それから、サービスの後退というのは、部分的には実際に起きているわけですよね。委託先の労働者にしても、最低賃金の問題も含めて、区民サービスとは何かということを考えていくことではないかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"浅野委員","kind":"提案","question":"今回このような提案ですけれども、２ページと３ページの表をいただいているんですけれども、またすべての事業が載っているわけではないんですね。ホームページでちょっと確認しましたら、平成２０年度は何人になるのか、それをぜひお願いしたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"菊地委員","kind":"意見","question":"第１１号議案については、反対をします。行政が本来区民サービスを考えるときに、あるべき姿というところから後退をした部分があるので、そうした立場で反対をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"菊地委員","kind":"質問・要望","question":"何点かお尋ねしたいんですけれども、お子さんが６歳でしょうか、この期間だったらとれますよということなんですか。特別の事情があれば、ちょっとその辺がよくわからなかったので教えていただきたいのと、ちょっとその辺の違いを説明するよう求めました。","respondent":"榎本人事課長","answer":"１回１年、１回あけてから、もう１回請求するときに１年以下だったらとれるというような形のとり方を前提としていただきます。ですから、この育児短時間勤務はとりあえずまずは１年間しか請求ができないという制度の設定のものです。","id":"exchange-024"},{"speaker":"菊地委員","kind":"意見","question":"１年間とりますよね。あけてから再度請求できるというような、ちょっとどうもそこが……との意見を述べました。","respondent":"榎本人事課長","answer":"下から２段目のところで、再度の請求というところで、ここで１年経過をしなければ再度の請求ができないというのが原則なんです。ここである程度、勤務をフルタイム勤務に目指していく方向性を示していますので、ここの部分が１年経過しないと再度の請求はできない。","id":"exchange-025"},{"speaker":"菊地委員","kind":"質問","question":"要は、期間が終了した後に、もう一度再請求ができますよということで、短時間勤務に入れますよということでとらえてもよろしいのでしょうか。この資料の３ページで、同じような育児の短時間勤務ということだと、２人で実際に任用していくみたいな考え方というのはあるんか尋ねました。","respondent":"榎本人事課長","answer":"要は、それにもう１人がいれば、正規を１人追加してしまうというようなカウントを妨げませんよという形の規定だというふうに理解しております。週２５時間勤務ですとか、２４時間勤務を選択された場合には、できないということになります。","id":"exchange-026"},{"speaker":"菊地委員","kind":"意見","question":"今の部分で、同じ職場で職員としてどういうふうな考え方で、そうした職員体制がやっぱり必要なのではないかなというふうに思います。申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"土井委員","kind":"質問・要望","question":"確認させていただきたいのが１つと、もう１つ、先ほどの延長再度請求のところのことです。組合の皆さんといいますか、職員の団体の皆さんとの間でお話し合い等がされたと思うんですけれども、その状況はどうなんか尋ねました。","respondent":"榎本人事課長","answer":"ただし、１回そこまでの最初の取得が終わった場合には、１年経過した後でないと再度の請求はできないということです。それから２点目の労働条件につきましては、職員団体それぞれの団体、労働組合に協議をいたしまして了承を得ているところです。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問","question":"資料の３ページ目（４）の2)、在職期間等からの除算というところで、期末手当、勤勉手当があるんですけれども、それぞれ文言が違っているんですが、ちょっと具体的に、例えば、週２０時間ですが、丸々１年間とった場合に、それぞれこの期間というのはどのようになるのか教えていただけますか。","respondent":"榎本人事課長","answer":"その月数で行きますと、普通ですと１２カ月の勤務がある期間とみなすのを、８カ月の勤務という形でみなして手当の計算をするという形です。３分の２は勤務したものとみなすので、８カ月勤務したものとして退職手当については在職期間をカウントするという形です。","id":"exchange-029"},{"speaker":"浅野委員","kind":"質問","question":"半分ですから、それとも４分の３になるというのか、解釈の仕方が悪かったので。","respondent":"榎本人事課長","answer":"それに対して、育児短時間勤務を週２０時間勤務するとした場合の年収ベースで行きますと、２０３万という形になります。勤勉手当が２分の１支給ということなので、その部分で年収ベースで行くと半額を上回っているという形になります。","id":"exchange-030"},{"speaker":"土井委員","kind":"質問","question":"例えばこの目黒川に関する限りにおいては、すぐ近隣に出水防止のための大きなプールを、ため物をつくってありますよね。そういうものはこういうものには何ら考慮されないんか尋ねました。","respondent":"青木都市開発課長","answer":"もちろんこれは出水期対策として設置したもので機能しておるんですけれども、集中豪雨がありますと水位が上がることは否めません。より安全を確実にすべきであるという強い指導がありまして、結果としては、出水期の施工を中止するということに合わせたものです。","id":"exchange-031"},{"speaker":"土井委員","kind":"意見","question":"そうしなければ、下手をすると、もう１つ小さな橋がかかってしまうぐらいの値段になってしまうわけですよね。ぜひそういう技術的な面も含めてこれから働きかけをお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問・要望","question":"４億６,０００万円は大変な額なんですけれども、これ、それぞれの内訳について教えていただきたい。その辺を教えていただきたいのと、もう１つ、ちょっとその辺も教えてほしいと求めました。","respondent":"青木都市開発課長","answer":"２点のご質問にお答えいたします。さらにこの鉄板を打ち込んだり、抜いたりする作業のために、地上からの作業ができませんので、台船を海から引いてまいります。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問","question":"そういう考え方のもとでこの４億６,０００万円からの新たな工事費が必要になってしまったと考えると、その辺を計画性、その辺はどうなんですか。何かの規定があってそういうことになっているのか。","respondent":"青木都市開発課長","answer":"増額変更を伴ったのは、申しわけないんですけれども、事前の段階から高い金額でのご審議をいただくことになったんだと考えています。確かにこういったことで当初の予定が狂うという点では、非常に私どもとしてもご迷惑をかけて申しわけない部分ではあるんですが。","id":"exchange-034"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325034?Template=document&Id=1776#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":44544,"voices":106}},{"id":"h20-20080226-6","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"区民委員会","time":"午前１０時０２分～午後０時１０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"確認","question":"それがソフトバンクにどのようにつながっていったのか、新たに品川区とソフトバンクが契約をしたのか、そこら辺を教えてください。ソフトバンクですと東証一部上場という大手企業同士ですから、その辺の契約関係に問題はないと思うんですが、その辺の確認だけ聞いておきたい。","respondent":"中山地域活動課長","answer":"今回の事業者変更と、これは事業譲渡ですので、この近隣セキュリティシステム事業を引き継いでいくという話が整ったという形です。そういうことの中で、安定的な運営、事業の継続性という中でこういう判断がなされたものというふうに考えていただきたいと思います。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"企業間同士のほうは事業者同士の話ですから、区はソフトバンクと契約しないで、そのままＹＯＺＡＮのままでいくということでいいわけですか。今度４月以降も、そこでソフトバンクと新たに契約するという形になるのか、その辺をもう一点確認したい。","respondent":"中山地域活動課長","answer":"新たな契約変更という手続は必要なく、ＹＯＺＡＮの契約がそのままソフトバンクに事業譲渡されるという形で、新たな契約はございません。新年度につきましては、これは新たにソフトバンクテレコムとの間で新たな新年度の契約を交わす形になります。","id":"exchange-002"},{"speaker":"安藤委員","kind":"意見","question":"最初のときに、プロポーザルのほうでＹＯＺＡＮに決まったと聞いていますけども、そのときの選定する際の区の考え方というのはどうだったのかということをちょっとざっと聞きたいんですけどもとの意見を述べました。","respondent":"金子産業振興課長","answer":"平成１７年に事業開始していまして、その前年、平成１６年度に事業者の選定を行っています。機能、意欲等々を総合的に評価した結果、結果としてＹＯＺＡＮという会社を選定したです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"意見","question":"そのときはもちろん総合的に判断して間違いないということで選ばれたと思うんですけども、今回そういう事業者の交代にならざるを得なかったという事態なんですが、何が計算違いだったのかということを……との意見を述べました。","respondent":"中山地域活動課長","answer":"ＹＯＺＡＮの判断のところは区でちょっと答えるわけにはいきませんけれども、安定的に継続する必要があるということから、区としてはそういう判断となった。","id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"区民からは３名で都民１名ということなんですが、どのようにお考えなのかということと、聞かせてくださいとの意見を述べました。","respondent":"久保田防災課長","answer":"歴史的に非常に長時間時間をかけて継続的にいろんな事業を区として、その継続性の上に立って、新たな事象なり新たな問題について修正を加えて。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問","question":"やっぱりちょっと５件というのは率直に言ってものすごく少ないし、僕の実感としては、ちょっと申しわけないんですけど。この膨大な素案をどうわかりやすく意見を伺う前の段階として説明したのかという点ではどのように総括をされているのかなというのをちょっと伺いたい。","respondent":"久保田防災課長","answer":"わかりやすくどれだけ区民の方に説明するかということになると思うんですけども、私ども９月１日に広報を出しましたときに。確かに説明責任というんですか、それはあるわけで、一般の方に薄く広く周知するのはやっぱり広報が一番かなというふうに思っています。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問","question":"確かにそうですよね。品川の地域特性というのをどう考えていて、それを今回どのようにこの地域計画に反映させているのかという基本的な考え方を説明するよう求めました。","respondent":"久保田防災課長","answer":"それの対応策として、その辺の確保をしていくという考え方が一つ、資機材の充実を図っていくと。これは品川だけじゃなくて、それから帰宅困難者対策、こういうものにどう取り組むかというのが特徴として挙げられるというふうに考えております。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問","question":"住宅倒壊と火災ということでお話がありました。ほかにも都市型災害ということですけども、特に住宅倒壊と火災の問題では、そういう意味ではどういうような積極的なお考えをお持ちなんか尋ねました。","respondent":"久保田防災課長","answer":"これに基づいて今後具体的な事業をそれぞれ進めていくわけですけれども、少なくともほかの区にない、品川区ならではの事業もこの中に組んでおります。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"細かいことで何点か確認をさせてもらいたいんですけど、これは最初が平成１２年ということなのか、まず読んでいると思います。それからあと、広報のところに、ＦＭラジオと出ていたんだけど、区のＦＭラジオというのは、どういう考え方なのか、それも説明を求めました。","respondent":"久保田防災課長","answer":"基本的な考え方として、先般ずっと実施してきたのが受水槽のセンサーを取り付けて、弁で受水槽を閉じちゃうと。日本語と外国語でもって、ほんの１分ぐらいだとたしか思ったんですが、そういうので放送もできるようになったです。","id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問","question":"皆さんに私がいろんなことを聞いた中での質問が今させてもらった部分なんですけど、あと、例えば勝島とか大井とかというのがありますよね。その辺、これからお願いしたいんですが、どうでしょう。","respondent":"久保田防災課長","answer":"被害想定自体が、これは平成１２年の人口でもって東京都のほうがカウントしていますので、平成１２年が正しいと思います。広域避難場所、それから普通の避難所というような形での周知も図っていきますので、そういう点ではより周知の努力は続けていきたいと思います。","id":"exchange-010"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"区全体でパブリックコメントといういい制度ができたんですけれども、その辺の活用をしていく工夫というのはぜひ考えていただきたいなと思っています。この辺というのは、１回目のときに、どのようなご意見が寄せられたのかわかったら教えてほしいと求めました。","respondent":"久保田防災課長","answer":"従来は１区だけではどうにも対応できないということで、東京都が中心になってこれはやっていくというような形で従来はずっと進めてきました。","id":"exchange-011"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"意見をなかなか出せないというのを私はちらっと伺ったことがあるので、なかなかこういうものに意見を出すというのは大変なことだと思うんですよね。結構みんな家が住めなくなったりしたときにどうしたらいいのかという、あと、この辺はこの計画の中にどこに盛り込まれているのか説明を求めました。","respondent":"久保田防災課長","answer":"そういうものをできるだけ解消していこうという東京都の方針があって、内陸部に内陸部にというような形で考え方を進めてきている傾向があります。しかし、この辺は引き続き区としても力を入れていくという考えです。","id":"exchange-012"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"この間、まちづくりとともに公園も防災の要素にかなり重点を入れて取り組んでいますというような話をちょっと伺ったので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"どういうふうな団体なのかなというのをもう少し聞きたいのと、そのかかわりというんですか、ちょっとその辺の状況というのを説明するよう求めました。","respondent":"田村環境課長","answer":"似たような事業は、実は３月の頭にも予定しているのが、ＩＳＯ取得の事業者交流会というのを３月４日に予定しています。その辺もＩＳＯの事業者交流会と環境支援講演会とうまくつなげられれば、待っているんじゃなくて、こちらから積極的に働きかけして。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"マテリアルなのかケミカルなのかということをお伺いしたいのと、あと、それ以降はどのようなリサイクルを計画しているのかというのが２点目です。３点目は、説明の実施の内容をちょっとお伺いしたいんですけども、その３点。","respondent":"秋山資源循環推進課長","answer":"１０月に向けての説明会の実施ですけれども、それぞれに対して説明会のご案内を差し上げて、管理組合についてご説明をする。そういう地域センター別の区民への説明会も考えてありますし、あと、あらゆるできる限りのことを行っていきたいというふうに考えております。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問・要望","question":"そういうのはかなり大きな考え方としてかかわってくると思うので、区としてはどのような方向で今お考えなのかということをお伺いしたいと思います。国内では徳島の上勝町ですかね、宣言をされているようなゼロ・ウェイストというような考え方といいますか、そこら辺の考え方はいかがか尋ねました。","respondent":"秋山資源循環推進課長、岩崎環境清掃事業部長","answer":"２２ページ以降、今後の取り組みということの中で、事業系の発生抑制等を図ってあります。ごみの減量、それからリサイクルの推進、そうしたものを働きかけていきたいというふうに考えているところです。 それは、よその都市でできるから、できないわけがないじゃないかということにはならないわけですね。それは２３区がこれから考えていかなければならない話です。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"最後に質問したゼロ・ウェイストの問題なんですけども、入口の対策をどうするかということがやはりすごく決定的に大事だとこの問題で言われていますので、それはどうお思いか尋ねました。","respondent":"岩崎環境清掃事業部長","answer":"政府レベルの計画を自治体である品川区に求められても、それはできないわけでして、それぞれ役割分担の中で資源循環推進のための仕事をしていくです。","id":"exchange-017"},{"speaker":"飯沼副委員長","kind":"質問","question":"埋め立てに持っていっているごみの８割が事業系、家庭系は２割、ごみの減量はないんではないかというところがまず一つ大きくあるわけです。ちょっと教えてほしいのは、５ページのところに「管路」、表のところに「管路」とありますよね。","respondent":"秋山資源循環推進課長、岩崎環境清掃事業部長","answer":"それから、５ページの「管路」というものがありますけれども、その中をごみが通っていくという方式がお台場の地域で行われております。５ページの表－３の持込ごみ量は事業系の、区収集の右側に持込ごみ量というのがありますけれども… そっちのほうに持っていったらどうかというようなものの考え方で平成２２年度末をもって埋め立てはできないんだというような話になってきております。","id":"exchange-018"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"先ほど部長が教えてくださった区の流れ、産廃の部分、これをあわせたものが大きい意味で事業系というところですよね。その点を１点と、リデュースのところをどのくらい力を入れてらっしゃるのかなというのをちょっと改めて伺いたいのと、その辺はいかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"今後の取り組みというところで書かれておりますし、そういう中で家庭での発生抑制というのを続けていきたいというふうに考えております。それから、容器包装プラスチックの収集ですけども、全部分けずに収集をしてはですけども……。","id":"exchange-019"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"石油製品を燃やすということは、私は環境問題の一つとしてしっかりとらえていってほしいし、燃やさない決断をしている自治体があるわけですよ。ぜひ広く意見を聞いて、今後の方向にも生かしていってほしいと思っているんですが、その辺はいかがか尋ねました。","respondent":"秋山資源循環推進課長","answer":"もちろん説明会というのは分別の変更、説明会に当たってもちろんそういう点を踏まえてご説明をし、質問等があれば十分に答えていくということで考えております。","id":"exchange-020"},{"speaker":"飯沼副委員長","kind":"質問","question":"どう分別をするのかという説明はとっても丁寧にされていたんですけれども、サーマルリサイクル本体の説明がほとんどなかったんですね。ちょっと最後の質問なんですが、どのくらい回収されているのか、ちょっとその点を説明するよう求めました。","respondent":"秋山資源循環推進課長","answer":"効率ですけれども、品川区のごみが品川清掃工場で今現在発電の効率が１８％というふうに一部事務組合のほうから聞いてあります。この１８％という数字は比較的工場の中では効率がいいほうだというふうに一部事務組合のほうから聞いております。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/798229?Template=document&Id=2510#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":38547,"voices":68}},{"id":"h20-20080226-7","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"厚生委員会","time":"午前１０時０２分～午後 ４時１８分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を23件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今度９時から１８時までになりますけれども、１日６名程度で、月曜日から金曜日までやっているということでいいんでしょうか。４カ月から就学前までの各年齢の子どもたちが６名制度、いつでも予約をして利用するようになるのか、そこら辺のところも説明を求めました。","respondent":"小林保育課長","answer":"２点目の東五反田保育園に関するお尋ねですけれども、平成２０年度より、保育課のほうで担当するという形で予定をしております。手続上、受け入れが可能ならば、前日までお電話等での予約に、現在、対応しています。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東五反田は、児童センターの１室をオアシスルームという形で使って、保育課がそれをオアシスルームとして管理するということでいいんでしょうか。６名程度に対して、どういう方がどれぐらいの人数で保育される体制になっているのか、人的な体制についても教えてほしいと求めました。","respondent":"小林保育課長","answer":"そして運営等を一体的に行い、事業の充実、効率的な施設運営に努めていく予定です。何人だから職員何人と固定的に対応しているものではございませんけれども、目途として、施設基準をクリアするように基本的には配置をしております。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"６名程度受け入れるということで、平均で５６.５％ということですけれども、６名来るときもあるわけですよね。そういうところで言えば、６名に対しての保育士の配置というのは、どういう人をどう配置しているのかというのを教えてほしいと求めました。","respondent":"小林保育課長","answer":"ご説明させていただきましたように、急に預かる人数が増えることもありますので、若干の余裕を持って対応しているということです。乳児で一遍に６名ですと、２名では足りませんので、人数が確定した中での職員の配置フォーメーションで対応しているという状況です。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"オアシスルームそのものを業務委託ということはないんでしょうか。そこのところも、あわせて、体制的に教えてほしいと求めました。","respondent":"小林保育課長","answer":"平成２０年度の実施予定でご紹介をさせていただきたいと思います。平成２０年度なんですけれども、保育園でやります７園のうち、業者に委託して実施する予定です。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"オアシスルームそのものだけを丸ごと業者に委託をして、毎日２人ぐらいの保育士で業者が請け負って見ているという感じなんでしょうか。そういうのは、いろいろ形態がそれぞれ違うというのは、何か理由があるんか尋ねました。","respondent":"小林保育課長","answer":"再三ご説明させていただいているように、各園の状況、利用実績等が違います。運営の仕方に対応したマンパワーを配置していくという考え方の中で、人材派遣、多様な雇用形態を活用して合理的に仕事に対応していくという関係で。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから水神でも正規プラス非常勤ということですが、この正規職員というのは、それぞれ１名ずつなんでしょうか。オアシスルームをやることによって、正規職員を増やしているという考え方でいいんか尋ねました。","respondent":"小林保育課長","answer":"そのときには６園で実施し、平成１７年６月にもう５園追加で実施して、マックス１０園で対応してきております。あくまでも需要対応、今後も適宜、その中から最も必要なところに必要な数を設置していくという形で対応してまいりたいと考えています。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"オアシスルームは、最大のときは１０園あったわけですけれども、今は８園ということで、１０園では多すぎるということで８園になったんでしょうか。委託そのものもどうなのかという思いがするんですけれども、そこら辺のところは、いかがか尋ねました。","respondent":"古川児童保健事業部長","answer":"実施園が８園でいいのかどうかも、在宅子育て支援をこれからもまた充実していく方向にありますから、人材もそうです。今日のお答えが明日も同じとは限りませんので、非常にお答えするほうも動いていますから、流動的な中で事業を実施していきたいと考えております。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"流動的に動いているというところもわかりますけれども、今のところでの、先ほど私が聞いたことに、お答えをぜひお願いしたいと思います。とりあえずそこだけ教えてほしいと求めました。","respondent":"小林保育課長","answer":"おおむね派遣を配置しておりますと申し上げました園の数に掛ける２という形でお考えいただければよろしいかと思います。運営だとかいった売り手の立場ではなくて、どのように自分たちの人や施設を活用するのがいいのかという形での対応を行っているところです。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私も、このオアシスルームについては、充実をさせていっていただきたいという思いで質問をさせていただいています。ぜひ、職員体制のところでも、今の雇用のところできちんとした形での雇用の体制をとっていただきたいということを要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"堺委員","kind":"質問・要望","question":"やっぱりこれから求められていくのは、よくいろいろなところで言われる地域力というんでしょうか、その地域の中にある潜在的な能力を生かす。感想も含めて、改めてちょっと、その辺のご見解を教えてほしいと求めました。","respondent":"古川児童保健事業部長","answer":"それはやっぱり、マンパワーを継続して活用していく事業では、なおさら一定のシステムが必要だろうと思います。申し上げましたような地域のマンパワーを大いに利用できるようなシステムも、今後、十分に構築していきたいと考えております。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういうことがあった場合に、品川区の保健所の役割はどういうことになるのかということを、改めてちょっと教えていただきたいんです。","respondent":"平澤品川区保健センター衛生課長","answer":"食品衛生法第５５条第２項に、輸入者の処分につきましては、厚生労働大臣が行うことになっております。したがいまして、処分については、厚生労働省のほうで、今後検討されると思います。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ジェイティフーズが品川区にあったということで、品川区の保健所がそういう役割を発揮するということになるということですよね。いつごろ、どういう形でまとめられるのかということを、ちょっと説明を求めました。","respondent":"平澤品川区保健センター衛生課長","answer":"いつごろですが、まず初めに、ジェイティフーズから、毎日速報値ということで、回収状況がＥメールで報告されております。は国のほうの報告事項となりますが、今のところ、４０万ケースほど回収されていると聞いております。","id":"exchange-012"},{"speaker":"山元委員","kind":"質問","question":"品川区民から１１件の相談があったということで、その内容といいますか、具体的にどういうご相談があったのか教えてほしいと求めました。","respondent":"平澤品川区保健センター衛生課長","answer":"次に、ご希望の方につきましては、検便を行いました。最後に、ケースによっては医学的な判断が必要だということで、所長が医学的な見地からの相談も受け付けておりました。","id":"exchange-013"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、入院なさったとかではなく、具体的に検便等で、とりあえずは収まったということなんか尋ねました。","respondent":"平澤品川区保健センター衛生課長","answer":"私どもの受け付けた相談で、入院等、重篤な事例はございませんでした。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問","question":"保健所でも、食の安全ということで監視員に回っていただいたり何かしています。教えていただければ、そのあたり、いかがか尋ねました。","respondent":"平澤品川区保健センター衛生課長","answer":"そこで、２月２２日、国は、関係閣僚会議で申し合わせ事項というものを発表いたしました。具体的な中身はまだ不明ですので、それを拝見いたしまして、私どもでできることから取り組んでいきたいと考えています。","id":"exchange-015"},{"speaker":"須藤委員","kind":"意見","question":"もし品川区であったらどうなんだという思いがちょっとあったので、保健所との連携はとれているのかどうか、説明を求めました。","respondent":"平澤品川区保健センター衛生課長","answer":"２４時間対応ということで、私、または保健所の衛生課長のほうに通報が入ることになっております。これは千葉のほうでどのような対応をされたのか、何らかの検査を実施する方向で、いつも対応しております。","id":"exchange-016"},{"speaker":"須藤委員","kind":"意見","question":"２９日の夜ということで、７時半という時間外の時間に連絡をいただいて、体制がとれるようにご努力をお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１０年間で３.７倍に増えて、全国の国公立私立の１万１,５００校のうち５７０校の、改めて驚いたんです。先日の一般質問の中でもされて、輸入品はどういう状況になっているのかということを、ちょっと教えていただきたい。","respondent":"小林保育課長","answer":"１００％ないのかと言われると、生産国を含めました表示をすべてされているわけではありませんので、若干危険なところはあります。加工食品も含めた、こういった、現在問題になっております冷凍食品等は少なくとも一切使っていないということでご理解いただきたいと思います。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これからも、ぜひ、それは貫いていただきたいと思うんです。表示されていないというもの以外は使われていないということなのか、そこら辺のところを、わかる範囲で教えていただきたい。","respondent":"小林保育課長","answer":"わかる範囲で使っているものはないと考えております。","id":"exchange-019"},{"speaker":"高橋委員","kind":"質問","question":"そういうのをどのように区民に伝えようと思われているんでしょうか、先ほど、品川区で回収等がある程度決着がついたという。広報の仕方というんでしょうか、何というんでしょうか、それは。","respondent":"平澤品川区保健センター衛生課長","answer":"先ほど、ご説明した中に一部含まれてありますが、自主回収が終わった段階で、区のホームページ等を通じまして、できる限りの情報提供をしていきたいと考えています。","id":"exchange-020"},{"speaker":"高橋委員","kind":"質問","question":"ホームページもいいですけれども、見ない方もいらっしゃるので、何かほかにプラスアルファしていただけるとありがたいと思うんです。広報「しながわ」とかに出すんでしょうか、もし何か方法がありましたら、お考えいただけたらありがたいと思います。","respondent":"平澤品川区保健センター衛生課長","answer":"事件性、このまま私どもの自主回収の予定期間である平成２０年３月３１日をもってはっきりするのかどうか、非常に難しいと考えています。これだけ回収して、申しわけございませんけれども、３月３１日の状況を見て判断させていただきたいと考えています。","id":"exchange-021"},{"speaker":"宮崎副委員長","kind":"質問","question":"ちょっと伺いたいんですけれども、相談を受け付けるということだと伺ったんですけれども、区としてやることは大体こんなものなんでしょうか。そういうことがあるのか、大体このぐらいで終わっちゃうのか、そこら辺のところはどうなんか尋ねました。","respondent":"平澤品川区保健センター衛生課長","answer":"１月３０日で、東京都のほうで回収いたしまして、この検査を実施しております。体調を崩された中で、東京都のほうにあります健康安全研究センターのほうに持ち込みまして、食材の検査を実施するということになります。","id":"exchange-022"},{"speaker":"宮崎副委員長","kind":"質問","question":"例えば、区民との関係では、体調を崩したとなると、もうちょっと何か、保健所として検査をする内容がそろっているのか。あるいは、今回の場合は検便ぐらいでいいと判断したのか、そういうところはどうなんか尋ねました。","respondent":"平澤品川区保健センター衛生課長","answer":"今回ありました三つの事件、１０人の被害者が出ていらっしゃるわけですが、体調を崩された方が全国で５,０００人を超える訴えがございました。私どもで対応している中身で、お預かりしまして検査をする、こういった流れになっております。","id":"exchange-023"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/993548?Template=document&Id=3196#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":21868,"voices":66}},{"id":"h20-20080226-8","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"建設委員会","time":"午前１０時０３分～午前１１時４９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件整理しています。","topics":[{"id":"topic-01","title":"東急大井町線の急行運転の開始","agenda":"東急大井町線の急行運転の開始","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それから、監視員をしばらくの間配置するというお話ですけれども、時間帯というんですか、どの時間帯に置くのか。そもそも東急がなぜ急行運転を始めたいのか、その説明も一緒にお願いします。","respondent":"阿部都市計画課長","answer":"それから、当面の間ということですけれども、東急のほうは３カ月程度ということを申しておりました。ただ、踏切のところの警備員につきましては、ちょっと聞いておりません。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"ホームドアの話はぜひ進めるべきだと思うので、東急のほうに伝えていただきたいと思うんですけれども、その点が１点。この間の経過も含めて、ちょっと教えていただけますか。","respondent":"阿部都市計画課長","answer":"戸越公園１号踏切というのは開設前の踏切ですが、警備員を配置するということと、自動放送装置を設置するということになっています。３月に開かれる校長連絡会で、もし沿線の学校以外で説明会をやってくれという要望があれば、東急が対処するということになります。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"安全対策も強化していただきたい。警備員は３カ月という話ですけれども、もっと時期を検討すべきだと思うんですけれども、いかがか尋ねました。","respondent":"阿部都市計画課長","answer":"表示もして、通過しますというような表示もするということですので、改めて東急に対して、さらに追加の安全対策を求める考えはございません。申し上げましたとおり、また東急もしていくと言っておりますので、改めて東急に対して申し入れをするということはないと思います。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"現状の安全対策ではまだまだ不安だという声があるのは、ぜひ、受けとめていただきたい。３カ月でおしまいではなくて、状況を見ていただいて充実すべきだなと思いますので、最後に意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"配置が３カ月程度ということですが、自動放送装置というのもしばらくの間ということですが、これも同等の期間と考えてよいのでしょうか。それから、小学校に対する説明会のやり方なんですけれども、子どもたちに座学でやるのか、それとも現地でやるのかというのは、おわかりか尋ねました。","respondent":"阿部都市計画課長","answer":"それから、先ほど申し上げましたけれども、沿線の学校につきましては、個別に東急のほうで、まずは学校に行って説明をいたします。それは個別に対応するという東急の話ですので、まずは学校に行って話をして、その後の周知の方法は学校によって異なるのかなと思います。","id":"exchange-005"},{"speaker":"阿部委員","kind":"質問・要望","question":"学校からの要望ということではあると思うんですけれども、現地でないとぴんと来ない学年というのもあると思いますので、東急のほうからも。どちらも要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問","question":"時間帯によっては出てくるんじゃないかと思うんですが、その影響について、東急のほうから何かコメントがあるんでしょうか。駅と駅の間の１区間が短いだけに、もし東急のご見解なりがありましたら、説明を求めました。","respondent":"阿部都市計画課長","answer":"確かに、委員ご指摘のとおり、全体の本数も増えますし、急行と各駅停車ということになりますので、踏切の遮断時間が若干長くなろうかと考えています。ただ、現在もそうですけれども、常時閉まったような状態の踏切は出てこないかなと思います。","id":"exchange-007"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、それは東急のほうに、そういうふうに感じた部分もありますよということは言っていただきたいなと思います。そういうことについての検討というのは、どうなんか尋ねました。","respondent":"松代管理工事課長","answer":"何とか来年度、拡幅に向けて実施できるような計画を、今やっと進められるかなと思っています。そういった意味で、安全対策を図っていこうと考えているところです。","id":"exchange-008"},{"speaker":"三上委員","kind":"質問","question":"今、大崎高校のほうで、歩道側のほうに、お互い歩行者が通るというケースが多いわけですよ、自転車も。お互いに踏切の中でぶつかり合っているわけですから、むしろ、このことのほうが事故が起きる可能性は高いと考えたほうがいいんじゃないか。","respondent":"松代管理工事課長","answer":"今、おっしゃることは、今後、もっときちんとやりますけれども、基本的には、全幅員が大体６ｍぐらいと考えています。交差しないような形といったことを、路面表示を含めて、していければと思っています。","id":"exchange-009"},{"speaker":"井上委員","kind":"質問・要望","question":"今のお話で、先々に計画されているということでしたけれども、そういう踏切については、早急に検討をしていただきたいということを要望します。それから最後に、警備員の配置ですが、荏原町駅なんかは、上り下り両方に配置されるということか尋ねました。","respondent":"阿部都市計画課長","answer":"踏切の片方に警備員がつくような形だったと思います。１人ということです。","id":"exchange-010"},{"speaker":"井上委員","kind":"質問","question":"では、踏切の両側に上下線が走りますよね。ということは、立っている方というのは、どういう任務を持って立っているんか尋ねました。","respondent":"阿部都市計画課長","answer":"要するに、くぐったりそういうことをしないように、当然通るわけですから、来ますよということです。あっちゃいけないことですけれども、そういうことがないように警備をするということです。","id":"exchange-011"}]},{"id":"topic-02","title":"小関橋架替整備工事委託契約の変更","agenda":"小関橋架替整備工事委託契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"地中障害物と言ったらいいんですか、専門知識がないのであれですけれども、コンクリートの固まりというのは人工物になるんですか。何でそんなものが地中から出てくるのか、産業廃棄物とは言えないのか、その辺、どういうことなのか、ちょっと教えていただけますか。","respondent":"青木都市開発課長","answer":"実際にあけてみましたところ、２ｍ四方ぐらいの固まりで、下水管を保護するような形で囲い込むような固まりがあったということです。下水管等につきましては、特に精度を高めた事前の調査などを行うということなく施工した結果として、このような変更をお願いするものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"質問","question":"４億円の増額ということで、金額も大きいのでもう少し伺いたいんですけれども、下水道管をつくったときに保護するために工事が行われたわけですよね。その辺は、なぜなんか尋ねました。","respondent":"青木都市開発課長","answer":"予定しなかったものを撤去するために時間を要した結果として、今、ここで変更のお願いをするということが是か非かは別としまして。わからなかったかによって工事金額が変わるということではないと考えておりますので、その辺は正しくご理解をお願いしたいと思います。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"改めて、調査をしてあるかどうかわからなかったというのではなくて、初めからあったものを、いわば東京都との連携の中で出てこなかったのかなと。そういう図面で、どこに何があるかというものはわからないんか尋ねました。","respondent":"岩田まちづくり事業部長","answer":"現場段階で何か出た場合には詳細な設計をやり直して工事を進めていくというのとシミュレーションをかけまして、そういう通達が来ております。","id":"exchange-014"},{"speaker":"阿部委員","kind":"質問・要望","question":"この場所から大変近いところに住んでいるものですから、非常に矛盾であると思うし、どうなのかなというのが１点です。それが、ずっとそれを使い続けるということで、４年間ぐらい使うことになるんですかね。","respondent":"青木都市開発課長","answer":"平成２１年の上部工での工期が長くなっている部分の説明ですけれども、実は、夜間工事も想定しておりました。この変更が何とかなると、そういった形で、工期の延長についても周知を図っていきたいと考えています。","id":"exchange-015"},{"speaker":"阿部委員","kind":"質問・要望","question":"詳しい説明を、ありがとうございました。その現地に看板でちょっと説明をつけるとか、住んでいる人だけではなくて、使っている皆さんにわかるような仕組みを考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"水はとりあえず全部入ってこないわけですから、工事はやれる。２年に１回あるか、１年に１回あるか、そういうことをやろうという考えにはならなかったのか。","respondent":"青木都市開発課長、岩田まちづくり事業部長","answer":"もう少しやれば終わるので、６月半ばまでいいでしょうか、７月だったらどうでしょうかというような協議をしてきたのは事実です。今後、変なご質問をいただいただけに変な答えになっちゃいますけれども… そういう合理的なものごとですべてをきちっと割り切れない部分がありますので、おそらく、検討の俎上に上げること自体がかなりきつい話だと思います。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういう前例を踏まえると、日本はこういう方法をとりたがる、とったほうがいいんだろうということで、こういう提案をされた。ただ税金が上がってこんなんでどうのこうのみたいな話をされても困るので、そこら辺を踏まえて、しっかり答弁をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"阿部委員","kind":"確認","question":"今の東京都がかなり強行だったというお話を伺っていまして、そうせざるを得ないんだろうと思いますが、ちょっと１点だけ確認させてください。この１３億円から１４億円というこの金額のうち、区の負担はどのぐらいなんか尋ねました。","respondent":"青木都市開発課長","answer":"お金の出所の話ですけれども、ほぼ２分の１が国からの補助金です。残り２分の１が、区の直接の費用というのは、結果的にはゼロになります。","id":"exchange-019"},{"speaker":"阿部委員","kind":"質問","question":"増額分も含めて、ほぼゼロということでよろしいか尋ねました。","respondent":"青木都市開発課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"}]},{"id":"topic-03","title":"東急目黒線連続立体化事業および武蔵小山・西小山駅前広場整備事業","agenda":"東急目黒線連続立体化事業および武蔵小山・西小山駅前広場整備事業","exchanges":[{"speaker":"井上委員","kind":"質問","question":"まずお聞きしたいんですけれども、そういうのは、そういうところはどのように考えているのか。新しく植える１２本について、１２本のうちの倒木の可能性のある本数は何本なのかということを、まず説明を求めました。","respondent":"浜脇街路事業担当課長","answer":"ちょっと説明の仕方が悪くて、変更後を見ていただきたいんですけれども、保存できるのは１５本です。今、現在、移植する予定ですし、もう数本については、公園とか、他の畑のほうに移植が終わっております。","id":"exchange-021"},{"speaker":"井上委員","kind":"質問","question":"質問のほうが、ちょっとおかしかったのかなと思いますので、もう一度。１６本が今の現状から失われるということについて、樹木医の判断によって、その本数の内訳を教えてくださいという質問です。","respondent":"浜脇街路事業担当課長、松代管理工事課長","answer":"それは、先ほど言いましたように、古いので、２回も移動はできないという判断によるものです。新しいものを植えるということです。事前に根回しということをしまして、２ｍぐらいのところで根を切りまして、その樹木をまた新しい場所に少し深めに植えるような作業もいたします。","id":"exchange-022"},{"speaker":"井上委員","kind":"質問","question":"桜の木を残してほしいという、車中心の道づくり、まちづくりをしなければいけないというのにはすごく疑問を感じています。どうでしょうかと住民の方に説明をして、私たちがその意見を集約して、こういったところで判断ができるという仕組みのほうが正当だと思うんです。","respondent":"松代管理工事課長、岩田まちづくり事業部長","answer":"そういったところで、今回、対応をしたです。説明等につきましては、こういった事情でやむを得ず変更せざるを得ないという説明をしていくという立場で進めているところです。 今回の補助３０号線につきましては、従来から、議会に対しては逐次ご説明を申し上げているケースだということです。説明会をやる前には、こういうことを住民に説明しますというご報告をした上で、地域の住民に説明をし。","id":"exchange-023"},{"speaker":"井上委員","kind":"意見","question":"もう委員会を通っていますから、議会はもう承認をされていますからというようなことではないように。どこでどういうふうに変更ができるものかというのが、そこのところは説明を聞いて、きちんと声を生かしてほしいと求めました。","respondent":"岩田まちづくり事業部長","answer":"３月になりますと住民説明会をやりまして、本委員会にもきちっとそれを説明した上で進めていくことは、当然のことだろうと考えています。若い木であっても、移植した場合の活着率、要するに移植して生き残る確率は５割以下と言われております。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問","question":"杉と違って、そういう意味では、極端に短いですからね。いわゆる二世、三世という形で、引き続き地域で愛着を持てるということが広がっているという話は伺ったことがあるんです。","respondent":"藤田道路公園課長","answer":"ですから、そういった意味では、クローン的な技術というのは進んでいると思うんです。今回みたいなケースは、やはり別な場所に植えて、街路樹の形にふさわしいような桜の木を持ってくるというのが一般的なやり方かなと考えております。","id":"exchange-025"},{"speaker":"中塚委員","kind":"意見","question":"だから、いわば新規に植える木を、そこの木の苗木からとったものだという工夫というのがあってもいいんじゃないかなと。ぜひ、そういうことをご検討くださいということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"須貝委員","kind":"意見","question":"新しく持ってきたときに、バランス的にどうなのかなと。細い樹木から始まっていくのかと思うんですけれども、できるだけバランスがとれた樹木を選定して植えていただけるとありがたいなと思いますとの意見を述べました。","respondent":"浜脇街路事業担当課長","answer":"３１本中１５本が何らかの形でしか残らないと、１６本がなくなっちゃうということで、雰囲気を壊さない程度のものを持ってくるよう努力をします。","id":"exchange-027"},{"speaker":"三上委員","kind":"意見","question":"２枚目のグリーンの矢印なんだけれども、対面通行の矢印の右、左は逆にすべきじゃないのかと。ちょっと修正していただいたほうがいいんじゃないかとの意見を述べました。","respondent":"浜脇街路事業担当課長","answer":"この辺につきましては、説明会には、ご指摘がありましたように直して出します。ありがとうございました。","id":"exchange-028"},{"speaker":"阿部委員","kind":"質問","question":"すみません、説明のときに聞き漏らしたのかもしれませんけれども、一方通行の逆転化、これは何月何日から行われるのか、周知方法と、周知期間を教えてほしいと求めました。","respondent":"浜脇街路事業担当課長","answer":"その予定ですけれども、工期につきましては、ビラとか看板で、工法が変わりましたということを、当日前後にお知らせしたいと考えています。説明会の中では、４月１日を目途にということで、ご説明をします。","id":"exchange-029"},{"speaker":"阿部委員","kind":"質問・要望","question":"感覚的に、車がどっちから来るというのが逆転するわけですから、慣れるまでは非常に危険だと思います。その辺は、強く周知方を図っていただくよう要望します。","respondent":"浜脇街路事業担当課長","answer":"当面につきましては、看板もやりますし、当然、ガードマン等もつけます。こういう交通規制になりますということについては、周知を図りたいと考えていますので、やってまいります。","id":"exchange-030"},{"speaker":"阿部委員","kind":"意見","question":"さらになんですけれども、その中で、例えば、古い標識がちょっと残ってしまったりとか、あるいは、反対に向いた道路の表示ですとか、そういったものが残ってしまうととても混乱のもとになりますので、そういうこともあわせて、気をつけて。","respondent":"本多委員長","answer":"本件を終了いたします。","id":"exchange-031"}]},{"id":"topic-04","title":"分譲マンション維持管理相談事業の実施","agenda":"分譲マンション維持管理相談事業の実施","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"どういうふうに相談に応じてくれるのかということで、中期、マンション自身が長く使えることにも結びつくわけですよね。相談業務の中で、どういうふうに相談員がアドバイスというか、力を貸してくれるのか、その辺、ちょっと教えていただけますか。","respondent":"齋藤住宅課長","answer":"収入も、世帯も、構成も全然違う、年金暮らしで１０万円というのがなかなか出せない。管理会社ではなくて、自分たちで設計図を書いて幾つか見積もりを出してもらうとか、こういうようなところまでご紹介できるです。","id":"exchange-032"},{"speaker":"中塚委員","kind":"意見","question":"１００年使えるマンションにするには、どういう管理、そこを悩んでいるそうなんです。ぜひ、いろいろお力を貸していただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"井上委員","kind":"質問","question":"初回のみ無料とするということですけれども、２回目以降そのまま継続して契約がされるかどうかというのはなかなか難しいものがあると思うんです。２点、説明を求めました。","respondent":"齋藤住宅課長","answer":"駐車場の問題、そういった法的な対応をどうすればいいですかというのは、月２回のマンション相談会を使えます。それは無料ですので、そういう形で、マンション管理費に負担がないように制度化したということでご理解いただければと思います。","id":"exchange-034"},{"speaker":"井上委員","kind":"質問・要望","question":"どういうふうに相談をしようかというような話だったら、１回目に、きちんと対価をお支払いすべきじゃないかと思ったんです。そこの無料にした考え方を、もう少し明らかにしていただきたい。","respondent":"齋藤住宅課長","answer":"ただ実際に、業務が、耐震補強だとかに移るようになったら、マンション管理士１人ではできませんし、専門の工務店、建設会社に相談しなきゃいけない。これのコーディネーターになれば、当然、契約の対価としてもらえる、こういうふうに考えております。","id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"では、整理すると、仕事あっ旋的な発想が、マンション管理士たちの出会いの部分については、そういうことでボランティアの考え方ということでよろしいんか尋ねました。","respondent":"齋藤住宅課長","answer":"犬、猫の問題、駐車場に勝手に使用しているという違法駐車の問題は、普通の第２、第４の水曜日にやると、こういうふうにお願いしています。要するに仕事をさせるためにやると、こういうものです。","id":"exchange-036"},{"speaker":"井上委員","kind":"質問","question":"申込み方法は、電話で随時受け付けているのは区の住宅課で、その６名のマンション管理士会に、どなたか行ってくださいというつなぎをするということでいいか尋ねました。","respondent":"齋藤住宅課長","answer":"そのとおりです。","id":"exchange-037"}]},{"id":"topic-05","title":"の所管質問","agenda":"の所管質問","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"東京都の検討の動きというのはどういうものなのか、経過も含めて、そこをもう少し詳しく教えていただきたいということです。","respondent":"齋藤住宅課長","answer":"平成２０年度の当初から、所管の窓口は都市整備局資産課というところが窓口になって、局内ＰＴで活用策を検討する。具体的に東京都でどのような活用策があるのかは、今後、都市整備局のほうで検討されますけれども、幾つかアイデアは寄せられていると聞いております。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"この資料で見ると、東京都での、住宅施策等での利用の有無、ここはもう決まったのかどうか、今、どの時点なのか。そこを教えていただけますか。","respondent":"齋藤住宅課長","answer":"これは平成２０年度当初で、この４月から実際のＰＴが始まる。今、ちょっと言いましたが、ＰＴの窓口のところに、もう幾つか活用策を提案したいという声が、都市整備局の中で来ているという話を聞いております。","id":"exchange-039"},{"speaker":"中塚委員","kind":"質問・要望","question":"私としては、ぜひ区移管で区営住宅をつくってほしいということは変わらないんですけれども、経過の中で地元区の意向確認というのが来るわけですよね。さらに地元区の意向の確認が来たら、ぜひそこで手を挙げていただいて、区営住宅の増設を進めていただきたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/759088?Template=document&Id=3904#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":32316,"voices":105}},{"id":"h20-20080226-9","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"文教委員会","time":"午前１０時０２分～午後０時０３分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"の近隣セキュリティシステムの運用事業者変更","agenda":"の近隣セキュリティシステムの運用事業者変更","exchanges":[{"speaker":"西本委員","kind":"質問","question":"もしも将来的にソフトバンクが何か起きたときに、すぐ違うところに乗りかえられるとか、そういう準備というのはできないものなのか尋ねました。","respondent":"市川庶務課長","answer":"基本的に、私のほうで委員のご質問に対して説明できる立場にございませんけれども、伝えるべきことは伝えします。先ほど私の説明の中で、それで平成２０年度からどちらの通信事業者にするかというところ、その辺の壁が少し低くなってきているように見受けられます。","id":"exchange-001"},{"speaker":"西本委員","kind":"質問・要望","question":"ちょっとお願いしたいんですね。例えば来年度１年間かけて開発をお願いするとか、そのときにお金が発生するかどうかわかりませんけれども、どうぞ伝えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"特定通話サービスと所在地確認サービスを受けている方々が、この際、伺っておきたいと思います。八潮の地域ではどういうふうになっているのか、そういう地域がもしほかにあるのであれば、実際にわからないので教えていただきたいなと思います。","respondent":"市川庶務課長","answer":"１点目の、近隣セキュリティシステムの、システムの企画開発自体はＮＰＯのものづくり品川塾というところで行いました。４番目のソフトバンクの携帯電話網の利用状況というんですか電波状況、いろいろアンテナを増設したり、技術的にカバーをして競い合っているようです。","id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"これは意味がないと思ったので、改めて確認させていただきましたけれども、違いがよくわかりました。ものづくり品川塾とＹＯＺＡＮとの関係というのはどういうふうになっていくか、もしわかっているところがあれば教えてほしいと求めました。","respondent":"市川庶務課長","answer":"最後にご質問いただいた点につきましては、ちょっと私のほうで承知しておりません。","id":"exchange-004"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"そこの調和というんですか、そういう足並みはどういう形でしていけるものなのだろうかなというところ、それについてお聞きしたい。でもなかなかいろいろな障害をお持ちのお子さんがいらっしゃるものですから、それに従わないというか、数に入れていませんという。","respondent":"河野指導課長","answer":"３番目の質問の親の認識との関係になるんですが、障害受容ができている親は、そういう形でほぼ１００％情報提供に対して了解をしてくださいます。来年度以降も継続して実施したいという方は、すべて予定をしているＮＰＯのほうに登録をし終えたというふうに聞いております。","id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"どういう体制になって実施していただけているのかというのを、ちょっと具体的な部分としてまず一つ伺っておきたいなというふうに思うんです。送迎は当然小さな低学年の子どもは特に、そういう点についてはどういうふうな考え方で臨んでおられるのか、そこもあわせてまず聞きたいと思います。","respondent":"河野指導課長","answer":"ただ、平成２０年４月より源氏前小学校のほうに、新たに情緒障害を対象とした通級学級を設置するということで前回お話をさせていただいたところです。それからこういう特別支援学級も含めて、特に登下校のための便宜ということについては、私どものほうも考えておりません。","id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"その辺の状況のつかみぐあいは教育委員会としてはどういうふうになっているのか。ちょっとそこをまず伺いたいというふうに思います。","respondent":"河野指導課長","answer":"通級に通っている子どもの保護者の方から、登下校に関する送迎の要望というようなことについては、私たちのほうに入っておりません。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"現実的には子どものことを知っていただいている方がついていただくのが一番いいわけですから、そういうケースも結構あるというふうに聞いています。それがＮＰＯになると１年契約ではなくて、その辺については、ちょっとどうなのかを改めて教えてほしいと求めました。","respondent":"河野指導課長","answer":"それから、いままで年間契約というふうな委員のご発言でしたけれども、年間契約ではなくて６カ月を限度に契約をしていく、こういう形です。それが、今回このＮＰＯになることによって、継続雇用が可能になるです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"子どもにとって、信頼をかちとれている介助員、そういう方々がＮＰＯに登録をしたにしても、そういう形を通して、一人の子どもから見たときに同じ介助員が来年度以降も継続して当たってもらえるのかという点について質問しているつもりですけれども、ご答弁をお願いします。","respondent":"河野指導課長","answer":"できるだけそういうような形で配慮したいと思いますが、その方があくまでも、どういう形でＮＰＯに参加しているのかということにもよりますので、継続して、年度を超えてやっていただける方については、できるだけそういう配慮をしていきたいというふうに思います。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"どうしても一部の担当者だけに任されてしまっている部分もあるやに聞いております。これからもさらに積極的に教育委員会として進めていただきたいということを強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"金野委員","kind":"確認","question":"これは年４回あって全部中身が同じで、果たして１回の研修で全部を知ろうというのはこれは無理なことかなと、この辺どうなんでしょうか。先生たちが研修する、その先生たちも時間をとるのが大変だというのはすごくわかるような気がするんですが、その辺はどうなんか尋ねました。","respondent":"河野指導課長","answer":"３点目の先ほどの教員の研修でございましたが、今日、私は３０分かけて特別支援教育の概要と区の取り組み状況までお話をさせていただきました。","id":"exchange-011"},{"speaker":"市川委員","kind":"質問・要望","question":"二つお聞きしたいんですけれども、１ページ目の特別支援教育の対象が、品川区の場合の数字を教えていただきたいとうことです。ＡＤＨＤというようなものが、その辺の取り組みというのはどういうことをやっているのか、この二つをお聞きします。","respondent":"河野指導課長","answer":"中学生、公立の学校に通っている子どもですが、およそ１万６,０００人ぐらいかというふうに私のほうで認識しております。あるいは区の広報等を通じて、区民全体に向けて啓発をしていきたい、そういう趣旨で担当部局とも連携してまいりたいというふうに考えております。","id":"exchange-012"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"１点確認をさせていただきたいのですが、やはり保護者がそこで気づくか気づかないかだと思うので、そこで相談に行けるように。３ページぐらいにこの巡回相談の専門医や心理カウンセラー等、そこの部分で、それをＩＴ化するということでよろしいんか尋ねました。","respondent":"河野指導課長","answer":"これは単に学校だけの問題だけではありませんので、区全体としても広報等々も連携協力しながら啓発に努めてまいりたいというふうに考えております。","id":"exchange-013"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"目を通すのが億劫になってしまうのかなということで、ぜひわかりやすいものをつくっていただき、そして啓発活動をより活発にしていただければなと。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"金野委員","kind":"質問","question":"このＩＴシステム化の今説明を伺ったんですが、そうなると、このカルテ化をしていくとなると個人情報というところでは大丈夫なんでしょうか。そういうシステムを使うということはすごくいいとは思うんですが、どうなんか尋ねました。","respondent":"河野指導課長","answer":"セキュリティーについては、これはもう万全を期すつもりでおります。あるいは学習支援員を配置する、そういう意味での個人情報のやりとりについては、当然保護者の方の了解をとるというふうに予定しております。","id":"exchange-015"},{"speaker":"南委員","kind":"意見","question":"私も今のところであれっと思ったんですけれども、いわゆるＮＰＯが雇用した人を各学校に派遣して介助していただくと。ちょっとその辺の具体的な状況がどういうことなのか、ちょっと違うんじゃないかなと思うので、その辺をとの意見を述べました。","respondent":"河野指導課長","answer":"要するに支援員、例えば朝、それに対して具体的に予定していた支援内容を急激に変更しなければならないというようなケースについて。こういうことだから、予定していた作業内容を、こういう部分をこういうふうに変更してくださいと。","id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"そうでない場合は大いにあり得るわけですから、身分との、そこをはっきりさせておきたいと思って聞いているんです。だから、私は今の説明では大いに起こり得るのではないかなというふうに思うので、それだけちょっと心配で確認しているところです。","respondent":"河野指導課長","answer":"ちょっと私も認識が甘い部分があって、緊急の場合には事後承諾でオーケーということだそうです。それから、経過を観察しながら具体的に組み立てていくということがこれからの特別支援教育の大事なポイントであるというふうに考えております。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"やはり大前提として信頼関係がなければいけないわけですから、そこのことを言ったので、誤解されていたのであれば訂正をしておきたいと思います。どこでそういうふうになっているのか、公的にはこういうケースの場合は事後承諾でオーケーだという、そういうことなんか尋ねました。","respondent":"河野指導課長","answer":"そういう具体的な内容については、委託の際の仕様に基づいて行うということで、あらかじめそういう旨を盛り込んだ仕様というふうになっておりますので、可能であるです。","id":"exchange-018"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ品川区でもつくっていただきたいという希望があるものですから、全体的につくるとか、ちょっと考えていただきたいなと思います。非常にいいパンフレットだったので参考になると思います。","respondent":"河野指導課長","answer":"その件については、これは教育だけの問題ではなくて、児童課、保育課のほうも関与してまいりますし、さまざまな部署が絡んでまいりますので、連携をしながら検討してまいりたいというふうに考えております。","id":"exchange-019"},{"speaker":"南委員","kind":"質問・要望","question":"勝島に求めていく、そういうバスを確保することが財政的な事情でできなくなったということで、そういう報告を受けたと。その辺の状況がどうなのか、事実なのかどうか、そこを確認したいと思います。","respondent":"古里学務課長","answer":"それに向けて、私どもとしても予算編成段階でいろいろと検討をしたところですけれども、設定をしていないということが現実です。活動の範囲をあまり広げることなくできる方策、こちらのほうを検討することが重要かということで、今その方向で検討しています。","id":"exchange-020"},{"speaker":"南委員","kind":"確認","question":"いいのかどうかの確認と、そこについては保護者の方々にそういう方向で検討しているということは同時に知らせているんでしょうか。その点について、長くやるつもりはありませんので、ちょっと簡潔に伺いたいと思います。","respondent":"長田教育次長","answer":"統合にかかわる説明会の中で、そういう要望、クラブ活動において特定の場所が使いたいというような要望が出てきたのも事実です。それに向け、検討はしてまいりましたけれども、要望はありましたけれども。","id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"その件は、ほかのときでもいいんですが、また改めてよく調べてから質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/612972?Template=document&Id=4628#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":34625,"voices":66}},{"id":"h20-20080226-5","meetingId":"h20-cm02","date":"2008年2月26日","dateIso":"2008-02-26","committee":"総務委員会","time":"午前１０時０２分～午前１１時４０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"意見","question":"平成１９年度のときに激変緩和措置の問題ですとか、幾つか東京都が挙げて５％にするんだということだったんですけれども、その辺のどういうところで合意に至らなかったというところの協議の中身というものをお聞かせ願えないかなと思いますとの意見を述べました。","respondent":"日下部企画財政課長","answer":"これは災害だけではなくて、いろいろなそれぞれ特別な事情があるケースに柔軟に対応できるようにしたほうがいいだろうというのが１つ。それと、その辺も特別交付金で対応せざるを得ないということで、今回もやはりその点がお互い１つの一番大きな争点になりました。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"今後も協議は続いていくんでしょうから、論議として実際問題としてどこまで続けるのかというとおかしいのかな。どこかで打ち切らざるを得ないのかというその辺の考え方はどうか尋ねました。","respondent":"日下部企画財政課長","answer":"より現実的な決着の１つの目安を立てるとすれば、２３区も最後までどうしてもノーだと言うわけにいかなかったというのはそういう経過もあります。そういうことがおそらく２３区の区長の頭の中にもすべてあるのではないかと考えています。","id":"exchange-002"},{"speaker":"土井委員","kind":"質問・要望","question":"というのがそこら辺ちょっと考え方も含めてお伺いしたいのと。どういう考え方に基づいて加味した額というのは決めるのかというのをちょっと知らせていただきたい。","respondent":"日下部企画財政課長","answer":"１点目の方針、主語がないというご指摘です。それはそのあり方も含めてご指摘の点ももっともだと思いますし、その辺は今後検討していく必要があるのかなと受けとめてあります。","id":"exchange-003"},{"speaker":"土井委員","kind":"意見","question":"法律用語にまでありますから、だれがだれをどうするのかさっぱりわからないのがありますよね。意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-004"},{"speaker":"伊藤委員","kind":"確認","question":"確認といいましょうか、５ページにある基準財政需要額の算定のところで、災害危険度の上位に入ってしまっていますよね。その考え方１つで財整調整の額も変わってくるわけですから、また当然見直しもかけていくんでしょうから、この２つをお聞きしたい。","respondent":"日下部企画財政課長","answer":"例えばさっきご説明申し上げました４ページに基準財政需要額で再調整の中で退職手当費というのがあります。それ以外のものということになってまいります。","id":"exchange-005"},{"speaker":"伊藤委員","kind":"質問・要望","question":"となれば、財政調整協議の中で求めていくということは１つの方向性だと思うんですけれども、そのことについてお答えをもう一度いただきたい。いろいろな法改正もあったりするわけですから、直近のいろいろな状況は反映されないわけですから、それがいつ。","respondent":"日下部企画財政課長","answer":"たしか３月に正式な決定通知が参りますけれども、もう年明けからは今度は平成２１年度の新年度の財調協議に向けた動きも同時にスタートいたします。最大限そこで算定できるような取り組みもあわせてやっていくことが重要だろうと考えております。","id":"exchange-006"},{"speaker":"土井委員","kind":"意見","question":"それによって出てきたものがどこかにあるはずなんだけれども、あるのかないのかわからないんだけれども、平成１９年度はどうなったのかなと。その当初算定残額というのに当たるのか、そこに含まれているのか、どうなのかとの意見を述べました。","respondent":"日下部企画財政課長","answer":"当初算定残というのはあくまで普通交付金のほうの算定残です。４ページの当初算定残とはちょっと別の性格のものだというふうに理解をしております。","id":"exchange-007"},{"speaker":"原委員","kind":"質問・要望","question":"一番大きいのは法的な収益性のものが発生するじゃないですか。保険の関係とそこだけわかれば教えていただきたい。","respondent":"中島経理課長","answer":"施設の管理関係、私どもでやっておりますのでお答えしますけれども、施設を使用するということで当面イコール管理もしていくですので、当然建物等につきましては必要な保険等に加入していくということになろうかと思います。","id":"exchange-008"}]},{"id":"topic-02","title":"改めまして２の所管事務調査、都と区の関係における諸課題","agenda":"改めまして２の所管事務調査、都と区の関係における諸課題","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"どうしても確認したいのが、結論をいつまでに導き出そうとしているのかという確認をしたいと思っていますので、そのことの話を伺いたいのと。その２つを聞かせてほしいと求めました。","respondent":"日下部企画財政課長","answer":"確かに４４４項目をこれから４月以降、検討するとなると大変な作業にはなりますけれども、その辺は２３区は一生懸命頑張っている。つまり、事務配分の検討が終わってから区域のあり方に移るということではなくて、途中からその辺をにらんだ上で区域のあり方について検討を進めて。","id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問・要望","question":"やはりそのことについては区長からも答弁をいただきたいと思うんです、大きな話ですから。場合によっては、これは具体的に話が煮詰まっていく段階であれば、いわばいろいろな事務が理事者によってまた見えてくるわけじゃないか尋ねました。","respondent":"本間副区長","answer":"まさにおっしゃる状況にあるわけなんですが、そもそもこの検討の進め方の基本的な考え方というのはきちんと整理はされております。今、何とかそのステージの中できちんとした整理ができるものということで考えているところですので、ひとつご理解のほどよろしくお願いいたします。","id":"exchange-010"},{"speaker":"伊藤委員","kind":"質問・要望","question":"こと東京都が相手な話ですから、今までいろいろな歴史があって、場合によっては区側が勝ったり負けたりしてきたことがあった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"土井委員","kind":"質問","question":"そういう意味での区側の意志統一というようなものが、どういう形で急いで進められつつあるのか。いや、都でよろしくお願いしますなんていうのが出てきちゃったらおもしろくも何ともなくなっちゃうので、その辺はいかがなんか尋ねました。","respondent":"本間副区長","answer":"それから検討委員会ということで持ち上がっていくですので、それぞれの区の整理、全部のその辺は回答しているという状況はあります。実務的な水面下でのそういう実務はきちんと進んでいるということは申し上げられるという状況です。","id":"exchange-012"},{"speaker":"土井委員","kind":"質問","question":"ただ、先ほども言いましたように、おしりが引っかかっているものですから、そこに上下水道というでかい課題が残っているわけですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"菊地委員","kind":"質問","question":"考え方、まさに上下水道みたいな大きなものも含めて確定をした際に、今の財政調整制度で単純に財源をぽんと上乗せをして進めるものなのかどうか。そこをお聞きしたい。","respondent":"日下部企画財政課長","answer":"それは今の時点でどうするこうするという話にはなりませんけれども、おそらくそれはそういう４４４がどういう形になるか。それを踏まえて今度は財政上の問題をどう整理していくのか、そういう一定の幅の中で整理を図ってみようという形になるのではないかと思います。","id":"exchange-014"},{"speaker":"武内副委員長","kind":"質問","question":"これについてはどのような展開というんですかね、例えばそれ全部区のほうで新たに足りない分を採用してやるのか。どんなようになっているんでしょうかね。","respondent":"日下部企画財政課長","answer":"かつてのことを考えますと清掃事業、これが移管をされた。比較的そこまでいかないような、そういうものも考えられますので、今の段階ではちょっとどういう形になるかはまだ予測はつかないという状況です。","id":"exchange-015"},{"speaker":"武内副委員長","kind":"質問・要望","question":"別に都から来てもらわなくても区で受けられるんだとか、そういう人のこともやはり考えていかなければいけないのかなという気もするんですね。そういうのもまた検討してほしいと求めましたので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"林委員長","kind":"質問","question":"その他ありますでしょうか。〔「なし」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/325034?Template=document&Id=1778#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":31014,"voices":60}},{"id":"h20-20080227-14","meetingId":"h20-cm02","date":"2008年2月27日","dateIso":"2008-02-27","committee":"行財政改革特別委員会","time":"午前１０時０３分～午後２時００分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件整理しています。","topics":[{"id":"topic-01","title":"の契約のあり方に関すること","agenda":"の契約のあり方に関すること","exchanges":[{"speaker":"阿部委員","kind":"質問","question":"それにしても何か評価基準のつくり方の枠組みみたいなものはあるんでしょうか。１つの質問として、評価の基準のつくり方と、それから最低限の、これとこれとこれは必須みたいな考え方はあるかどうか、説明するよう求めました。","respondent":"中島経理課長","answer":"この評価基準ですけれども、これは各所管で定める実施要領に基づきまして定めてあります。基本的な業務に対する考え方とか、実施体制とか、この辺については必ず確認するということになってあります。","id":"exchange-001"},{"speaker":"阿部委員","kind":"質問","question":"結局受託したところが仕事をやり切れなくて、委託を業者の側から返してもらったと言ったらいいんですかね、そういうことがあったかと思います。実績の重視の仕方ですとかが変わってくるんじゃないかと思うんですけれども、その仕事による分類みたいなことはされているんか尋ねました。","respondent":"中島経理課長","answer":"実績は２３区内で学校給食の、自校方式の学校での実績があるかどうかということを基準の１つとして定めておりまして、学校での実績があったです。","id":"exchange-002"},{"speaker":"阿部委員","kind":"意見","question":"学校給食のほうなんですけれども、要は当該の業者は確かに２３区内の別の学校で実績があったと。基準に何か足りないものがあったと考えるべきだと思うんですけれども、その辺についてはどういったことが今後必要だと思われますかとの意見を述べました。","respondent":"中島経理課長","answer":"学校での実績もございましたし、保育園での実績もありまして、相当高い評価を受けている事業者でございました。学校の調理業務の委託が実質継続困難になったということで聞いてありますので、そういったところに問題があったということではないと聞いております。","id":"exchange-003"},{"speaker":"阿部委員","kind":"質問","question":"ですから、まさにそこだと思うんですね。要は１人いなくなったら回らなくなるような業者であれば、さらに別の評価項目も必要なんじゃないか、そういう話です。","respondent":"中島経理課長","answer":"あった場合に、業務を保証してくれる協会等があるわけですけれども、そういったところでの応援は実際的には要請していないと聞いてあります。あるいは指名する場合に、指名するかどうかということは、この業者につきましては１つの判断材料になるのかなとは考えてあります。","id":"exchange-004"},{"speaker":"阿部委員","kind":"質問","question":"その中で現場が２人いなくなったから、この規模でとか、そういう全体のルールにしていったほうがいいんじゃないか。やっぱり１人やめたから、今、やめるなんていうことはよくあるわけですから。","respondent":"中島経理課長","answer":"今、委員のご指摘がございましたので、今後、当然そのことも含めまして、検討していかなければいけないのかなと思ってあります。まだ検討しなければならない部分というのは当然あろうかと思いますので、今後その辺も含めまして、十分検討させていただきたいと考えています。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問","question":"この資料の学校給食についての評価基準と、戸籍証明の郵送の評価基準とありますけれども、この評価基準そのものは、冒頭に説明のあった事務の流れの中のどこで使われるものなのか、それをまず説明いただけますか尋ねました。","respondent":"中島経理課長","answer":"この評価基準を使うところですけれども、１ページ目の資料の右側の主管課の部分のところの中段ぐらいですけれども、審査委員会の開催になってございまして、そこに履行能力等の審査ですけれども、この中でこの評価基準を使いながら審査を行っていくです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"この審査委員会の開催の中で、それぞれこの評価基準、今日の資料をもとに評価していくということなんでしょうか。どういう形なのかご説明いただきたいのと、５０点満点という話もあったんですけれども、評価基準の基準というんですかね。","respondent":"中島経理課長","answer":"１点目の審査委員会のメンバーですけれども、面接をして、それでもって一人ひとりの委員の役割はその場で終わるです。面接をしながら、ヒアリングをしながら、その配点票に基づいた形で採点をしていくです。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"３なのか、５なのかというものと同時に、その必須のものがあるのかないのかご説明いただきたい。評価の仕組みは何を基準にどう確認しているかというのがいまいち説明の中で見えてこないので、ご説明いただけますか。","respondent":"中島経理課長","answer":"それと、評価基準の中で必須というか重要なものとして考えているのが、これはどこの課もそうですけれども、実施体制ですね。何人ぐらい配置する予定なのか、その段階では、この業者につきましても十分この業務を遂行できるという判断をヒアリングの中でしたものです。","id":"exchange-008"},{"speaker":"中塚委員","kind":"質問・要望","question":"欠員、異動が生じた場合、この「安定」というのはどのように確認するのか。客観的にどういうふうに確認をするのか、そこがまだまだ不十分なのかなと思うんですけれども、いかがなんか尋ねました。","respondent":"中島経理課長","answer":"１点目の総括のお話ですけれども、先ほど阿部委員のご質問にもお答えしましたけれども、もっと追求していく必要があると考えています。例えばヒアリングの中で実施体制を確認して、その中で私どもが、あるいは信頼できるんじゃないかという要素は実績ではないかと考えています。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"でもほかにも事故、災害、学校との交流、どれ１つとっても欠かすことのできない体制だと思うんですね。説明がどうも説得感に欠けてしまうんですけれども、ぜひその配点票を見せていただきたいと思うんですけれども、いかがなんか尋ねました。","respondent":"中島経理課長","answer":"現時点でこの配点票を公表するというふうには考えてございませんので、そういった意味では非公表というんですかね、公にはしてございません。考え方として、先ほど申し上げましたように、実施体制について一番大きな要素を持って考えているです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここは必須だと思う点、その物差しというのは客観的なものですから、その理由をもうちょっと教えていただきたいんですね。その採用がどうだという話ではなくて、その物差し自体にまた問題があったら困るわけですから、そこを僕らはチェックしようがないんですよね。","respondent":"田中総務部長","answer":"例えば先ほど大間窪小学校の話がございましたけれども、そこで問題になったのは、2)にあります欠員・異動等があった場合の体制をどう考えているか。","id":"exchange-011"},{"speaker":"武内委員","kind":"質問","question":"今のところ、この戸籍証明の関係と学校給食の調理代行のこの２つの事業を、この簡易型の総合評価方式でやっていらっしゃるんですか。それともほかにまだやっているかどうか。","respondent":"中島経理課長","answer":"まだほかにもやってございまして、今年につきましても、すまいるスクールとか、そういった関係の事業につきましてもやっておりまして、今後徐々に拡大していきたいという考え方です。","id":"exchange-012"},{"speaker":"武内委員","kind":"質問","question":"というのは、今のところは多分やっていないんでしょうけれども、行く行くは工事案件なんかも考えていくということなんですかね。","respondent":"中島経理課長","answer":"平成２０年度に向けて、１件になるのか２件になるのかあれですけれども、試行的に今回実施していこうという考え方です。","id":"exchange-013"},{"speaker":"武内委員","kind":"質問","question":"それと履行能力ですか。そういった場合というのは、まず予定価格自体が超えちゃうと、履行能力があろうがなかろうが、すべてそれは失格になっちゃうんか尋ねました。","respondent":"中島経理課長","answer":"先ほどの流れ図の中でございましたけれども、まずは価格を出してもらいましたら、評定が終わるまで価格は開きません。ですから、予定価格を公表していますので、実質的に予定価格を超えるような事業者があれば参加してこないということになりますので。","id":"exchange-014"},{"speaker":"武内委員","kind":"質問","question":"いろいろな学校改築とか、そういった中で、業界においてはちょっと心配されている部分もあるようなことも伺っているわけですね。それとも価格は価格でだめであっても、例えばそっちのほうを基準として業者を選定することができるのかどうか、そこをお伺いします。","respondent":"中島経理課長","answer":"予定価格につきましては、予定価格を超えて契約することができないとなっていますので、そういった価格の入札があった場合には、実際の評価点が例えば５０点満点だったとしても、その事業者につきましては失格にするです。","id":"exchange-015"},{"speaker":"林委員","kind":"意見","question":"総合評価を入れにくいネックになっている部分があって、取り入れられなくて、たまたま簡易型という形。こんなのじゃとても入れられないなという実態も聞かせてもらったんだけれども、国のほうの動きというのをまず聞かせてくれますかとの意見を述べました。","respondent":"中島経理課長","answer":"総合評価に関しましては国で先行してやってございまして、特に地方がなかなか導入できないという一番大きな要素は、学識経験者のかかわり方です。","id":"exchange-016"},{"speaker":"林委員","kind":"質問","question":"品川区で取り入れられるかどうかわかりませんけれども、品川区の実態に合ったというか、いい方法を考えておいてほしいと思います。今日もらった資料の中で幾つかお聞きしていきますけれども、上から４行目、５行目、公告をして公募型の採用をするか、指名型にするか。","respondent":"中島経理課長","answer":"平成１９年度行いました試行の中では、指名型と公募型両方実施しています。実際にその区分けですけれども、原則的には３,０００万円以上の予定価格につきましては公募型で実施する。","id":"exchange-017"},{"speaker":"林委員","kind":"質問","question":"３,０００万円を境にどちらかを採用する。それは経理課で、それとも主管課でということなんか尋ねました。","respondent":"中島経理課長","answer":"実際に戸籍の事務につきましては、予定価格が３,０００万円を超えていましたけれども、指名型でやってあります。これは業務が特殊というか、戸籍のパンチ入力なんかもありますので、そういった戸籍関係の業務を経験しているところを中心に指名をして実施したです。","id":"exchange-018"},{"speaker":"林委員","kind":"意見","question":"価格点と技能点と分かれると、そっち側を点数をつけていくんだけれども、この審査票というのは一体どういう、大ざっぱでいいです、ここにないので。次の２枚にあるような、基準に沿ってここをこういうふうに書きなさいよとか、そういうふうになっているのか、ちょっと簡単に説明を求めました。","respondent":"中島経理課長","answer":"審査票につきましては、委員ご指摘のとおり、評価基準に沿った形で質問をして、それに書いてもらうという形で現在運用しているです。","id":"exchange-019"},{"speaker":"林委員","kind":"質問","question":"そうすると、例えば戸籍の方は、戸籍証明の交付にあたっての注意点等の考え方はどうですかという、例として。そういう織りまざったような審査票になっているわけか尋ねました。","respondent":"中島経理課長","answer":"そういうことです。各所管によってつくり方が若干違っておりまして、さまざまそれは工夫しながら、あるいは事業者が書きやすいようなものにして書いてもらっているです。","id":"exchange-020"},{"speaker":"林委員","kind":"質問","question":"ヒアリングをするというから、その場で私は一生懸命やりますよとか、単純に言うと意欲をあらわしてもらう。それを斟酌するということになるわけか尋ねました。","respondent":"中島経理課長","answer":"ちょっと言葉が的確かどうかあれですけれども、審査票で出していただいたものの裏付けをとるというか、本当に書いたとおりできそうかどうかというのを、５人の部課長が見ているわけですから、そういった中でいろいろなことを聞きながら、その辺を判断していくです。","id":"exchange-021"},{"speaker":"林委員","kind":"質問","question":"業者のヒアリングの中で話すことへの判断能力だとか、それから、その会社に対する基準以外のところの評価点というのかな。学識経験者という形で外部の方が入るということは、１つのステップにならないかなという気がするんですけれども、いかがか尋ねました。","respondent":"中島経理課長","answer":"今、委員の言われる審査委員会そのものに学識経験者を入れちゃうということも１つの考え方であろうかと考えています。そういった諮問をして回答をもらうという形で、審査委員会に直接加わっていただくということには施行規則上はなっていないです。","id":"exchange-022"},{"speaker":"林委員","kind":"意見","question":"これだけが審査票に書いてあるとすれば１６問あるわけで、その１６問に、１番目はこういうふうに思っていますということなんだろうと思います。区のいわゆる職員以外の感覚を持った人が入るというのは、僕はプラスがあると思うんだけれども、その辺をちょっと聞かせてくださいとの意見を述べました。","respondent":"田中総務部長","answer":"そういうものも聞きますし、そういうものをいろいろなファクターに合わせて判断をしているという内容で現在、進めしています。あるいは評価のファクターに対する採点といいますか、そういうものを精査しながら、いい契約ができるようにしていきたいという考え方です。","id":"exchange-023"},{"speaker":"林委員","kind":"質問","question":"もう１つ、これからも指名、随契という比率は変わらないと僕らは理解しておいていいんですか。品川区の契約あるいは発注ということに関して、指名の比率が上がるということは考えられないんか尋ねました。","respondent":"田中総務部長","answer":"事業者の方が説明に来るときに、それからやりとりを私どもがいたしまして、評価をするのが一番のポイントかと考えています。これから検討すべき課題ではあるかなと考えていますが、その所管にかかわらない関連の課長を別途必ず入れるように今度の要綱では定めしています。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"要綱のところを見ましたら、審査委員会による審査の１１条の２のところに、審査委員会は原則として事業者に対し評定に必要なヒアリングを実施する。ヒアリングを行わない場合もあるのかどうか、実際にどのくらいの時間をかけてこのヒアリングが行われているのか、ちょっとその辺を説明するよう求めました。","respondent":"中島経理課長","answer":"原則的にはヒアリングを実施していくですけれども、それはヒアリングを実施しなくてすることができるという意味での原則です。あるいはヒアリングする業者の数によっても当然変わってありますけれども、大体２０分から３０分ぐらい時間をかけているのかなと考えています。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"具体的にどういうところがあるのか、そこを教えてほしいのと、一生懸命探したら。二、三十分くらいで形式的に流れてしまうんじゃないかなと思われるんですが、その点はいかがか尋ねました。","respondent":"中島経理課長","answer":"一番最後の時間の関係ですけれども、ヒアリングは１社２０分から３０分ということで考えて実施しています。それとヒアリングを実施する、ヒアリングをしなくても判断できるという業務があるのであれば、それはやらないこともできますよです。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういう不正をこのところでどうチェックができるのかなというところを１点教えていただきたいのと、配置基準は妥当であるか。5)のアレルギー食への対応が適切に行われるかという、この適切の判断というのはどういうふうにされるのか、ちょっと説明を求めました。","respondent":"中島経理課長","answer":"今後の問題として、先ほど林委員のご質問にも総務部長がお答えしましたけれども、今後の検討すべき課題であると考えています。それとアレルギー食の関係ですけれども、そういった学校の定めたアレルギー食対応ができるのかどうなのかということを判断するです。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の配置基準のところなんですが、何食を何時までにつくってほしい。その辺までも含めて把握をしていくというのが、責任ある体制であるのではないかなと思いますが、その辺はいかがか尋ねました。","respondent":"中島経理課長","answer":"人数だけで言いますと、食数にもよりますけれども、１名から２名多い体制で実際はやっているとは聞いてあります。それにつきまして予定価格を提示しているですので、あとはそれぞれ予定価格のものを幾らで入札してくるのかということになりますけれども。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"質と賃金というのは比例をすると思うんですね。その辺を１点と、あと６番目の安心できる考え方をしているのかどうかと、その点はいかがか尋ねました。","respondent":"田中総務部長、中島経理課長","answer":"私もある１つの部内の審査委員会のほうで経験したんですが、こういう業務に何年従事されているか、ヒアリングをさせていただいたりしています。私どもは会社がどういうふうにこの業務を… 先ほどの条件の中で２３区内の学校給食の実績があるということと同じように、代行保証制度の契約をしていることがこの参加の条件になっているです。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"労働環境というところまで、先ほど総務部長は会社の内部にまでは立ち入れないと、これに入らないと責任持ったことはできないんじゃないんでしょうか。だから、総務部長の会社の内部には立ち入れないというそこのところは、そうではないと思うんですが、いかがか尋ねました。","respondent":"田中総務部長","answer":"それを会社自体でどう対応できているか、あるいは審査票の中でチェックをしてやっているのが私どもの審査のやり方です。これはあくまで会社の内部に立ち入って、幾らもらっているから安心だとか云々という問題ではないのかなと認識しております。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"その辺をもう１回確認と、あと本当に品川区のところで再委託がないのかどうか、そういうチェックって本当にされているのかどうか。人材派遣がもしも業者のところに入っていたら再委託になると私は考えているんですけれども、いかがか尋ねました。","respondent":"中島経理課長、田中総務部長","answer":"再委託の話ですけれども、委託全般の中で、一部、元請けというんですかね、請けたところが一部委託するということは可能だと考えています。 これはいろいろな面である場合もあります。２の1)に人員数（有資格者数）、配置基準、それをきちんとした評価の中でやっているという内容です。","id":"exchange-031"},{"speaker":"山内委員","kind":"確認","question":"確認をさせてください。それから案件によって違うんでしょうけれども、大体何社くらいの業者が選定され、またその選定をされる方はどなたなのかということを説明するよう求めました。","respondent":"中島経理課長","answer":"３,０００万円以上で指名する場合につきましては、指名選定委員会というものを開いて、そういったものを通して指名していくです。それとそれ以下の金額が少ない場合の指名につきましては、契約係のほうでさまざまな業者の中から条件を提示しながら指名していくです。","id":"exchange-032"},{"speaker":"山内委員","kind":"質問","question":"先ほど総務部長の説明の中で、そうしますと、例えば新規参入したいという業者がありますよね。なかなか参加できないというか、そういうことになりかねないのかなとちょっと私は想像したんですが、その辺の兼ね合いというのはどうなんか尋ねました。","respondent":"中島経理課長","answer":"指名してみて、実際にどのくらいの価格で入札するのかということも含めて、少しずつ拡大していくということは考えながらやっているところです。","id":"exchange-033"},{"speaker":"山内委員","kind":"質問","question":"そうしますと、そういう業者が例えば窓口にいろいろな説明を受けたいといったときは、そのような形で説明というか、そのようなことをしていただけるようなサービスというのはあるんか尋ねました。","respondent":"中島経理課長","answer":"その辺の説明はするのと、多少困難な部分があるんですけれども、その辺は説明をさせていただきながらやっていくということです。ただいわゆる営業活動につきましては、契約の窓口で受けたらきりがございませんので、それについては受けてはございません。","id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"１点だけ、先ほどのやりとりから。先ほど飯沼委員からのご質問の中で、虚偽申告のチェックはという質問があって、それについてはお考えを説明するよう求めました。","respondent":"中島経理課長","answer":"虚偽することは悪いことなんですけれども、虚偽の中身というんですかね。ただ今、ただ契約のもともとの約款等で対応できるところはありますけれども、少し要綱等でもその辺を整理させていただければと考えています。","id":"exchange-035"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"審査票に書いてもらうのは、例えばこの左側の４項目ぐらいを審査票で書いてもらうということでよろしいですか。そこをちょっと確認したいと求めました。","respondent":"中島経理課長","answer":"項目のこの４つにつきましては最低書きますけれども、例えば実施体制の中で、そういった工夫はやってあります。ただ実際、これは基本的に業者の方に審査票の中で書いてもらう部分として、基本的にこのくらいの項目は審査票に記入していただいているです。","id":"exchange-036"},{"speaker":"鈴木（真）副委員長","kind":"意見","question":"事業者に全部、例えばもう１個の学校調理のほうで考えると、これだけの項目というのはかなりの部分を占めるよというのは出てくると思うんですね。事業者にとっては出ているかどうかで大分変わると思うんですけれどもとの意見を述べました。","respondent":"中島経理課長","answer":"戸籍で言いますと、基本的に要求要点につきましては、審査票の中に記入させていただいているです。","id":"exchange-037"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"最後に確認します。委員会に出ていますけれども、まずい書類というと変ですけれども、判断基準に影響を及ぼす書類ではないということで判断していいんか尋ねました。","respondent":"中島経理課長","answer":"審査票という形で出しておりますので、一部変わっている可能性もありますので、全く同じものにはなっていないです。基本的にはこの中身を聞いているです。","id":"exchange-038"},{"speaker":"鈴木（真）副委員長","kind":"確認","question":"点数は公表すると思うんですけれども、その審査の内容、こういうものだったよということも表には出ない書類なのか。要するにここに力点を入れて書けばいいという、虚偽じゃないけれども、重点項目が重く見えてしまう書類なのかどうかということで確認をしたい。","respondent":"中島経理課長","answer":"この評価基準は要領の中に載ってありますので、そういった意味では別に外に出ていっても、白紙の状態で出ていくことについては問題ないと考えています。","id":"exchange-039"},{"speaker":"高橋委員","kind":"質問","question":"２番の人的なところをちょっと重く見ようということはあったんですが、４番の事故・災害等緊急時の体制について、そのあたりをお聞きしたいんですが。","respondent":"中島経理課長、堀越行財政改革担当課長","answer":"先ほど総務部長もお答えしましたけれども、状況に応じて変更する必要があれば変更していくという内容ですので、変更する可能性があるのかなと思ってあります。それを受けて指定管理者についていろいろな評価に関する意見交換を所管のほうで行いまして、評価の実施、検証という形です。","id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"モニタリング・評価ガイドラインを平成１９年３月に策定して、今の説明ですと、今年の４月以降運用を開始するということでよろしかったでしょうか。今の現状、検討されているところを少し教えていただきたいと思うんですけれども、いかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"４月から実際にモニタリングという形で実施しているというものです。４月から実施ということで、平成１８年度の状況について事業報告書を受けて、実施状況の確認と評価という形で進めております。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"もう少しそこを詳しく教えていただきたいのと、運用改善に結びついているのか、その流れを教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"新しいサービスの展開について、新規のサービスの検討を始めたりですとか、そういうサービスアップについてもお話を伺っております。ですから、そういう面も含めて、所管のほうでも受けとめて、今後の業務の改善という形で評価をしているというものです。","id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"その仕組みが議会のほうにはなかなか見えてこないので、ぜひもう少し教えていただきたいと思うんですね。利用者アンケートがどういう設問でどういう形でどういう実施がされているのかもあわせて教えていただきたいのと、いかがなんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"具体的には施設のいろいろな特性等に応じて工夫していく、つくられている、そのように認識をしております。利用者の方のご意向ですとか、そういったものについてもきちっと把握をしていく、そのような姿勢でこのような形でモニタリングを進めてあります。","id":"exchange-043"},{"speaker":"中塚委員","kind":"質問・要望","question":"そのアンケートを集約したものというんですかね、どういう傾向が、どういうアンケートが行われているか。わかるものは議会のほうに説明すべき、そういう仕組みをつくるべきではないのかなと思うんですけれども、いかがなのかということです。","respondent":"堀越行財政改革担当課長","answer":"区としての考え方、適しているのであろうと、そのような考え方で進めるべきではないかなと考えています。それと記載については、まだ始まったということで、そういうものについてはよりわかりやすい形ができるように工夫を図っていきたいと考えています。","id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の説明ですと、指定管理者自身がやっているアンケートを、なぜ出すことができないのかよくわからないので、そこをご説明いただきたいんですね。その難しい理由を教えていただきたいのと、実態がどうなのかというところを、そこもあわせて教えていただけますか。","respondent":"堀越行財政改革担当課長","answer":"それをそのまま区のほうに提出していただくということについては、一定いろいろな整理が必要なのではないかなという意味から申し上げたものです。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問","question":"伺っているのは、指定管理者自身が行ったアンケートをなぜ見せていただけないのかということなんですね。なぜそれを出していただけないのか、そこがわからないので、そこを説明するよう求めました。","respondent":"堀越行財政改革担当課長","answer":"今、コピーではないというお話でしたけれども、そのような現物に近いような形でお出しするというのはなかなか難しいかなと考えています。設置の責任者として、区としての一定の整理をさせていただいてご報告をする、このような考え方です。","id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"今の話ですと、統計的な傾向はお示ししていただけるということでよろしいのかということを１つ確認させてください。今の説明では納得できないので、個人情報とかそんなことを言っているわけではないので、ぜひそこはもう１度最後にご説明ほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"それぞれ施設の特性とか統計のとり方がいろいろあると思いますので、それは工夫を図るという意味で検討させていただきたいとお答えします。ご指摘のあった点については、今後のいろいろな課題の一つとして受けとめて、研究なり検討なりという形で進めていきたいと考えております。","id":"exchange-047"},{"speaker":"林委員","kind":"確認","question":"１つだけ確認させてください。それにこのモニタリングがどう生かされるか、金額については全く違うことで受託者との契約をすると理解しておいていいんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"５月あたりに評価をしたんですが、年間の実施状況を適宜見ていくという形になりますので、そういうのを次年度の計画に生かしていく。","id":"exchange-048"},{"speaker":"林委員","kind":"提案","question":"そうすると、予算編成ですとか財政側へのシーリングというか、事業部での提案みたいなものにこれが生かされる。それから企画財政課というところとどういう連携をとってこのモニタリングが生かされるのかという話をちょっと聞かせてくださいとの意見を述べました。","respondent":"福田企画部長","answer":"それからもう１つは、モチベーションをつけている場合があります。そういうものを総合的に勘案しながら、来年度の契約金額を査定、決定していく、これが大きな流れです。","id":"exchange-049"},{"speaker":"林委員","kind":"質問","question":"８月から９月にかけてというか、そういう時期で、ちょうど予算編成に入る時期だろうと思うんです。何のためにこれをやるかということが問われてくるわけですから、しっかり事業部経営会議というところで出るそうですから、きちんと内容。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"石田（慎）委員","kind":"質問","question":"１点だけお聞きしたいんですが、なぜ民間委託にすると経費が削減されるのか、その２つについてお伺いしたいんですが。","respondent":"堀越行財政改革担当課長","answer":"ほかのところとのいろいろなやり繰りですとか、そういったいろいろな部分を考えて、それなりに経費の削減というのが図れるものだと思います。","id":"exchange-051"},{"speaker":"石田（慎）委員","kind":"質問","question":"ぜひまずチェック体制をしっかりすることによって競争が生まれるのかなと思うので、ぜひ今後も一層チェックをしっかりしてほしいと求めました。以前、今後どのくらい出そうな見込みというか、もしわかったら教えてほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"年次協定を締結する際に、そういった中で、幾つかの施設で削減が図られた施設というのが上がっています。単純な比較というのはなかなか難しいんですけれども、同じようなベースで比較すると、削減の効果が見られているという状況です。","id":"exchange-052"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"これは要望なんですが、経費の節減というせっかく３つがありまして、ほかの業務にもぜひとも民間のノウハウ等を生かしていただければ思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"阿部委員","kind":"質問・要望","question":"先ほどのご答弁の中で、競争状態がないとというお話がありましたが、１つまず教えていただきたいのが、管理委託から指定管理者制度になったものの中で、従来の管理者がそのまま指定管理者になっているという比率というのはどのくらいかおわかりか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"総合体育館にいくと品川区スポーツ協会という形になっておりまして、公募という形でない例が、今のところは引き続きという形の例が多うあります。そういう考え方もありますし、公募をまずは基本として、事業者をしっかりと選定していく必要があると考えております。","id":"exchange-054"},{"speaker":"阿部委員","kind":"質問","question":"先ほど石田慎吾委員が聞いていたプラスの面がある一方で、どうしても手続的にブラックボックス化しやすいというデメリットもあるわけですね。ちょっと話を戻しまして、全体的なことについてお伺いしたいんですけれども、今後の見通しというのはどのようになっているんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"指定管理者制度に関する基本方針というものを平成１７年に定めておりますけれども、これを活用していく、これが基本です。ただ新規の施設等があれば、そういう形で活用していきたいと考えております。","id":"exchange-055"},{"speaker":"阿部委員","kind":"質問","question":"平成２０年度はこの８３施設のままである見通しでよろしいか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"平成２０年度は８３施設という形になります。","id":"exchange-056"},{"speaker":"阿部委員","kind":"質問","question":"多分総合的に利用者のよしあしを聞くような項目というのは必ず入っているんじゃないかと思うんですね。それについてさらにどこが悪かったのかを公に検証するようなことはできないかと思っているんですが、いかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"先ほど中塚委員のご質問にもお答えしましたけれども、これはセルフモニタリングの一環として事業者が行っているものです。そういうものも資料として、どのような形になるかはちょっと検討させていただきたいとは思いますけれども、指定管理者側とも協議をしながら。","id":"exchange-057"},{"speaker":"阿部委員","kind":"質問","question":"公のお金が入っているところについては、財務情報の公開を努力義務にしているような条例を持つ自治体も幾つかあると聞いております。個別の申請があったときにそれを出すかどうかというだけではなくて、基本的な財務状況などについては、その辺はいかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"区のほうで対応するという形で、区のほうで対応して、情報公開・個人情報保護条例にのっとった形で対応しているです。したがいまして、現時点ではそのような対応で進めていきたいと考えております。","id":"exchange-058"},{"speaker":"阿部委員","kind":"提案","question":"世の中、公のお金がどのように動いているかというのは、できるだけ公開するという方向に行っていると思うんですね。そういう意味では、その団体の基本的な財務情報ぐらいは、それについては特にそういう考えはないという意味でのご答弁だったんか尋ねました。","respondent":"福田企画部長","answer":"例えばバランスシートを策定して、そして区のバランスシートとともに公開する、こういう大きな国の流れがあると認識しております。考えてみますと、私としてはちゅうちょせざるを得ないなと、これが現状です。","id":"exchange-059"},{"speaker":"阿部委員","kind":"質問・要望","question":"その事業ということですから、単なる単発の、たまたま物品を購入してお金が入ったというのとはまたちょっと違っていると思うんですね。最後は要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"所管課の評価のところと検証が、９月に各所管のところで総括シートの検討がなされたと思うんですが、その辺は集約されているんでしょうか。中身をかいつまんでお知らせほしいと求めました。","respondent":"堀越行財政改革担当課長","answer":"はいろいろな総括シートをつくるまでの検討の状況がどうだったですとか、そのようなご意見をいただいていると聞いています。申しわけございません。","id":"exchange-061"},{"speaker":"飯沼委員","kind":"質問","question":"すごく大きな疑問であるのが１点と、総括シート１枚からでは、区が保有をしている資料をもっと議会に提供すべきであると思うんですね。その辺、とてもこの状況では議会での判断はできかねると思うので、もっともっと資料の提供が必要であると思うんですが、いかがか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"指定管理者のほうから自分でしっかりと認識をして、そういう部分も含めておおむね良好に管理をされていると、そういうものです。我々としては工夫をして、なるべくわかりやすい形で総括シートという形でお出しをするのがよりよいだろうと、そのように考えているところです。","id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"改善を重ねていただきたいのと、より透明性を高めるという意味では、議会が求めているものをきちんと出してほしいと求めました。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"武内委員","kind":"質問","question":"８３施設で指定管理者が実施されていると伺ったんですけれども、６２施設のモニタリング・評価なんですけれども、残りはこれからやるんですか。それとも何か理由があってやらないのか、その辺をまず説明を求めました。","respondent":"堀越行財政改革担当課長","answer":"平成１９年度は４月からスタートしておりますので、平成１９年度分についても、現場の視察ですとかを行いながらやっております。ですから、今年の同様の時期に、今度は８３施設という形で評価を行って、また同様にそれぞれ所管の委員会にご報告をするという予定でおります。","id":"exchange-064"},{"speaker":"武内委員","kind":"質問","question":"例えば宅建管理センターなんかのところでいくと、いわゆる管理運営の委託料、指定管理者料というんですかね。その半面、一定のところまでいかない場合には下げるという、そんな考え方なんか尋ねました。","respondent":"堀越行財政改革担当課長","answer":"実績が上がらなかった場合は逆にマイナスになるという場合も考えられますし、可能性としては、今申し上げられるのはそういうところが考えられます。ただ実際は所管に確認して、また後ほどご回答させていただければと思います。","id":"exchange-065"},{"speaker":"武内委員","kind":"質問","question":"そういった感じでインセンティブを与えていくということも１つの方策でいいと思うんですけれども、その中で押さえていかないといけないところは押さえていかなきゃいけないので、その辺のところをどのようにされているのかということをお伺いしたいと思います。","respondent":"堀越行財政改革担当課長","answer":"コミュニケーションをしっかりと指定管理者の側ととっていくという形を基本的な考え方にしております。委員ご指摘になったところも、今までもそうですし、これからも気をつけていきたいと考えております。","id":"exchange-066"}]},{"id":"topic-02","title":"の特定事件調査のまとめ","agenda":"の特定事件調査のまとめ","exchanges":[{"speaker":"林委員","kind":"質問","question":"特別委員会ですから、まとめというと、この資料でもうまとめになるわけ。ですから、あと２回か尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"林委員","kind":"質問・要望","question":"３月はないのか。そういう集約をしていっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"},{"speaker":"中塚委員","kind":"提案","question":"ただ行政に対していろいろ私も提案したいものがあります。いろいろ改善すべき点があるとは思いますので、どういう方向になるのか見えないので、自分の意見だけ述べさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-069"},{"speaker":"武内委員","kind":"意見","question":"私も提言をまとめていく方向でいいと思います。どうするこうする、これはどうするとなるのかちょっとわかりませんけれども、そういう方向でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-070"},{"speaker":"中塚委員","kind":"質問","question":"今、国保のほうではいろいろ調査していますけれども、住民税とか介護保険料のほうはなかなかそういうデータ的なものがないですからね。武内委員から、もし、中身があれば聞かせていただけたらなと感じます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"林委員","kind":"意見","question":"今月いっぱい、あるいは３月いっぱい、あるいは３月の半ばまでに委員長あてに各会派で提言すべき項目について出してください。今言った、１つの例としては委員長あてに会派がそれぞれ項目を出していって、最終的には５月にそれを１本にまとめられればでき上がるということの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-072"},{"speaker":"阿部委員","kind":"質問","question":"私もせっかくですので提言の形でまとめる方向でこれから頑張っていければいいと思います。やっぱり１年間やってきたこの議論というのがベースになった提言であるべきだとは思いますので、そういう形ではどうでしょうかと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問","question":"１年間、質問してご答弁いただいたり、よい方向に向くようにしていくのが大事であるなと思っています。今までのところをベースにしながらも、もしまとまらなかったときはどうするのかというあたりも、あわせて議論をしていくことが必要であると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"市川委員","kind":"意見","question":"１年間、いろいろここで勉強もさせていただきましたし、いろいろなご意見も聞きましたので、提言をするという方向でまとめたほうがいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"阿部委員","kind":"提案","question":"先ほど、確かに今までは審議というよりは勉強会に近いような内容であり、そんなに重量級の提言というのは難しいかなという気もしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/817079?Template=document&Id=5834#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":51172,"voices":162}}]);
